window.__D("text/imrei-bina/c001",{"p":[[1700400080,"דפעור בעבודת' להיות נמשך להם מפסולת העונג העליון כו' כנ\"ל והנה מבואר למעלה שבחי' מ\"ע שלפני הרקיע כו' נבדל בערך ממ\"ת בזה שאין שם שרש לבחי' עונג רע כלל וזהו יהי מבדיל בין עונג לעונג כו' והוא שרש התורה כמו שהיא קודם שנברא העולם שנאמר ואהיה אצלו כו' בחי' שעשועי' העצמיי' שבהעל' עצמותו והיינו בחי' המ\"ע דאורייתא גם לאחר שירדה מן השמים למטה ונקרא עץ החיים שמלובש בעה\"ד טו\"ר לברר בירורי רפ\"ח כו' כנ\"ל וזהו ונשב בגיא מול בית פעור כי בגיא זה הואיל משה לבאר את כל התורה כולה וחזרו על כולה לקבלה משרש' הקדום מפנימי' העונג העליון שבח\"ע הנקרא מ\"ע וזהו ממש למול ולנגד הקליפה דפעור כפנים של אדם שהוא מול העורף כך מה שנשב בגיא זה היה מול בבחי' עיקר הנקודה המנגדת לע\"ז דפעור וד\"ל ובכל הנ\"ל יובן ג\"כ מ\"ש כי לא על הלחם לבדו יחיה האדם כי על כל מוצא פי ה' יחיה האדם דהנה התורה נקרא לחם כמ\"ש לכו לחמו בלחמי תשב\"כ ותשבע\"פ וזהו עכשיו שירדה בעה\"ד טו\"ר לברר בירורים וה\"ז כמו הלחם שנברר ממנו הפסולת והמובחר עולה למוח ולב ועושה תוס' מוחין כו' וכמ\"ש ולחם לבב אנוש יסעד וקאי בלחמה של תורה דוקא [ולזה מכריזין אשרי מי שבא לכאן להנות מזיו עונג העליון דאצי' ותלמודו בידו שלמד בעוה\"ז דוקא כשמילא כריסו בלחמה של תורה הנגלית בתלמוד ופוסקים דוקא כמ\"ש במ\"א) ושרש התורה הוא בעה\"ח לחם מן השמים כמו המן (שלזה ניתן להם המן ך' יום קודם מ\"ת כמ\"ש למען אנסנו הילך בתורתי כו' פי' כדי שיוכלו לברר בלחם דתורה שבאה בעה\"ד כמ\"ש במ\"א)ומבואר למעלה דלחם מן השמים כמו שנקרא לחם פנג או לחם הפנים וכה\"ג הוא בבחי' אכילה עכ\"פ והוא בחי' עונג מורגש אבל במשה נאמר לחם לא אכל כלל וכעוה\"ב שאין בו אכילה כלל וכמ\"ש בזהר באתרי' לאו אורחי' למיכל כלל מטעם שהוא פנימיות עונג הנעלם בעצמות ממש כנ\"ל וזהו כי לא על הלחם לבדו וקאי בלחם דתורה (וגם כמו שהיא בשרשה בעה\"ח שנקרא לחם מן השמים שזהו המן שבו נאמר פסוק זה בפ' עקב למען הודיעך כי לא כו' יחיה האדם דלעילא שהוא בחי' ז\"א שממנו יבא לו מוחי' חדשים מפנימיות מוחי' דאו\"א אבל לא על הלחם הזה לבדו יחיה במוחי' חדשים הללו כ\"א על כל מוצא פי ה' דוקא והוא בחי' הדבור שבתורה שקול הדבור דתורה בו מלובש מעצמות שעשועים העליונים שבעצמות חכמתו הקדומה שלפני שרש כל האצי' כמ\"ש ואשים דברי בפיך לנטוע שמים עליונים וכתיב את ה' האמרת כו' ומוצא פי הויה דז\"א בתורה דוקא כמארז\"ל ג\"ש יושב הקב\"ה ועוסק בתורה בקול ודבור כו' ועי\"ז נמשך מהעלם העונג שבעצמותו בעונג עליון זה שבח\"ע שבתורה שנקרא לחם ולזה לא אמר שאין הלחם של תורה כלום רק שלא על הלחם לבדו עיקר כ\"א על כל מוצא פי ה' שבתורה יחיה האדם ע\"י הלחם (ובמשה שנא' לחם לא אכל היינו כמו לע\"ל שאין בו אכילה כלל רק מוצא פי ה' לבדו כמשמעו' פשט הכתוב הזה וקאי לע\"ל דכתיב יחיינו מיומים ע\"י לחם דתורה במוחי' דאו\"א ביום השלישי יקימנו ונחיה לפניו ממש כמ\"ש במ\"א):\n(ו) <b>והנה</b> מעתה י\"ל בפי' פסוק ראשון דק\"ש שמע שם ע' רבתי הנ\"ל דהנה כתיב כי עמך מקור חיים כו' ומשמע שיש מקור לחיי' העליונים הנ\"ל דכתיב ראה נתתי לפניך את החיים ואת כו' וממ\"ש כי עמך מקור חיים כו' משמע שיש גם בחי' מקור למקור החיים והטוב העליון שלזה אמר כי עמך מקור חיים כידוע ולהבין זה הנה תחלה יש להבין מהו ענין עיין רבתי דשמע בהיות מבואר למעלה [בסי' ג'] בפי' לך ה' הגדולה כו' שזהו בחי' עליות המדות שבלב דז\"א"],[1700400081,"דאצי' מדבור ומחשבה למדות עליונות דבינה דאצי' ששרשם ממדות העצמיי' דעצמות המאציל שנק' גדול וגבור כו' והוא ענין ע' רבתי דשמע פי' שם ע' היינו בחי' עליי' המ\"ל דאצי' שנק' דבור (וגם ד' רבתי דלא' בחי' מחשב') כידוע דשם הוא בחי' שם ב\"ן עם מספר רפ\"ח שעולין עמה גימ' ש\"ס ועולין בז\"ת דבינ' דעקודי' כו' שהוא באותיות גדולות שהוא הע' רבתי כו' ובאור הדברי' הנה מבואר למעלה די' מאמרות נמשכי' רק מהבל הלב ע\"י הקול ומח' שבמוח וכאשר באין עצם המדות שבלב לדיבור ומח' בהתחלקות צירופי אותיות אין זה רק כמו בחי' לבוש שפושט כו' משא\"כ עצם המדות שבלב ומוח שאינם בגדר חילוק אותיות עדיין וכנראה בחוש באדם שמתפעל באהבה לרעהו שהאהבה רוחניות היא ובלתי מוגבלת עדיין בחלקי' כלל דהיינו בבחי' אור עצמי ופשוט ואשר אנו רואים שיבא הארת אור האהבה בהסתעפות רבות וענפי' שונים כמו לעשות ריבוי טובות וחסדי' שונים לרעהו זהו הנק' חלקי אור נצוצות האהב' הפשוטה הזאת המגבילים אותה וכלא חשיבי לגבי עצם אורה ההיולי הפשוט שבוודאי א\"א שיבא כל עצם אור האהבה כמו שהיא בלב לידי כליון אורה בהתלבשו' מעשה החסדים וטובו' כי כל המעשה לא יגיע רק לאפס קצה אור האהבה וכמו\"כ התלבשות אור האהבה בכלי הדיבור והמחשבה וודאי כלא חשיבי לגבי עצמיות מהותה כי לא יוכלו לגלות עיקר הנקודה של האהבה הרוחניות שבלבו כמו שהיא לא בדיבור ולא במעש' וגם לא במח' וא\"כ בעלות התפעלות המדו' שבלב בדיבו' ומעשה וגם במח' הרוחניות לא האיר מהן רק אפס קצהו ולא כל עיקר נקודתם העצמית ולפ\"ז יובן ג\"כ למעלה במ\"ש לך ה' הגדולה בה\"א שזהו דבור ומח' כנ\"ל היינו רק עליות הארות של עצם המדות וענפיהן לבד הבא בגדר התחלקות וגבול ולא עצם מציאות עיקר נקודת' שבלב (וכמו\"כ התפעלו' עצם המדות שבמוח בינה כאשר נגבלין באותיות המח' שנק' מל' דתבונ' שזהו ד' רבתי דאחד כנ\"ל שזהו לך ה' הגודלה ה' עלאה כו') וזה ענין הז' קולות קול ה' על המים בחי' אור הארה בעלמא בקול הוי\"ה שבא מעצם אור החסד שבלב כו' קול הוי\"ה בכח עולה מאור עצם גבורה שבלב כו' (ועד\"ז עצם המדות שבמוח בינה בהתפעלות לזכות ולחוב כו' כשבאין באותיות מח' שנמשך ג\"כ בקול ודבור וחוזרין ועולין מלמט' למעל' כנ\"ל וזהו שמע שם ע' רבתי פי' כמו שם הוי\"ה דקול ה' על המים מבחי' עצם אור החסד שבלב כו' וכח שם זה אינו רק בחי' הארה בעלמא ועד\"ז קול ה' בכח מעצם אור הגבורה כו' כנ\"ל ולפ\"ז ענין ע' רבתי הוא עצם המדות שבלב טרם שיצאו לקול ומחשבה כו' וד\"ל אך הנה באמת הנה אנו רואים שגם בחי' התפעלו' המדות שבלב ומוח אינם עצמיי' ממש בלב ומוח דהיינו לא שתחילת עצם מציאותן בעיקר נקודתם נתהווה בלב אלא יש להם מקור מוצא שמשם נחצב עיק' מציאות נקודת' וכידוע שזהו ענין עצן המדות הנטועים ומושרשי' בעצם הנפש ממש כמו עצם מדו' הטוב והחסד הנטוע ומושרש בעצם הנפש ממש שמחמתו דוקא יש לו רצון וחפץ תמיד להטיב והרצון מוליד שכל ונתפעל גם בשכל לטוב ולזכות וכן להיפך מדת עצם הדין (כנ\"ל בענין חכמים המה להרע ולהטיב כו') (וכמ\"ש במ\"א בענין ז' שבתות תמימות כו' ובענין הלל ברכ' כו') וידוע שזהו מ\"ש באר\"ז דז\"א בע\"י אחיד כו' דעצם המדות שבלב שרשם בעצמות ממש שמשם מאיר אור התפשטות במדות שבשכל ובמדות שבלב כו' והיינו ממש ע\"ד הנ\"ל באור עצם המדות שבלב שמאירין בדבור ומח' ומעשה כו' דהנה כמו שמבואר למעלה בערך הארת הגבלת המדות במו\"ד וקול לגבי עצם המדות בלב כך הוא ממש ערך העצם התפעלות מדות שבלב לגבי שרש ומקור מחצב עיקר מציאות' בנפש עצמה ששם"],[1700400082,"הם נטועים בבחי' הילוי ועצמי פשוט בתכלית ורק בחי' אורן מאור בהתפעלות חו\"ג שבלב ומוח שהרי איש הטוב והחסדן בטבע עצם הנפש יתפעל בלבו לטוב וחסד הרי התפעלות זו לפי העת הארה מוגבלת היא ולא יכילו כלי הלב לעצם הטוב המושרש בנפש כמו שלא יכילו כלי המו\"ד לכל עצם התפעלות האהבה שבלב הרוחניות כנ\"ל ונמצא שעצם הראשון של המדות שבנפש הוא בחי' מקור למקור כי המדות שבלב נק' מקור היולי לגבי מדות שמאירי' במו\"ד וקול ועצם מציאות הראשון שלהם בנפש נק' מקור למקור זה שהוא המדות שבלב (ועיקר ההפרש בין מקור למקור למקור הב' הוא במה שבמקור הב' שבלב ומוח נחלק כל מדה לי' דהיינו רצון ושכל וחג\"ת כו' באופן מוגבל עכ\"פ בלב ומוח רק שהוא בבחי' הרוחניות בלב עדיין וכן במוח אבל בעצם מקור הראשון כל מדה היא בחי' היולי פשוט בלתי נחלק לי' עדיין להיות שאינה עדיין בבחי' אור וכלי כמדה שבלב ומוח והוא מדות שבבחי' יחידה שלמעלה מבחי' כלים המגבילים האור וכו' וראיה לזה הוא מה שאנו רואים דרך פרט כמו בעצם מהות טבע איש הטוב והחסד שבעצם נפשו כי טוב הוא בעצם (וכמו ותרא אותו כי טוב וכן אמרו צדיק כי טוב ונק' איש טוב בעצ') הרי לא יקרא שם זה עצם טוב על בחי' האר' וגילוי טובו הנגלה שזהו הנק' רק אור טובו וחסדו כמו ברצון לטוב ושכל לטוב שמה שיתפעל וירצה תמיד לטוב ויטה שכלו רק לטוב וחסד אין התפעלות הרצון והשכל הזה רק בחי' אור העצם הטוב כי עצם טובו הוא למעלה מן הרצון עדיין רק טוב היולי ופשוט וממיל' יאיר אור רצון ושכל תמיד לטוב כזיו המגלה העצם וכן להיפך מי שטבעו דין ואכזרי מאיר עצם מדה זו להיות לו רצון ושכל תמיד לדין וחוב היפך החסד וכן במדת הניצוח וההתפארות וכה\"ג מה שיוליד רצונו' ושכליי' למדה זו הכל נק' אור וזיו המוגבל מן העצם שלה המושרש בנפש שמשם נמשך תמיד וה\"ז ממש כערך גילוי אור אותיות במח' כשמהרהר לאהבה שבלב שנק' הרהורי לבו כנ\"ל ולא נק' זה שם העצם רק שם הפעולה אבל עצם הטוב נק' מה שכח טבע הטוב מוטבע בעצם בלתי רצון כלל עדיין והוא אשר יכול להיות ממנו כמה רצונות שונות עד אין שיעור לטוב ועדיין אין גילוי רצון בפרט משא\"כ כשאור העצם נגלה בלב מוכרח שיש בו רצון ושכל של חסד וטוב הבא בהגבלה רק שלא נגלה דרך פרט כל א' בפ\"ע עד שנחקקו באותיות דמח' ודיבור וכה\"ג וזהו הנק' אור וכלי שהאור מוגבל והכלי מוגבל משא\"כ במדות שביחידה שהוא בלא כלי רק עצם הנפש היא הכלי וחומר ושם אין המדה בגבול ושיעור לא בעצם ולא בהתפשטות שהוא ענין אור וכלי שנק' עצם והתפשטות דהיינו כמו שאין שיעור בעצם כך אין שיעור בהתפשטות והיינו מה שלא נחלק לי' כח\"ב כו' וד\"ל ולמעלה יובן מזה במה שאמר איהו וחיוהי חד שהן האורות דע\"ס הגנוזות בעצמות כמו שאין לו שיעור בעצם בכלל ולא בהתפשטות דאא\"ס בכלל עצם מהותו אין לו שיעור למעלה ואין לו שיעור להתפשטות למטה כו' כך פרטי מדותיו הכלולים בבחי' עצמיו' כמדות הנטועים בעצם הנפש בבחי' יחידה שכל מדה היא בבחי' א\"ס בב' דברים הללו שאין לו שיעור למעלה בעצם ולא בהתפשטות להתחלק לי' כנ\"ל ונק' מקור למקור כמשי\"ת (וכמ\"ש במ\"א בפי' ולגדולתו אין חקר באריכות) ונמצא מובן מכל זה למעלה בעצמות אא\"ס ממש שהמדות הכלולים בעצמו ממש הן בבחי' א\"ס ממש כמ\"ש ולגדולתו אין חקר וכן לתבונתו אין מספר וכה\"ג חסדי ה' כי לא תמנו כו' (וזה קאי בבחי' העצם כמו אין חקר ובין בבחי' ההתפשטות שזהו מ\"ש אין מספר להתחלקות וכן כי לא תמנו למטה מטה כו') וזהו ענין שמע ע' רבתי דפי' ע' רבתי באותיות גדולות מורה על"],[1700400083,"גדולת עצמות אא\"ס שמדותיו העצמיי' ממש כמשל המדות הנטועי' בעצם הנפש כנ\"ל אין להן שיעור למעלה מעלה כו' וכך אין להן שיעור בהתפשטות למטה וז' מדות הללו המה עצמיי' ופשוטים למעלה מהתחלקות עדיין ומה שנק' ע' רבתי ואות הע' כלול כ\"א מי\"ס היינו שכלולים בהעלם עדיין להיות שעתידין לצאת מן מן העלם עצמותן לידי גלוי במוחא ולבא ששם מתחלקי' לע' ממש ע\"כ הז' מדות נק' בשם ע' שכולל בהעלם כל התחלקות פרטיות שלהם כו' (והיינו מה ששיער בעצמו בכח מה שעתיד להיות בגילוי רצון כו' כדמיון החושב מה שיצייר שיש אופן מוגבל במח' איך לצייר אך א\"כ איך נק' עצמי' בלתי מוגבלים ודאי גם זה אמת דמצד עצמן בלתי מתחלקים ואעפ\"כ באין לידי גילוי והתחלקות שהוא כמו התפעלות הרצון שבאיש הטוב להטיב שמוכרח שיש בתחלה בעצם מקור להתפעלוק רצון זה בפ\"ע דוקא וכן מקור להתפעלות שכולו לטוב בפ\"ע ועכ\"ז עצם הטוב בלי התחלקות כלל וכלל וכמ\"ש במ\"א בביאור דבר זה המאמר מה ששיער בעצמו בכח כו' מאחר שבעצמו בחי' א\"ס ממש איך שיער בעצמו מה שבגילוי שהוא בא בהתחלקות וריבוי והתירוץ שב' מדריגות הן הא' ידיעת עצמו ממש והב' מה שבידיעת עצמו יודע לשער מה שחוץ ממנו ואע\"פ שאינה ידיעה שחוץ ממנו מ\"מ יתכן בזה מקור להתחלקות עכ\"פ ואעפ\"כ איהו וחיוהי וגרמוהי חד באין שינוי כלל וכלל כמ\"ש שם וד\"ל) ובכל זה יובן פי' כי עמך מקור חיים שהוא בחי' מקור למקור כנ\"ל דהנה י' מאמרות שמחיה העולמות בע\"ג נק' בחי' חיים התחתונים ובחי' מדות דזו\"נ דאצילות עם בחי' המוחין שבמדות נק' חיים העליונים דאצילות ונק' עץ חיים כלומר מקור להתפשטות החיות דעולמות שבא מגבול מבחי' הדבור העליון שזהו רק התפשטות האצילות כמשל פעולת תנועת גלוי חיות ביד מכח הפועל שביד שנק' כח המניע בשם עצם ונק' חי בעצם כידוע בפי' חי העולמים שהוא בחי' צדיק עליון יסוד ז\"א וכך הן כל המדות עד גם בחי' מוחין שבמדות דבינה וגם מדות שבחכ' נק' חיים העליונים כידוע דבינה דאצי' נק' ג\"כ אלהים חיים רק שהוא בבחי' חיים העליונים דז\"א ונק' חיי המלך כו' וכן כתיב והחכמה תחיה כו' אמנם יש בחי' מקור למקור דע\"ס דאצי' דהיינו בחי' מקור הראשון למקור השני לע\"ס דאו\"א זו\"נ דאצי' הנכלל בשם חיים העליונים וע\"ז אמר כי מעך מקור חיים פי' חיים הללו הן אורות וכלים דע\"ס דאצילות הגלויו' מהעלם עצמו' המאציל והגם שנק' מקור לחיים התחתונה אבל באצילות לא נק' מקור כלל כו' ומקור חיים העליונים דע\"ס דאצילות הוא בחי' ע\"ס הגנוזות בעצמו' שהן מדותיו העצמיי' כנ\"ל וזהו מקור א' ומקור למקור זה דהיינו לע\"ס הגנוזות בעצמות שנק' מקור חיים דאצילות ע\"ז א' כי עמך מקור חיים כלומר עמך בטל מקור הע\"ס דאצילו' הנק' מקור החיים והוא בעצמותו ממש דלאו מכל אינון מדו' כלל גם לא בהעל' (כנ\"ל דמה ששיער בעצמו בכח כו' הוא צמצום עצמותו ממש כו') וכערך גילוי התנועה מכח המניע כך ערך גילוי המניע לגבי עצם הנפש שמאירים בטרם שיניע וכך ערך גילוי עצם אור זה להחיות הגוף לגבי עצם הנפש בטרם שתחיה חיי בשר כו' נמצא ג' מדרגות יש כאן גילוי התנועה ועצם כח המניע בטרם שמניע ועצם אור החיות דנפש והד' עצם הנפש ממש וכך יובן למעלה בפי' כי עמך מקור חיים גם מקו' למקור חיים העליונים דאצילות המתגלה בבי\"ע שהן ג' מדריגות עד העצמות ממש הא' גילוי התפשטות האצילות בבי\"ע והב' אורות דע\"ס דאצילות והג' ע\"ס הגנוזות בעצמו והד' בחי' עצמו' המאציל ממש דלאו מכל אינון מדות כלל שע\"ז אמר לך ה' הגדולה כו' (שהרי גם הע' רבתי ג\"כ בטל בעצמותו ממש כמשל ערך ביטול עצם המדות שבנפש לגבי בחי' עצם יחידה שבנפש"],[1700400084,"עצמה כו' וד\"ל) ונכלל כל הנ\"ל בפי' מכלכל חיים בחסד פי' חיים העליונים דאצילות עושה כלי לכלי דאפיק י' תיקונין וקרא לון ע\"ס בהעל' וגילוי דאבי\"ע וכ\"ז רק מאור חפץ חסד היולי שבעצמות שעל' ברצונו כטבע הטוב להטיב כידוע במ\"א שחפץ חסד זה למעלה ממדת עצם החסד שבו וד\"ל:\n(ז) <b>ומעתה</b> יש להבין בטעם אות דלי\"ת רבתי דאחד שהוא כמו אות הע' רבתי ממש וכמ\"ש בזהר סי' לזה ע\"ד ה' כו' דכמו שהע' רבתי בעצמות מדותיו ית' כך אות הדלי\"ת רבתי מורה על בחי' איזה אור שבעצמות דוקא ולמה הוא בתיבת אחד באחרונה וע' רבתי בתיבת שמע בסופ' וכפי מארז\"ל ד' זה צריך להאריך בו כדי שתמליכהו בשמים וארץ וד' רוחות העולם כו' והנה מבואר בספרי הקבל' דד' רבתי זה הו' במל' דתבונה שמלבש' לתנה\"י דבינ' כמו שהמל' מלבש' לתנה\"י דז\"א כו' וי\"ל תחלה ההפרש בין בינה לתבונה דהנ' מבואר למעלה בענין ע' רבתי שהן מדות שבעצם הנפש ממש כטבע הטוב העצם באיש החסדן כו' ומה שמאיר מהן בהתפעלות המוח ולב נק' הארה מן העצם בלבד והנה ממדות שמתפעל במוח יובן במדות העצמיי' ג\"כ עד\"ז דהנה אנו רואים שבהתפעל אדם במוח לאיזה דבר הטוב ונאהב ה\"ז נק' אהבה שבמוח בינה וכן התפעלות יראה שבמוח או כעס וניצוח וכה\"ג והתפעלות זו מתלבשת מיד במחשב' והרהור דוקא שכמו שהתפעלו' המדות שבלב אוי\"ר כו' מיד יבאו לידי הרהור במוח ונק' הרהורי לבו כך ממש התפעלות המדות שבמוח בינה יבאו מיד בהתלבשות במח' ונק' מח' זו בשם מל' דתבונה המלבשת להתפעלות מדות שבמוח בינה שיבא בה בבחי' בולט להרהר בכמה אופנים מוגבלי' ושונים מאד ע\"ד דוגמא התפעלות היראה ופחד במוח בינ' מאיזה דבר יעשה לבושים שונים בהרהורי' להרהר בזה באופני' שונים וכן להיפך לדבר שהיא התפעלות השכל שבמוח לאהוב ולחמוד יעשה לבושים שונים באופן הרהור ומח' לחשוב בו תמיד ותשוטט מחשבתו בזה בכמה ענינים ואופנים שונים ופי' תבונה הוא גילוי מוצא אור התפעלות השכל שבמוח בהלבשה בדבר פרט בריבוי אופנים שונים מאד דווקא וזהו ענין ד' רבתי למעלה כפי המבוא' בספרי הקבלה שהוא הלבשות מדות דבינה בבחי' תנה\"י דווקא ולא יותר לכך הוא באות דלי\"ת דווקא דהיינו להכרעה שבת\"ת דבינה ונה\"י דבינה שהן גמר שפע עצם המדות בחי' חג\"ת שבבינה (ומלובשים במח' בלתי אותיות עדיין רק בענינים ואופנים שונים משא\"כ עצם התפעלות חג\"ת דבינ' לא יבואו עדיין בהתלבשות כו') וכמו שהדבור מלביש לתנה\"י דמדות שבלב (כמ\"ש בסי' ע\"ט בביאור המאמר דזוה' דלעי' בסי' דאשמ\"ח) וכמו\"כ יובן ממש במדו' העצמיי' דיחידה הנ\"ל ודאי ג\"כ באין בהתלבשות במח' והרהור כמו שאנו רואי' בחוש הטבעי שמיד יעורר מדת טוב העצם בנפש יבא לכלל מחשבה בזה ואמנם מח' זו אינם כמחשבה והרהור שמלביש להתפעלות חסד וטוב שבשכל בינה שמוגבל הוא לפי השכל המבין הטוב ההוא שבוחר בו במדה ושיעור השכל וכן למאוס בשכל ברע ויתפעל בכעס במוח כו' אבל מח' זו שמתהוו' להלביש לעצ' התפעלו' שבטוב העצמי שבנפש גם היא בבחי' פשיטות בלתי מוגבל' כלל וזהו המח' שתשוטט באדם בבחי' מקיף על השכל וגם על הרצון דהיינו לא שנתפעל ברצון או שכל כלל עדיין שיהי' מכריח למח' זאת כו' ואעפ\"כ הוא חושב בלי בחירה כלל להיותם בחי' לבוש מקיף דהיינו לבוש פשוט ועצמי לעצם הטוב שמוליד כל רצון ושכל לטוב כנ\"ל שעדיין אינו בכלל התפעלות רצון ושכל כו' והלבשה עצמיות לעצמות המדות נק' בחי' תבונה בעצם וגם היא באה להלביש רק מבחי' תנה\"י ולא לחג\"ת כו' כמובן ממדות דבינה הבאין בגילוי אור מוגבל בהשגה כו' וד\"ל ועם כל זה יובן ענין ד' רבתי השוא בחי'' מל' דתבונה עליונה שבעצמות"],[1700400085,"המאציל שע\"ז א' לתבונתו אין מספר שמנבשת לע' רבתי דהיינו למדות העצמיי' הנ\"ל והענין הוא כידוע בע\"ס הגנוזות בעצמות כח\"ב כו' עד בחי' מל' דא\"ס שהוא אשר עלה ברצונו ומחשבתו כו' אנא אמלוך כו' וביאור הדברי' ידוע דמה שעל' ברצונו בעצמותו נק' תחלת המח' והוא בחי' כתר דמל' שנק' סופא דמח' כי נעוץ תחלתן בסופן שזהו אנא אמלוך שנק' מל' דא\"ס כמ\"ש אני ראשון ואני כו' ומה שמתחלת המח' והרצון נמשך דרך חו\"ב ומדות בבחי' העצמות הכל הוא דרך מעבר כדי שיבא לסופא דמח' זו שהוא אנא אמלוך כו' וז\"ש גדול אדונינו ורב כח פי' אדונינו בכללות הוא בחי' מל' דא\"ס עצמו כמ\"ש במ\"א בפי' ועתה יגדל נא כח א\"ד כו' שם א\"ד שבעצמות אא\"ס ולהיותו נמשך בבחי' קו וחוט אחר הצמצום להיות מקור לאבי\"ע נק' אדונינו כלומר אדון כל האדונים כמ\"ש מלכותך מל' כל עולמים שמבחי' מל' דא\"ס נמשך בהשתלשלות עו\"ע מל' שבעליון כתר לתחתון בכל ה' פרצופי' דא\"ק וע\"י ואו\"א וזו\"נ עד מל' דעשי' וז\"ש אלקי האלקים ואדוני האדונים כידוע בפי' ראו כי אני אני הוא כו' ונמצא עכ\"פ מל' דא\"ס שנק' אדונינו ורב כח היינו משום דנעוץ תחלת הרצון בו שהוא בעצמות הכח דא\"ס שנק' רב כח והוא מה שאא\"ס למעלה מעלה עד אין שיעור ע\"כ מתפשט למטה עד אין תכלית שז\"ש גדול אדונינו עד למטה מטה בבחי' מל' דעשיי' וז\"ש בסיפא לתבונתו אין מספר פי' תבונתו הוא בחי' ד' רבתי הנ\"ל כמו שהוא בעצמו' דהיינו כמו הדבור ומח' למטה מאצילות לבי\"ע כך יש בחי' דיבו' ומח' למעלה בעצמות ומל' דא\"ס הוא בחי' התגלות או' להיות מקור לאבי\"ע כמו אותיות הדיבור למטה בבחי' שים א\"ד וכמ\"ש אני ראשון כו' ראו כי אני אני הוא ויש לזה מח' הוא בחי' מל' דתבונה שבעצמות שנק' תבונתי ממש והוא בחי' מחשבה העצמי' הנ\"ל שמלבשת למדות העצמיי' ואמנם כמו שבסוף דמחו שבדבור נעוץ תחלת המח' והרצון הפשוט כנ\"ל כך בסופא דמחו זו שמלבשת למדות העצמיי' נעוץ תחלת הרצון ומחשבה הפשוטה שבעצמות וז\"ש לתבונתו אין מספר להביא גילוי המדות העצמיי' באותיות מחשבה להיות נמשכין למטה בגילוי אור דמל' דא\"ס משום שאין לו שיעור למעלה בהיותו נעוץ בתחלת הרצון כו' דהא בהא תליא כנ\"ל ולזה רישא סויפ' דמקרא זה מדברים הכל בענין א' רק שרישא דגדול אדונינו מדבר בבחי' מל' בתחלה וסוף שבו כנ\"ל וסיפא מדבר בתבונה שהוא שרש המחשבה בתחלה וסוף ועם זה יובן ג\"כ סדר הפסוק דשמע דעקרו ע' וד' רבתי מדות ומח' שהוא רק ענין התלבשות שלהם במח' העצמו' ואח\"כ בשכמל\"ו הוא מה שנמשך ממל' דא\"ס שבא מהעל' המח' לגילוי כנ\"ל בפי' גדול אדונינו כו' והיינו פי' בשכמל\"ו דקאי על מל' דא\"ס שיורד ונמשך עד למטה מטה במל' דעשי' וזהו ברוך שם דא\"ד שבעצמות שנק' כבוד מלכותו העצמיי' לעולם ועד עד מל' דעשי' כנ\"ל (ומה שמשה לא אמר בשכמל\"ו לפי ששרשו במים עליונים דבינה ותבונה וז\"ש בזוהר ע\"ד ה' כו' כמו עדות שהוא על הנסתרות דוקא והיינו בבינה ותבונה שנק' עלמא דאתכסייא בכלל וז\"ש ברוך ה' מן העולם ועד העולם ממל' דתבונה שבעצמו' למל' דא\"ס שנק' עלמא דאתגליי' בכלל מאחר שנק' מקור לאבי\"ע כנ\"ל ושרש התורה במ\"ע והוא חכמ' עילאה הנעלמה בבינה ותבונה עליונה שבעצמות כידוע) וזהו מארז\"ל על ד' רבתי שתמליכהו בשמים וארץ כו' כידוע דשמים וארץ הוא בחי' מעלה ומטה עד רום המעלות דהיינו עד בחי' עצמו' א\"ס שאין לו שיעור למעלה ולמטה ברצון ומח' שבעצמו' כנ\"ל ופי' ד' רוחות העולם הוא בחי' ד' רבתי שבמחשבה עליונה הנעלמה בעצמות ואח\"כ בא לידי גילוי במל' דא\"ס להיות בבחי' מקור לעולם הנאצל ונברא שנק' עולם בעל ו\"ק ונק'"],[1700400086,"מקום כידוע בענין הוא מקומו של עולם ואין העולם מקומו כמ\"ש הנה מקום אתי עד רום המעלות וד\"ל ומ\"ש תמליכהו הוא מל' דתבונה ומל' שבדבור שכוללי' ו\"ק דמדות שמלבישים אותם כנ\"ל וד\"ל (ואמנם עדיין יש להבין למה הד' רבתי באחד והע' רבתי בשמע ואיך יתחברו כא' להיות נק' עד כנ\"ל דהנה לכאורה אינו מובן בענין ע' רבתי שהן המדות העצמיי' כנ\"ל אחר שנתבאר למעלה בענין נעוץ תחילתן בסופן שהשכל ומדות נק' מעבר לבד ובכאן עיקר הכוונה בתחילת הרצון שנעוץ בסופא דמח' כנ\"ל והמדות אינן תחלת הרצון והענין הוא דיש הפרש בין מדות סתם למדת הללו שהן עצמיי' דהיינו שכלול כ\"א מיו\"ד דווקא דלכך המספר ע' שזהו ע\"י בחי' כח\"ב שבכל מדה והוא הרצון שבכל משה ששרשו בעצם תחלת הרצון הפשוט ולכך הע' רבתי דוקא וזהו פי' שמע שם ע' דוקא כי בירור דרפ\"ח ע\"ע שם ב\"ן גי' שם כמו ויעש דוד שם כו' נק' סוף מעשה שעלה במח' ורצון בתחלה וכענין במי נמלך בנשמתן של צדיקי' כו' והיינו פי' וענין מח' בתחל' הוא בחי' ד' רבתי שנק' תבונתו שנעוץ בתחלת המח' והרצון ובתיבת שמע הוא העליי' דסוף מעשה במח' הראשונ' והד' רבתי הוא מח' הראשונה וזהו ע\"ד כו' שנשלם תחל' המח' ע\"י ברורי' דרפ\"ח כו' שזהו ע' רבתי דתוהו שבזה היה עיקר תחלת התענוג ורצון הנעל' הפשוט בתכלית והגם שבתיבת אחד הרי אח' זה היא בחי' ט\"ס דז\"א שהוא שם מ\"ה שנק' ז\"א שמברר לב\"ן (והיינו ג\"כ ז' רקיעי' וארץ כו') והוא המשפיע למל' (כמ\"ש במ\"א בענין וע\"ד בחלופי אח\"ד שמא' דאחד נעשה וי\"ו במל' ומן הח' ע' והד' אחת היא כנ\"ל הטעם) הנה כל זה נק' בחי' מעבר כדי שיהיה נשלם המח' והרצון שבתחלה ולכך כל פסוק זה מתיבת ישראל עד ד' רבתי נק' מעבר שעי\"ז יאיר התחלת רצון ומחשבה שבע' רבתי בסופא דמח' בד' רבתי וכידוע בכללות הכוונה בתיבת ישראל שי\"ר א\"ל בחי' כתר דחכמה שנק' אל והוא שרש היחוד דחו\"ב שזהו ה' אלהינו ואח\"כ ה' אחד יחוד זו\"נ וכמשי\"ת בסמוך כל זה נק' אמצען כו' כי גם מה שישראל עלה במח' כמשי\"ת לא נק' תחלת הרצון רק מה שע\"י ישראל שעלה במח' בא לידי סוף מעשה בברורי' דרפ\"ח כו' ע\"י תו\"מ שלהם דוקא ולכך א' שמע ישראל דוק' וזהו עד הוי\"ה בכם דוקא וד\"ל) ועדיין יש להבין בענין הד' שהוא מפני שמלביש לתנה\"י לבד ולכאורה עיקר תחלת הרצון במדות העצמיי' חג\"ת ולא בנה\"י כו' אך הענין הוא מב' טעמים הא' דבחג\"ת קודם שבאו להשפעה שנק' נה\"י אין זה סוף הרצון עדיין ותחלת הרצון אינו רק בסופו שהוא דוקא כאשר בא לידי שפע וגם בכליות יועצות איך להשפיע ששקול הדבר ולא נגמר עדיין ה\"ז לא נק' סוף לרצון כי לא ידוע עדיין האיך יבא הרצון בפ\"מ שא\"א למעשה להיות בשיקול רק באופן מיוחד דוקא ולזה בחג\"ת שהן בעצם עדיין לא נשלם התחלה רק בנה\"י והטעם הב' הוא מצד בחי' הת\"ת שהוא המכריע ששם בא גילוי אור הרצון לקו והמשכה כוללת ב' קווין שברצון ימין ושמאל כא' ששם דווקא מאיר מעצם נקודת הרצון טרם שמתחלק כידוע אך א\"כ היה ראוי הלבש' זו בחג\"ת דוק' אמנם מטעם הא' שהן המדות בעצם והעיק' של תחלת הרצון הוא בהשפע' ולזה א\"א להיות לא בחג\"ת לבד ונה\"י לבד כ\"א בשליש אחרון דת\"ת בצירוף עם נה\"י דהיינו דוקא בחי' הכרעת הת\"ת הבא לענין גילוי השפע של המדות ולא ההכרעה בעצם המדות לבד שזהו ענין שליש האחרון שנק' נה\"י שבת\"ת כו' כידוע ומבוא' במ\"א ואז נשלם תחלת הרצון בהגיעו להכרעה שבבח\"ת לבא לידי סוף מעשה ע\"י שפע המדות בנו\"ה ומשם ליסוד ואז דוקא נתחבר תחלה בסוף וזהו ענין הד' שמלבשת לתנה\"י"],[1700400087,"דוקא (ומ\"ש תמליכהו בשמים ובארץ היינו בחי' מעלה ומטה שנק' תחלה וסוף שמתחברים כא' בד' רבתי מטעם שנעוץ תחלתן בסופן וסופן בתחלתן ולא באמצען כנ\"ל וד\"ל והגלוי הוא הדלי\"ת ובהעלם מתחבד בו מעל' ומטה דשמים וארץ שכלול בד' דהיינו ד' רוחות העולם עד רום המעלות וד\"ל):\n(ח) <b>והנה</b> מעתה יש להבין בכללות ענין הפסוק דשמע ישראל מה שנזכ' ב\"פ הוי\"ה כנ\"ל ומהו ישראל לכאן באמרו שמע ישראל דווקא ה' אלהינו כו' והנה תחלה יש להקדי' ההפרש בין אחד ליחיד והוא ענין ב' פעמים הוי' הוי' הא' בבחי' יחיד והוי' ב' בבחי' אחד והיינו שיהי' מיחיד אחד הוצרך להוי' ב' וע\"ד המבואר במ\"א בענין ויקרא ה' ה' כו' וההפרש בין אחד ליחיד ידוע שזהו עד\"מ מספר א' המנוי שכל איש ואיש שנמנה במספר נק' אחד גם שיבא שני אחריו ונק' שני לראשון גם השני נק' אחד וגם הג' והד' ונק' מספר אחדי' דהיינו שהגם שבצירופ' יחד יקרא זה ראשון וזה שני וזה שלישי היינו כשיבאו בסדר זה אחר זה אבל כל א' לעצמו נק' א' מפני שאין שני לו כאשר לא יתאספו יחד אלא כל אחד על מקומו וגם כשבאין במספר נק' א' המנוי מטעם זה ולשון אחד שמתאחד ם זולתו היינו בצירוף עו' א' שיקרא שני לו לכך יקרא א' כשהוא לעצמו משא\"כ כשאין דבר לספר עמו כלל רק הוא לבדו איך יקראוהו אחד מל' אחדות או מענין א' המנוי במספר אחדי' שיבא בצירוף וחיבור מאחר שאין איש אחר זולתו כלל ולזה יקראוהו בל' יחיד זאין לו שיתוף וחיבור במספר כלל וכלל ועכ\"פ יובן מזה שיפול לשון אחד גם בצירוף רבים כשהם מתאחדים כאיש אבל ביחיד לבדו לא יתכן לשון אחדות וחיבור כלל מאחר שאין לו חבור מתחלה רק הוא לבדו וכמו\"כ יובן שיוכל להיות ענין האחדות בתחלה דהיינו לא שנתחלקו והיו לאחדים אלא שכולל הריבוי בעצמו והיו לאחדים בתחלה כאילו אין בהן חילוק כלל ואח\"כ מתחלקי' ויוצאי' כ\"א בפ\"ע כמו עד\"מ מספר אלף שכולל עשרה חלקים ממאות ומאה חלקים מעשירות ואלף חלקים מאחדים הרי כלולים כא' ממש במספר אלף ואח\"כ יוצאים לגילוי התחלקות וכן אלף איש שמתחלקים במספר וכה\"ג וכל זה לא יתכן בלשון יחיד שאין בו בחי' ריבוי וחילוק גם בתחל' שיפול בו לשון אחדות המתאחד בכלל לבא לידי פרט אלא יחיד הוא בעצ' בלתי יקרא כולל הריבוי כלל לפי שהוא יחיד בעצם דהיינו בלתי מתחלק בעצם והדמיון לזה עוד יובן ממה שנק' פשוט ומורכב שהמורכב יש בו התחלקות בעצם הגם שכלולי' ומתאחדי' בו והפשוט בלתי מתחלק בעצם כלל וא\"א לומר שיכלול ההתחלקו' כמו המורכב מאש ומים הרי יש בו בהכרח מחלקי המים והאש ברבוי הכולל ויבואו להתחלקו' גמורה כשיוציאו בגילוי כל פרטי החלקי' משא\"כ עצם הפשוט ממים או אש לבדו שלא יחולק גם בעצ' כלל כו' וכך הוא בכחות הנפש עם עצם הנפש ובכל כח בפ\"ע יש הפרש זה בין העצם שבו שבלתי מתחלק למורכב שבו שמתחלק כמו בנקודת עצם התקשרות הנפש מה שנק' בשם התפעלות עצמיות הגם שבלתי מתחלק עדיין לגילוי רצונות פרטיים לדבר שנפשו קשור' בו בעצם כמו התקשרות עצמיות דאב לבנו שבלתי מתחלק עדיין לפרטי חלוקי התפעלות רצונות באהבתו זאת אבל ממילא הרי מזה דוקא יבא גילוי התחלקו' רצונות באהבה עצמיים זובב' הפכים לטוב ולרע והכל א' מצד התפעלות העצם דהיינו מה שמתפעל ברצון להטיב לו וההיפך מזה שמתפעל ברצון להרע לו כדי שיטיב מעשיו שזהו נקרא גבורה שבחסד שהוא רק מצד האהבה ובנקודת התפעלו' עצמיו' התקשרותו אינם נגלים ב' הפכי' הללו עדיין כי אין שם גדר התפעלות"],[1700400088,"מחולקת עדיין רק עצם והיולי עדיין ואין שם הפרש כלל בין התפעלות הרצון לטוב להיפוכו מאחר שהכל מכח א' שהוא התפעלו' התקשרו' העצמיות וכמ\"כ בנקודת התפעלות התקשרו' עצם נפש האלקי' בתפל' בעבודה שבלב שאין שם עדיין התחלקו' התפעלות הרצון לדבר והיפוכו שהוא לאהוב הטוב ולמאוס הרע או התפעלות החדוה ועונג באלקו' ולהיפך להצטער מריחוקו מאלקי' חיים שהן ב' מיני התפעלות הפכיי' וכלולי' כא' ממש בהתפעלו' העצמיו' לפי שזהו הכל מכח א' באו שהוא התפעלות התקשרו' עצמיו' של הנפש רק שמתחלק אח\"כ בב' אופני' חדוה ובכי' או להתפעל ברצון לטוב או לשנוא בהתפעלו' היפך הטוב שהרי אנו רואים שמנקוד' התפעלות עצמיות בתפלה יהיה האדם מחמת זה כל היום מואס ברע ובוחר בטוב שהן ב' רצונות מחולקי' וכלולי' כא' ממש וכל זה הוא הנק' מורכב בשעת התפעלו' הנקוד' העצמיו' שכוללת עכ\"פ בכח והעלם גדול מה שעתיד לצאת ב' התפעלות דחו\"ג כמו העץ המורכב בהעלם מאש ומים ועכ\"פ נק' מתחלק מן ההעלם לגילוי אבל עצם פשוט שבנפש שבלתי מתחלק לעולם הוא בבחי' הנקוד' העצמיו' דכל בחי' עצמות' ממש בה שזהו טרם שבא' לכלל התפעלו' עצמיות כלל ולא נק' בשם התפעלו' כלל גם בהעל' רק שהוא עצם פשוט כמו שהוא ממש שא\"א לומר בו שכולל כמה מיני התפעלו' דחו\"ג מאחר שאינו בגדר התפעלות עדיין גם לא בבחי' התפעלות עצמיות לזה לא נק' מורכב מדב' והיפוכו גם בהעלם שיבא לידי גילוי וכמו אהבת נפשו אהב' דיהונתן ודוד וכה\"ג וכמו אהבת עצמו באד' שאינ' בגדר התפעלו' כלל כאהבת האב לבן שבא לידי התפעלות לפעמי' כל כו' מפני שנלקח מעצמותו ולא שהוא כעצמו ממש וראיה מנסיון דאיוב שא' וגע אל עצמו כו' אם לא אל פניך כו' ואברהם אבינו ע\"ה עמד בנסיון בעצמו ובבנו יחידו מפני שהיה מרכב' בכל עצמו' נפשו ממש שנק' אהבת הנפש מצד עצם מציאותה בלא התפעלו' מורכבת כלל וכמ\"ש רשב\"י בחד קטיר' כו' וכמ\"ש במ\"א שזהו בחי' יחידים שבנפש העצמיות מש טרם שבאה לכלל התפעלו' מן העצ' שההתפעלו' מן העצ' אינו רק חלק ממנ' ולא כול' כמו שהי' ממש וכמו עד\"מ מן המספר שההפרש בין יחיד לאחד שביחיד לבדו הוא בלתי מתחלק שלא יפול בו לשון אחדות וחיבור גם בהעלם שנק' מורכב מאחר שאין לו חבר כו' ואחד כולל הריבוי ואח\"כ מתחלק שבהכרח יש בו התחלקו' זאת גם בהיותו בעצם והיחיד בלתי מתחלק גם בעצם וכן ממשל אש ומים שעיקר ההפרש בין פשוט למורכב הוא רק במה שזה בלתי מתחלק גם בעצם כו' וד\"ל ומכל דמיונות הללו בנפש האדם ובמשל המספר כו' יובן הכל למעלה כללות ענין ההפרש בין יחיד לאחד בעצמות אא\"ס ממש שנק' יחדי וגם נק' אחד כידוע וההפרש ביניהם יובן מתוך כל הנ\"ל עד רום המעלו' דהיינו גם בעצמות אא\"ס שלפני הצמצום הראשון הנק' מק\"פ כו' שע\"ז הצמצום א' בריש הרומנא כו' גליף גליפו וחקוק' בטה\"ע הפשוט דהיינו מה ששיער בעצמו עדיין בכח מה שעתיד כו' הנה ידוע שזהו הנק' בל' הפרד\"ס דרך כלל ע\"ס הגנוזות בעצמות ממש ומ\"ש אנת הוא חד ולא בחושבן היינו לא בחושבן י\"ס שהן במספר עשר ולא תשע כו' וע\"ס הגנוזות הללו נקרא ג\"כ בשם אחדות הפשוטה שיפול בזה לשון אחד עכ\"פ דהיינו שמתאחדים יחד והוא כענין הנ\"ל במספר ברבוי הכולל בעצם שעתיד לצאת להתחלקות גמורה רק שנק' בשם אחדות הפשוטה להיות שאור זה פשוט בתכלית עדיין כי לא ניכר בו שיש התחלקות ע\"ס כי גם מה שעתיד להיות התחלקות הרצון הפשוט במדות חו\"ג שבעצמות כלול כא' בלי נודע עדיין שיש ב' מיני רצון לחו\"ג גם בעצמו' עד\"מ התפעלות העצמיות שבנפש הנ\"ל שכולל ב' מיני"],[1700400089,"התפעלות הרצון לחו\"ג ועתיד לבא בגלוי אבל כלולים כא' ממש כנ\"ל במשל התפעלות עצמיו' כאב לבן וכמו בתפל' כו' וזהו ג\"כ כמשל המספ' בא' המנוי הנ\"ל שנק' מורכב בהעלם שכולל ודאי ב' הפכי' בהעלם עכ\"פ שאל\"כ לא הי' בבחי' מספר עשר ולא תשע כו' גם בעצמו' רק מפני ששיער בעצמו מה שעתיד כו' ולזה נק' בשם אחדות הפשוטה שיפול בזה לשון אחדות עכ\"פ שהוא מתאחד בריבוי' הכולל שבו בהעלם כו' אבל מ\"ש אנת הוא חד ולא בחושבן י\"ס כלל וכמו שמסיים ולאו מכל אינון מדות כלל אפי' בהעלם העצמו' כו' הנה זהו הנק' בשם יחיד כמו היחיד שאינו בגדר מספר המתאחד לא בהתחלקות גם בעצם הנ\"ל כי אין לו חבר מתחלה כו' וה\"ז כמו בחי' עצמות הנפש ממש שאינה עדיין בגדר התפעלות מן העצם לכלול הריבוי כו' אלא הוא בחי' עצמות אא\"ס כמו שהוא ממש טרם ששיער בעצמו בכח כו' שלא יפול בזה לשון אחדות וחיבור גם לא לשון אחדות הפשוטה הכולל בהעלם עדיין כו' אלא יקרא בשם יחיד דווקא וכמו בחי' יחידה הבנפש עצמה ומהות' שאין בה התחלקות בהעלם ג\"כ והוא מה שאמרו שהי' הוא ושמו בלבד והוא שנק' טהירו עילאה טרם ששיער בעצמו כו' הנק' גליפו וחקיקה כידוע וד\"ל (ומה שמבואר למעלה (בסי' וי\"ו) בענין ע' רבתי שמדות דיחידה בלתי נחלק לי' עדיין דהיינו ג\"כ למעלה מהתפעלות רצון ושכל לטוב רק טוב היולי ופשוט בלתי התפעלות רצון רק שיוכל להיות כמה מיני התפעלות רצון כנ\"ל ועכ\"ז נק' מדות הכוללי' המספר ע' שזהו בחי' מורכב בהעלם ממה שעתיד לצאת בגלוי כנ\"ל ולמעל' מבואר שעצם המהות שבנפש שלמעלה מהתפעלות העצמיו' זהו רק בעצם הנפש ממש שאינו נק' מורכב לכלול הריבוי כו' הענין הוא דכמו שב' מדרגו' הנ\"ל בעצם הנפש בכללות' בין מהות וכל עצמו' שבה בין התפעלו' מן העצם כנ\"ל כך יש ב' מדריגות כזה בכל כח מכחו' הנפש שהוא ההפרש בין העצם וכל המהות של אותו הכח כמו שהוא ובין התפעלות מבחי' העצם שנק' מורכב כנ\"ל וכמו בעצם מדת הטוב כמו שהוא ממש שנק' פשוט והיולי למעלה מהתפעלות העצם והתפעלות מן העצם של מדה זו נק' מורכב שכולל כמה מיני התפעלות פרטיות כו' וכמו התפעלות איש החסד והרחמן על עני ומדוכא שיש הפרש בין קוד' שנתפעל מן העצ' לאח\"כ כו' דהיינו גם בהתפעלו' רחמי' עצמיי' דאב לבן כמו המו מעי לו רחם ארחמנו כו' וכה\"ג וד\"ל ולפ\"ז הרי במדו' שביחודה יש בכל א' בפרט בחי' העצמות שבה ממש טרם שיתפעל העצם שזהו ממש כמו עצם ומהות כל הנפש בכללותה רק שבמדו' בא דרך פרט וא\"א לומר שפרט זה בעצם וכל מהות המדה ג\"כ אינו רק חלק מן הנפש כערך התפעלות מן העצם שנק' חלק לבד כנ\"ל דודאי אין זה דומה לזה כלל מאחר שכל עיקר הענין בעצם המדה במה שהוא בבחי' פשוט ועצמיו' הגם שהוא בדבר פרט בחסד או חכמה וכה\"ג א\"כ לא יתכן לקרותו בשם חלק נבדל כלל מכל עצמו' הנפש לפי שבוודאי א\"א לחלק במהות ועצמו' הנפש ממש בפרט' חלקיה העצמי' שבה לפי שזהו הכל לשכל עצם בלתי מתחלק כנ\"ל וד\"ל וראי' לזה ממה שאנו רואים בהתפעלו' כל העצם של האהבה כמו שהיא או עצם הרחמנות כו' שישתתף בזה כל הנפש ועד שתכלה כולה כאהב' נפש דיהונתן ודוד שיכול לבא למס\"נ ממש באהבתו אותו הגם שהאהבה מדה פרטית חלק מן הנפש כו' וכן בהתפעלות עצם הרחמים דאב לבנו יכול להיו' כליון כל הנפש וראי' מאאע\"ה שכבש רחמיו העצמיי' בבנו יחידו נחש' למס\"נ בעצ' כל הנפש משו' שאין לחלק כלל בעצם א' הפשוט עד שבפרט א' שבה יחובר הכל כי הוא בלתי מתחלק כו' ודווקא בהתפעלו' כל העצם של המדה ולא בהתפעלות חלק מן העצם שזה ודאי יוכל להבדל מעצם הנפש רק שמתאחד בזה אבל לא"],[1700400090,"שיהי' כעצם א' ממש דלכאורה גם בהתפעלות עצמיות הנ\"ל מתאחדת כל הנפש לימשך אח\"ז אעפ\"י שאינו אלא התפעלות איזה רצון בדבר פרט כממון וכבוד וכה\"ג אך אין זה ערך להתפעלות כל עצם שבתאות הנפש לממון וכבוד שיוכל לבא למס\"נ ממש כידוע (ועוד ראי' ממס\"נ על קדה\"ש שההתקשרות עצמיו' אינו רק בדבר פרט והוא בחכמ' כח מה שבנפש האלקי' וממיל' נמשכ' כל הנפש מפני שאין העצ' מתחלק כלל וכן ראי' מכח המוליד בדומה לו לפי שנמשך ממוח האב אעפ\"י שהטפ' במוח החכמ' לבד נמשך בה מכל כוחו' העצמיי' שבנפש עד שיוליד בדומה לו ממש בכל פרטי חלקי כוחות הנפש בצורה וחומר שהבן קרוב בדעתו ומדותיו אל האב כו') ולפ\"ז שגם במדות בפרט יש בכל א' מבחי' כל עצם הנפש יובן מזה למעל' עוד ענן חדש ביחוד העצמו' דאא\"ס מ\"ש דאיהו וחיוהי חד כו' או אנת הוא חד שזהו מלבד ענין הנ\"ל במהות ועצמות אא\"ס ממש טרם ששיער בעצמו כו' אלא גם בפרטי מדותיו העצמיי' דהיינו בחי' העצם ממש של כל ספי' בפרט שיש בו מבחי' כל העצמו' ממש עד שאין לחלק בזה כלל כמובן מהנ\"ל דאין העצם הפשוט מתחלק כו' וז\"ש אנת הוא חד בבחי' יחוד עצמי ופשוט דהיינו מכל ע\"ס המיוחדים בבחי' עצמיו' ממש מלבד עצמות יחודו ממש וזהו כמו פי' איהו וחיוהי חד שיש עכ\"פ איהו וחיוהי רק שמיוחדים ביחוד עצמי ופשוט משא\"כ בעצמו ממש לא שייך לומר איהו וחיוהי כו' וגם לא שייך לומר גם אנת הוא חד כו' אך בזה יתכן לשון אנת הוא חד בבחי' יחיד העצמי שזהו בלא חושבן י\"ס כמובן מהנ\"ל וד\"ל):\n(ט) <b>וזהו</b> ענין ב\"פ הוי' שבפסוק זה דשמע כו' הוי' הא' הוא בבחי' יחיד בעצמות אא\"ס טרם שצמצם א\"ע כו' שאין עוד מלבדו כלל ועד\"מ כשאהדם לבדו שאין עוד זולתו לבא עמו במספר אחדי' כנ\"ל (ולפי הנ\"ל בסוף סימן ח' שבחי' יחיד זה יתסן גם ביחיד שבמדות העצמיי' שבעצמו' ממש מצד בחי' העצמיות שבכל א' כו' שייך לומר בזה ענין שם הוי\"ה יוד כתר וחכמה ה\"א בינה וי\"ו מדות כו' אבל בעצמותו ממש הרי א' ולאו מכל אינון מדות כלל אפי' בהעל' ולא יתכן בו שם הוי' עדיין כידוע) והוי' הב' הוא בחי' אחדות ה' שנק' אחדות הפשוטה הנ\"ל שהן ע\"ס הכלולים בעצמות כדמיון שלהבת הקשורה בגחלת כמ\"ש בס\"י וכיחוד מספר אחדי' הנ\"ל שיתכן בו ההתחלקות בעצם טרם שמתחלק בגילוי רק שכלולים ומתאחדים עדיין וזהו ה' אחד שע\"ז ארז\"ל כל המאריך בא' מאריכין לו ימיו ושנותיו פי' מאריך בא' הוא בבחי' אריכו' העליונה שבעצמות אא\"ס דאיהו וחיוהי חד הכל בבחי' א\"ס עדיין וכנ\"ל דלכך נק' אחדות הפשוטה עדיין כו' וד\"ל וזהו הנק' המאריך כי המדות שבעצמו' כל א' אין לו שיערו למעלה ואין לה שיעור למטה שזהו הנק' אריכות הגם שכל אריכות אינו נופל אלא על בחי' ההתפשטות לסוף אבל אריכות זאת קאי גם על התחלה שארוך בתחלה מפני שאין לו תחלה וכמ\"ש במ\"א בפי' יום שכולו ארוך שהוא ארוך בראשו כמו בסופו לכך נק' כולו ארוך משא\"כ ארוך בסופו ולא בראשו שבראשו יש לו תחלה כו' שזהנו במדות שברצון ושכל כו' שבאין מהעלם העצמות לגילוי בפרצופי' דא\"ק וע\"י וא\"א וא\"וא כו' אבל במדותיו שבעצמות ממש שע\"ז אמר איהו וחיוהי חד הגם שעתיד לצאת מן ההעלם כו' אבל בהיותם כלולים בעצמותו איהו וחיוהי חד בבחי' א\"ס למעלה ולמטה שזה נק' כולו ארוך והוא מה שאמרו תמליכהו בשמים וארץ כו' בחי' מעלה ומט' וד' רוחות שהן כלולי' בא\"ס בבלתי שיעור למעלה ולמטה ולד' רוחות כו' וע\"ז אמרו המאריך בא' שהוא בדלי\"ת רבתי דאחד שיכוין להמליכהו בשמים כו' וכנ\"ל בענין נעוץ תחלתן בסופן גם בעצמות ע\"ס דכתר עד המל' בא\"ס עצמו וזהו שאמרו דכל"],[1700400091,"המאריך באחד מאריכין ימיו ושנותיו דווקא כידוע שהמדות נק' ימים ומדת עליונות שבכתר נק' ימי קדם בקדמות השכל וכתרגום בראשית בקדמין כו' ויש קדם לקדם והוא קדמות הרצון כמו מגיד מראשית כו' ומקדם אשר לא נעשה פירוש אשר לא עלה ברצון עדיין לעשות שהרצון נחשב עם המעשה לא ממש מאחר שעיקר הרצון אינו אלא בשביל סוף מעשה דווקא וסוף המעשה הוא שעולה במח' ורצון בתחלה ונק' תחלת הרצון תחלת המח' וסופא דמח' הוא בסוף המעשה ונעוץ תחלתן בסופן והיו לאחדי' ממש כידוע וא\"כ מה שאנו רואי' חלוקי המדות חג\"ת וכה\"ג בסוף מעשה הן הן אותן המדות ממש שהיו ברצון אבל בקדמות הרצון היינו קודם שבא במקור הרצון הזה שבא בסוף מעשה דהיינו קודם שהי' מקור לרצון דרצון הזה כו' ששם וודאי לא יגיע סוף מעשה כלל ולפ\"ז מ\"ש כל אשר חפץ ה' עשה קאי בתחלת הרצון שנעוץ בסופו במעשה דהיינו מתחלת גילוי הרצון להאציל עד אשר חפץ לעשות הכל נחשב א' ממש עד שבחי' המדות דעשי' (שנק' ז\"א דעשי') הוא חי' המדות שברצון הקדום (שנק' א\"ק שהוא הרצון לרצון כידוע) וז\"ש אשר נשבעת לאבותינו מימי קדם אבותינו בחי' חג\"ת דבי\"ע שהיו מרכב' בנר\"נ שלהם לחג\"ת דאצילות ושרשם הראשון בחג\"ת דקדמו' הרצון הנק' רצון קדום ולכך המדות דשם נק' ימי קדם וכמ\"כ חדש ימינו כקדם (ולפעמים נק' ימים הראשונים והן ברצון שבחכמה ובינה כמ\"ש כי שאל נא לימים הראשונים כו' ומי דלא קיימא לשאלה הוא במדו' שבכתר וחכמה כו' כידוע) וכן הוא ענין ימי עולם ושנים קדמוניות כו' ומ\"ש המתנשא מימות עולם קאי גם על המדות שברצון הקדום הנ\"ל והוא בבחי' כתר שבכתר שלמעלה מהתחלקות קווין שברצון הקדום כידוע (והוא כתר דא\"ק שמקבל ממל' דא\"ס כמ\"ש בשער הכללים) ואמנם במ\"ש ומקדם אשר לא נעשה יש להבין מהו פשט הכתוב מגיד כו' דמראשית אחרית שייך לומר מגיד שהוא תרגום דבראשית בקדמין בחוכמתא שנעוץ תחלה בסוף מעשה כנ\"ל אבל מקדם אשר לא נעשה איך שייך הגדה והמשכה משם אחר שלא היה שם עדיין מקור לרצון דרצון הנק' רצון קדום כנ\"ל ופשט הכתוב משמע דסיפא דקרא ארישא קאי מגיד מראשית כו' וגם מקדם אשר לא נעשה הוא מגיד כו' אמנם הנה הענין הוא מובן עפ\"י הנ\"ל בפי' יום שכולו ארוך בראשו כמו בסופו דהיינו שאין לו תחלה והוא לפי שאין לו שיעור למעלה ולמטה כנ\"ל והיינו במדות מאחר שנק' יום רק שכולו ארוך והוא במדות שבעצמו' א\"ס דווקא טרם שבא לכלל מקור לרצון הקדום ג\"כ שהן כלולי' בא\"ס עצמו וע\"ז א' איהו וחיוהי חד בבחי' יחיד' דעצמו' כנ\"ל הגם שעתידי' לצאת מהעלם העצמות אחר הצמצום בקו כו' מאחר ששיע' בעצמו בכח כנ\"ל אבל בהיות' כלולים בעצמו' נק' כל מדה יום שכולו ארוך בראשו כמו בסופו כו' משא\"כ מדות שברצון הקדום דא\"ק ובגילוי הרצון וחכמ' דא\"ק וע\"י כו' יש לו תחלה וסוף כנ\"ל בענין סוף מעשה במ\"ת כו' ואמנם עכ\"ז מאחר ששיער בעצמו בכח מה שעתיד לצאת בגילוי מהעלם עצמותו הרי שפיר שייך לומר גם ממדות שבעצמו' ממש בחי' המשכה רק שאינה נקרא' המשכה מהעל' לגילוי עדיין אחר שהן כלולי' בעצמו עדיין רק ששרש הגילוי מן ההעלם משם נמצא דווקא והוא ע\"י בחי' הצמצום הראשון כידוע א\"כ נק' בחי' המשכה נעלמה שבעצמו' עדיין והוא מה ששיער בעצמו בכח כדי שיבא לידי פועל בבחי' מקור לרצון הקדום (דבחי' א\"ק וכה\"ג) וע\"ז אמר ומקדם אשר לא נעשה עדיין פי' אשר לא היה עדיין בחי' מקור לרצון כלל מהעלם לגילוי רק כלול בעצמותו ממש (עד\"מ הידוע מרצון המוחלט באד' למטה שנשאר כלול בהעלם העצמות ממש וכאשר מעוררו ה\"ז מעורר לתחילת ההויה דהיינו להיו' לו רצון לרצון"],[1700400092,"בהתפשטות וגילוי לחוץ מעצמו מה שהוא הי' כלול בהחלט בעצם מהותו כו' ואע\"פ שאין כל חדש מעיקרו בזה שהרי מה שהוחלט אצלו יצא לגלוי ברצון לרצון וכו' מ\"מ הרי זה כהויותו של רצון מחדש מאחר שהחלט רצון זה היה כלול ובטל לגמרי בעצם מהותו כאלו שלא היה מעולם כו' וד\"ל) ועכ\"ז שייך לומר בזה בחי' הגדה והמשכה בהיות שמה שבהעלם העצמו' ודאי נתעורר לבא לידי גילוי כמ\"ש בע\"ח דמתחלה היה חפץ חסד כטבע הטוב להטיב וכה\"ג וזהו מגיד גם מקדם שנקרא קדמון לכל הקדומי' גם אשר לא נעשה ברצון ומח' בתחלה ואעפ\"כ הוא אמיתי המקור הראשון לתחלה וסוף דרצון ומעשה ולזה תחילה אמר מגיד מראשית אחרית מתחלה דרצון לסוף מעשה ואח\"כ אמר ומקדם דהיינו בחי' העל' המקור האמיתי לראשית ואחרית זה שהוא מבחי' קדמות הרצון דהיינו מקדם שעלה ברצון כו' שהן ממדות העצמיות ממש שאין לו תחלה וסוף כלל כנ\"ל ומה שאין לו תחלה וסוף שזהו מקדם אשר לא נעשה זהו דוקא בחי' מקור האמיתי לראשית ואחרית שברצון וסוף מעשה (כמובן ממשל רצון המוחלט הנ\"ל) וזהו הנק' קדמות הרצון (כמו קדמו' השכל) שלמעלה גם מבחי' רצון הקדום כנ\"ל וד\"ל ובכל זה יובן מאמר הנ\"ל דכל המאריך באחד דוקא מאריכין ימיו ושנותיו דהנה כתיב כי בי חשק ואפלטהו כו' עד אורך ימים אשביעהו ואראהו בישועתי כי הנה ידוע דבתיבת אחד כשמאריך באחד צריך למסור נפשו בא' כענין ר\"ע שהיה מאריך בא' עד שיצאה נשמתו באחד והיה מצטער כל ימיו מתי יבא לידי ואקיימנ' בפ\"מ ואמנם בחי' מס\"נ בכח ישנה בכאו\"א מישראל לפ\"ע שרש נשמתו שמס\"נ זו הוא על הנשמה האלקי' כמ\"ש ברישא דקרא שמע ישראל דוקא דישראל זה הוא הנשמה האלקי' כמו שהיא בשרש מקור חוצבה שעל' במח' ורצון הקדום כידוע ופי' מס\"נ זו היינו למסור גם מקור כל רצון והוא בחי' התפעלות עצם הנפש ממש שמזה יבא ממילא התפעלות רצון כנ\"ל ונמצא נעשה מהתפעלו' העצם מקור לכל רצון שהוא נק' למעלה רצון קדום וכידוע בשעת מ\"ת שאמרו נעשה ונשמע שזה הי' מצד התפעלו' כל עצמו' הנפש נכלל בזה ממילא נעשו' כל רצון ה' כלומר להיות רצון לכל רצון ה' כידוע בענין מי גילה רז זה שהקדימו נעשה כו' כלומ' נעש' לכל אשר נשמע שזהו במקור כל רצון שנלקח מצד התפעלות נקודה העצמי' דיחידה שבנפש (וזהו עיקר מס\"נ שלמעלה ממסירת הרצון כמ\"ש בדרוש דפדה בשלו' כו' ולא התפעלות חלק לבד מן העצם אלא התפעלות לכל העצם והגם שהתפעלות כל העצ' אינו רק בדבר פרט כמו באהבה וכה\"ג הרי מבואר למעלה שאין לחלק בעצם בין כולו לפרט שבו שהרי יוכל לבוא למסירת נפש על התפעלות פרט מן העצם כנ\"ל) וגם הנה ידוע דבמס\"נ העיקר הוא אל מהות ועצמות אא\"ס דוקא כמו שהוא ממש וכמ\"ש מי כה' אלהינו בכל קראינו אליו ולא למדותיו גם לא למדות שבעצמו' הכלולים רק לו לבדו שנק' יחיד בעצם כנ\"ל למעלה גם מבחי' יחיד העצמי שבמדו' דע\"ז א' איהו וחיוהי חד כנ\"ל וא\"כ לכאור' יש להבין מה שאמר לשון זה דלמסור נפשו בא' דוודאי תיבת אחד קאי באח\"פ שלמטה מבחי' יחיד וכנ\"ל בענין ב\"פ הוי\"ה דמהוי\"ה א' דבחי' יחיד נמשך הוי' הב' דאח\"פ שהוא יחוד מדותיו שבעצמות כשלהבת הקשורה בגחלת וכה\"ג כנ\"ל אך הענין הוא דמ\"ש למסור נפשו בא' ודאי באחד ממש והוא בהיות שכאשר מאריך באח\"פ זה בבחי' יחוד מדות שבעצמו' איך דאיהו וחיוהי חד כו' ומוסר נפשו ממש באח\"פ זה בבחי' התפעלות כל עצם הנפש אזי ממילא נמסר נפשו ביחיד שלמעלה מא' והוא להיות באתדל\"ת אתדל\"ע כמ\"ש אם ישים אליו לבו דרוח אייתי רוח כו' כידוע וא\"כ בהתפעלות עצמיות נפשו מעורר למעלה ג\"כ בעצמות"],[1700400093,"אא\"ס שנק' יחיד להיות מקור לכל רצון פשוט שבעצמות מדותיו הפשוטי' שנק' אח\"פ כנ\"ל (דהא בהא תליא והיו לאחדי' דאין העצם מתחלק וחלק מן העצם ככולו נחשב כנ\"ל) אך מה שמאריך ומוסר נפשו בא' ולא בהוי' הא' שהוא לבחי' יחיד שז\"ש אליו ולא למדותיו הטעם הוא משום דישראל עלה במח' (שהוא מח' הקדומה שבעצמות שכוללת המדות העצמיי' שנק' ישראל סבא בכלל כמ\"ש במ\"א בענין וירא ישראל ישראל סבא כו' וכימי כו' אראנו נפלאות כו') לכך ישראל זה צריך למסור נפשו במקור חוצבו ממש שהוא בבחי' א' עילא' שבעצמו' בחי' עשר מדותיו הכלולים בעצמותו וכל זה נעשה מצד בחי' היחוד שבעצמותו ממש שע\"ז אמר אנת הוא חד שהוא בלא חושבן י\"ס כלל כנ\"ל ועכ\"ז מיחוד דמדות העצמיי' נעשה בחי' יחוד העצמי שבלא חושבן י\"ס דהא בהא תליא ואין לחלק ביניהם כלל מטעם הנ\"ל ונמצא שניהם אמת דעיק' מס\"נ להעצמו' ממש ועכ\"ז צריך למסור נפשו בא' דוקא וד\"ל ובכל זה יובן פי' המשך הפסוקים הנ\"ל כי בי חשק פי' בי בעצמותו ממש שנק' יחיד וקדמון לכל הקדומי' כו' וכמ\"ש אליו ולא למדותיו כנ\"ל ופי' חשק הוא בחי' התפעלות כל הנפש בבחי' יחידה שבה דוקא שזהו הנק' חשיקה (כמו שכם חשקה נפשו כו' ותדבק נפשו כו' כידוע ההפרש בין חפץ ורצון שהוא חלק פרטי מן הנפש ויוכל להיות לו חפץ לדבר אחר משא\"כ החשק שכל הנפש נמשך ונדבק עד שלא יוכל להיות לו רצון וחפץ ותשוקה זולתה כלל וזהו סימן על התפעלו' העצם ממש והיינו עיקר מס\"נ כנ\"ל שהוא מזה בא ממילא למקו' כל רצון וזהו כי בי חשק ולכך ואפלטהו מהמנגד דקליפה לפי שהגם שאת זלע\"ז כו' יש עומק רע דקליפ' שהוא ג\"כ מקור כל רצון זה אבל אפלטהו משם לאחר שחשק' נפשו בהתפעלו' כל עצמותה שאין זה באת זלע\"ז כלל (וראי' ממס\"נ על קדה\"ש שאינו אלא בישראל וכמ\"ש במ\"א בענין בבואה דבבואה לית להו והוא מ\"ש מיד כלב יחידתי כו' כידוע) ואח\"כ ואשגבהו כענין ונשגב שמו' כו' שזהו בעל הרצון הקדום הנ\"ל וז\"ש כי ידע שמי העצמי שהוא מקור כל רצון קדום כו' יקראני ואענהו דרוח אייתי רוח בהיותו אחוז וקשור בעצם בעל הרצון ממילא ואענהו להיות רצון וחפץ בו וכמ\"ש חפצי בה ארץ חפץ כו' ולא עוד אלא שבטר' תקר' ואני אענה והוא משום דעמו אנכי בצרה כמו בכל צרתם לו צר ממש ולכך א\"צ לקריאתו כלל עד\"מ אב הרוא' בצרת בנו א\"צ להמתין עד שיקראנו להושיעו כי בצרתו לו צר כמי שרוא' בצרת עצמו כב\"י ולכך בטר' תקרא כו' וכך עמו ממש אנכי בצרתו מטעם הנ\"ל ולכך אחלצהו מכל קטרוג שאין שרש ליניקות חיצונים שם כלל ואכבדהו בכתר דמל' דכבוד עליון שהוא מלך מרומם מתנשא מימות עולם והוא מ\"ש אורך ימי' אשביעהו פי' אורך ימים כענין יום שכולו ארוך והוא כמ\"ש במ\"א ע\"פ את מספר ימיך אמלא וכן מ\"ש יחיינו מיומים ימי קדם הנ\"ל ביום הג' יקימנו ונחיה לפניו בבחי' ימים שבעצמותו ממש דאיהו וחיוהי חד הנ\"ל שנק' יום שכולל ארוך בראשו כמו בסופו לפי שאין לו תחל' וסוף כנ\"ל וזהו אמלא משלימות העצמות כו' וגם כאן אורך ימים העליונים שבעצמי' אשביעהו ואח\"כ אראהו בישועתי בבחי' יחיד שנק' קדמון לכל הקדומים שמרומם לבדו מתנשא גם ממדות העצמיי' וכנ\"ל שזהו מ\"ש אנת הוא חד ולא בחושבן י\"ס כלל וזהו נק' ישועתי שהוא בכח עצמותו ממש ונק' רב להושיע בחי' מקור כל ישועות שבא למטה והוא מה שאין לו שיעור למעלה בעצם עצמותו נק' ישועתי מושיע א\"ע כב\"י וד\"ל וזהו מארז\"ל כל המאריך באחד באח\"פ בבחי' איהו וחיוהי כו' מאריכין ימיו בבחי' אורך ימים הנ\"ל יום שכולו ארוך כו' וכמו ר\"ע שהיה מאריך בא' ויצאה נשמתו באח\"פ העליון מקור חוצבו והוא ג\"כ ענין מאריכין ימיו"],[1700400094,"יחיינו מיומיים ונחיה לפניו ממש היינו ואראהו בישועתי ממש וד\"ל (ובזה יובן ג\"כ מ\"ש כי אתה ה' מחסי אתה בעצמך דווקא כו' ואז לא תאונה כו' על כפים כו' על שחל ופתן תדרוך תרמוס כפיר ותנין דקליפה כו' והיינו ג\"כ משום דבי חשק דווקא ומטעם כל הנ\"ל וד\"ל) וכמ\"ש גם כי אלך בגיא צלמות לא אירא רע כי אתה עמדי כו' וד\"ל:\n(י) <b>ומעתה</b> יש להבין המשך דברי הפסוק הזה דשמע ישראל ולמה ישראל דווקא לפי שעלה במח' כו' דהנה מבואר למעלה בענין ב\"פ הויה שזהו בחי' יחיד ואחד ע\"ד הנ\"ל בפי' מגיד מראשי' כו' ובענין המאריך בא' מאריכין ימיו כו' אך א\"כ יש להבין מה זה שהקדי' לומר לישראל דוקא שמע ישראל ה' וכו' ועוד דמשמע דבחי' המשכה זו מיחיד לאחד היינו שהוי' יחיד הוא ה' אחד בלי הפרש ביניהם דכמו דאיהו וחיוהי חד למעל' בעצמותו כל איהו וחיוהי חד גם אחר הצמצו' כשבאו ע\"ס הגנוזות בגילוי באבי\"ע ג\"כ וכמאמ' אנת הוא דמייחד לון כו' וכידוע בענין אני ה' לא שניתי בין קודם הצמצום לאחר הצמצום כו' דהיינו שגם אחר הצמצום הוא בבחי' יחיד שאין עוד מלבדו כמו קודם הצמצום וכמ\"ש אתה ה' לבדך גם לאחר שאתה עשית השמים כו' וכמאמ' אתה הוא כו' וכידוע ועיק' הכוונ' בא' זה אינו בא רק לומ' שה' אחד ביחוד הע\"ס גם באורות וכלים דאיהו וגרמוהי כו' כמו הוי\"ה הא' ביחוד העצמי שבמדותיו העצמיו' הנ\"ל ואמנם היאך ישוה יחוד דאחד ליחוד העצמי דיחיד הנה לזה אמר שמע ישראל מפני שישראל דוקא הוא בחי' הממוצע בין יחיד לאחד והוא המשוה אותם שיהיה ה' אלקינו ה' אחד בלי שינוי כלל כנ\"ל וטעם הדבר היא לפי שישראל זה עלה במח' הקדומה כו' וביאור הדברי' הנה תחלה יש להקדי' בענין ביאור המאמר הידוע שבמח' אחת צופה ומביט עד סוף כל הדורות בסקירה א' כו' שזהו הנק' מח' הכללית הראשונ' שכוללת כל התחלקות פרטיו' מראש לסוף וכן קורא הדורו' מראש כו' וכן מגיד מראשי' אחרית ומקדם כו' הכל מדבר במח' זאת הנק' מח' הכללי' שנקראת בשם טהירו תתאה והוא בחי' מקיף הכללי שמקיף לכל ההשתלשלות דאבי\"ע בהשוואה א' מראש לסוף כעגול השמים המקיפים לארץ כידוע והוא אחר הצמצו' הראשון הנק' מק\"פ וחלל כו' שנשאר בחי' רשימו ומזה נעשה בחי' המקיף הכללי הזה בראשית המשכת הקו והחוט כמ\"ש בע\"ח (משא\"כ בחי' טה\"ע הוא לפני צמצום הראשון כמבוא' בספר עמק המלך וכמ\"ש במ\"א ומה ששיער בעצמו בכח כו' שזהו נק' גליפו וחקיקה בטה\"ע היינו לפני הצמצום לפ\"ד רוב המקובלים וכמ\"ש במ\"א ביאור זה באריכות) ויובן זה עד\"מ מח' או רצון כללי הכולל כל מיני התחלקות אופני' שונים ורבים מאד לפרטי פרטיהם ונסקרי' כולם בסקירה א' ממש ברצון ומח' זו הכללית דהיינו גם לכמה מיני ריבוי רצונות ושכליי' ומדות פרטיים רבים נסקרי' הכל כא' הגם שיש רצון ושכל לכל מדה בפרט וגם יש רצון לכל רצון בפרט כולם בסקירה א' נכללים ברצון ומח' הכללי' עד\"מ מח' ורצון הכללי במו\"מ או בנין וכה\"ג ודאי יש במו\"מ כמה ענינים פרטי' שיש בו רצון ושכל ומדה מיוחד ונחלק לכמה מדות בפרטו' ומסתמא יש מקור לכל רצון ומדה והכל מתהווה אח\"כ בגלוי בפרטי פרטות אבל בעוד שחושב ורוצה בכלל כל עסק המו\"מ והבנין כולל הכל כא' בלתי נודע אז כלל שיש רצון ומקור לרצון באיזה דבר במו\"מ זה בפרטות ולפי הנראה בכללות הרצון ומח' אין לכל פרטיות הענינים המתהווי' ברצונו לעסק זה שייכות כלל לכללות הרצון מאחר שאין הרצון הזה כללי בדבר מיוחד באותו העסק רק שרוצה בכללותו לבד אך וודאי מפני שא\"א לפרט בלי שיש לו שרש בכלל ואם לאו לא היה"],[1700400095,"נמצא התהוותו בפרט כידוע א\"כ ודאי בהכרח לומ' שכל פרט רצון ורצון לרצון וכל מדה בפרט הי' כלול תחלה בהעל' ברצון זה הכללי לעסק הזה בכללותו רק שלא היה ניכר אז ואח\"כ יוצא לידי גילוי מהעלמו ושרשו בכללות הרצון כו' ועכ\"ז כשנסקרים כא' בסקירה א' הרי אין כאן התחלקות ניכרת כלל וכאילו המח' הזאת הכללית מח' א' פשוטה בתכלית כמו כל עצם פשוט שבלתי מתחלק כלל כנ\"ל ובאמת יש בו התחלקות בהעלם עכ\"פ ועתיד לצאת לידי גילוי נמצא ממוצע הוא מב' דברי' הפכיי' במה שהוא כמו עצם פשוט בלתי מתחלק וגם יש בו התחלקו' כל הפרטי' בהעלם וסובלם בסקירה א' זו ביסוד והתכללות גמורה כאילו אין בו מציאות התחלקות כלל ועוד יובן בזה שאין בו הפרש בין תחלה לסוף כי במח' כללית לא נודע מי הראש ומי הסוף מאחר שאין בו התחלקות ניכרת עד\"מ תחלת העסק דמו\"מ וסוף גמרו שנק' תחלת המח' וסוף מעשה שנק' סופא דמח' נסקר כא' ממש בכללות הרצון ומח' וכללות העסק דמו\"מ דהיינו מה שבסוף מעשה ובתחלה הכל כא' בא ברצון זה הכללי ונעוץ תחלתו בסופו וסופו בתחלתו מבלי שימצא ראש וסוף אלא שניהם כא' ממש נסקר בסקירה א' תחלה וסוף כא' כמו עיגול הכדורי שמקיף לקו ההולך ביושר מעליונו לתחתיתו שסובב בשוה לעליון ותחתון שבו מבלי ימצא ראש וסוף כידוע וכך הרצון ומח' הכללי' הסובלת תחלה וסוף יחד הוא כעיגול רוחני וע\"ד משל המצייר דבר מה במח' בכללותו מתחלתו לסופו בבת א' מבלי שיוקדם קצתו מקצתו במחשבה אלא מציירו בכללותו יחד שהוא נסקר מראשו לסופו בשוה ממש כידוע והדוגמא מכל זה יובן ביאו' ענין המאמר דבמח' אחת צופה ומביט עד סוף כל הדורות שנק' מח' הכללית למעלה וכמ\"ש בע\"ח שזהו בחי' מקיף הכללי שמקיף לכל ההשתלשלות דקו מראשו לסוף העשיה בבת א' דהיינו מה שבא בהתחלקות רבות בע\"ס דא\"ק שהוא כמו רצון לרצון וע\"ס דא\"א וע\"י ואו\"א כו' עד סוף הכל בסוף העשי' הכל נסקר בסקירה א' במח' כללי' הזאת שנק' מקיף הכללי' שבו ודאי אין התחלקו' נכרת כלל מתחל' לסוף וצופה במח' אחת לכולם יחד בשוה ממש ולכך נק' מח' אחת דווקא שהוא כעצם מח' או רצון כללי פשוט בתכלית כנ\"ל במשל רצון הכללי למו\"מ כו' ויש בו דבר והיפוכו שהרי ודאי כלול בהעלם במקיף הכללי הזה שנק' מח' כללית מכל פרט ופרט דאבי\"ע (וכמ\"ש במ\"א בענין כל היצור לא נכחד ממך כו' כי הוא צוה לפרט במח' הכללי' כו') וגם מובן שנעוץ תחלה וסוף שבקו וחוט הכל כא' במח' זאת הנק' בחי' מקיף כללי דהיינו שנסקר בסקירה א' התחלה וסוף דהיינו תחלת הרצון לרצון עד סוף מעשה שבמל' דמל' דעשי' כו' וזהו מגיד מראשית הקו אחרית הקו וגם מקדם לקו אשר לא נעשה כו' והוא בעצמו' אא\"ס שלפני הצמצום שהמדות עצמיי' דשם נק' יום שכולו ארוך בלי תחלה וסוף כלל כנ\"ל (בסי' טית) ולכאורה אין זה מובן דודאי מגיד מראשית אחרית יתכן לגבי בחי' מקיף הכללי' בחי' מח' אחת הנ\"ל שכולל תחלה וסוף כא' ממש כמובן ממשל הנ\"ל אבל מקדם למח' הכללית אשר לא נעשה גם לא בכלל איך מגיד וגם הכונה שגם מקדם אשר לא נעשה הוא מגיד כמו מראשית אחרית והרי אין שם בחי' תחלה וסוף כלל כנ\"ל אל הענין הוא משום דמח' זו הכללית בחי' ממוצע דהיינו שכלול מדבר והיפוכו שנרא' כעצם פשוט בלתי מתחל' וגם יש בו התחלקו' בהעלם כנ\"ל ולזאת במקיף זה שכולל הכל כעצם א' פשוט בלתי מתחלק כלל יאיר בו מבחי' יחיד העליון שלפני הקו כו' שהן כללות עצם מדותיו שנכללים ביחוד עצמי ביחיד עצמו כנ\"ל בענין אנת הוא חד כו' דאע\"פ שגם המדו' העצמיי' הן בהתחלקות בפרט הרי מצד בחי' העצם של כל מדה אין בהן התחלקות כלל כעצם פשוט שבלתי מתחלק ונכללים ביחיד בעצם"],[1700400096,"כנ\"ל וזהו ומקדם אשר לא נעשה שהוא במדות שבעצם אור א\"ס שלמעלה גם מרצון קדום גם לא נק' מרום לרצון כללי' הנ\"ל (אלא הוא רצון המוחלט בעצמו שנכלל בעצמו ממש והיינו מה ששיער בעצמו בטה\"ע כנ\"ל) מ\"מ הרי אין באין בבחי' יחוד כללי במח' כללית הנ\"ל להיותו ג\"כ כמו בחי' עצם פשוט במח' א' פשוטה וכוללת כל מה שעתיד להתחלק בגלוי והיינו מפני בחי' הארת המקיף עליון שלפני הצמצום שכולל כל המדות שבעצם בבלתי מתחלק וכמ\"ש אנת הוא חד ועכ\"ז יש בו כח מה שעתיד לצאת בהתחלקות כו' ונק' ג\"כ מח' א' הכוללות כל התחלקות המדות העצמיי' מתחל' לסוף ולא מתחלה לסוף ממש שהרי אין שם בחי' תחל' וסוף רק מתחלת הרצון הפשוט לסופו כמו כאשר עלה ברצונו הפשוט אנא אמלוך כידוע וד\"ל וזהו שמקדם אשר לא נעשה הוא ג\"כ מגיד מראש לסוף כמו מראשית הקו לאחריתו משו' דהא בהא תליא דמצד מח' אחת שבעצמו' הטה\"ע שכולל שם יחד נמשך ג\"כ בחי' טה\"ת זו לכלול תחלה וסוף ממש וכנ\"ל דמקדם זה הוא אמיתית המקור לתחלה וסוף שברצון הקדום כו' מאחר ששיער בעצמו בכח כדי שיבא בפ\"מ כו' (ויובן כל זה בקיצור עד\"מ מרצון כללי המוחלט בעצמו שממנו דווקא מתהווה בבחי' רצון ומח' כללית בגילוי אח\"כ ואין ההפרש ביניהם רק שזהו בהתכללות גמור בעצמותו ועכ\"ז כולל תחלה וסוף שיבא אח\"כ אבל במח' הכללית כולל תחלה וסוף ממש והא בהא תליא והיו לאחדי' ממש) ואחר הקדמה הזאת יובן איך שע\"י ישראל דווקא יהי' ה' אלקינו דבחי' יחיד ה' אחד בלי שינוי כלל כנ\"ל והוא לפי שישראל עלה במח' היינו בבחי' מח' אחת הכללית הנ\"ל שנק' מקיף כללי לכל ההשתלשלות דקו מראשו לסופו בשוה ממש ושרש מח' זו הכללי' שהיא כעצם א' פשוט הרי הוא בבחי' יחיד שהוא יחוד עצמי שבעצם מדות שבעצמו' ממש כנ\"ל (ועד\"מ מרצון המוחלט הנ\"ל כשבא לגלוי כו' כנ\"ל) והנה פי' ישראל עלה במח' היינו בבחי' עליי' והגבהה דהיינו שכל המח' כללית הנ\"ל לא הי' רק בשביל ישראל זה דווקא וכמארז\"ל ז' דברי' קדמו' במח' וישראל קדמו לכולן כו' וכמו במי נמלך בנשמתן של צדיקים כו' דהנה וודאי הגם שבמח' הכללי' נכלל תחלה וסוף כא' ממש כנ\"ל מ\"מ בהכרח לומר שיש בכללות המח' נקודה פנימי' ותמצית המכון שלזה עלה במח' זו בבחי' כללית עד\"מ מח' הכללית במו\"מ או בבנין הנה ודאי שכל אותה המח' הכוללת ראש וסוף יחד יש בזה איזה מכוון פנימי ונעלם הכל בכללות המח' בלתי נודע איה מקומו של הכוונה הפנימית כמו בעסק כללי דמו\"מ שהמכוון ממנו הריוח שיתענג מאוד מזה שזהו המכוין מן התחלה וסוף לאחר גמרם כא' וכן מתכלית מעשה בנין ביתי שהמכוון עונג שיגיע לו ממנו וכה\"ג למעלה מעלה עד רום המעלות ויובן מזה בכללות המח' האחת הנ\"ל לאחר גמרה כמו וירא אלקים את כל אשר עשה והנה טוב מאוד שזהו העונג המגיע מכללות מח' זו וידוע שזהו מ\"ש ישראל עלה במח' דהיינו ענין הכוונה הפנימי' שיגיע מכללות המח' האחת הנ\"ל עלו ישראל במח' זו בבחי' פנימיות המכוון שבה ולהיות כן ע\"י בחי' ישראל זה דווקא יהי' יחוד המדות דיחוד עם יחוד המדות דא' שוה ממש בלי שינוי כלל בין קודם הצמצום לאח\"כ לפי שבודאי גם בבחי' שרש מח' כללי' (הנק' טה\"ע) כמו ששיער בעצמו כו' ודאי הי' ג\"כ מכוון פנימי שהוא תכלית העונג ושעשועי' העצמיי' שיבא מכל זה שעלה ברצונו ומחשבתו בכלל בעצמותו עדיין (הנק' רצון המוחלט בכלל כולל כמה פרטי') ושם א' מישראל עלה במח' ג\"כ וכמ\"ש במי נמלך פי' במי נמלך בעצמותו ממש אם הרצון יוחלט בעצמו בכח כו' וישראל זה עלה בפנימי' העונג לרצון ומח' הכללית שבעצמותו ממש הנ\"ל ונמצא שכאשר ישראל זה ירד למטה בעול' העשי'"],[1700400097,"בסוף מעשה ונשלם על ידו יחודי' העליוני' שבע\"ס דאבי\"ע הגם שלא נק' זה רק בשם אחד וכמו שידוע בענין היחוד באורו' וכלים דאצילות שנק' איהו וגרמוהי כו' שזהו הכל ע\"י ישראל למטה דווקא שעושי' כל היחודי' דזו\"נ ואו\"א וא\"א וע\"י וכו' ולזה הי' כל עיקר העונג הפנימי המכוון שבכללות המח' שבעצמותו כנ\"ל ע\"כ ודאי מובן שאין שינוי כלל בין יחיד בעצמותו לאחדות ה' באבי\"ע מה שזה עלה במחשבתו העצמי' וכולא חד ממש וזהו שא' שמע ישראל דווקא שעל ידן ה' אלהינו במדות שבעצמותו ה' אחד בלי שינוי כלל בין קודם הצמצום לאח\"כ משום דאני ה' לא שניתי כלל ומה שנתצמצם מיחיד לא' רק משו' שישראל עלה במח' בבחי' פנימי' העונג לכל מה ששיער בעצמו בכח ולכך א' לישראל שמע שם ע' רבתי וד' רבתי דעד ה' בכם דווקא וזהו בראשית בשביל ישראל שנק' ראשית כו' שבשבילם שמים וארץ כא' נבראו במח' כללית שבהעלם עצמותו שנק' טה\"ע וכו' שנק' מקיף כללי לפי שישראל זה בחי' ממוצע לכלול יחיד ואחד בשוה ממש משום שעלה במח' הכללית דיחיד ואחד עלה דווקא כנ\"ל וד\"ל:\n(יא) <b>והנה</b> באמת עדיין אינו מובן תוכן ענין ב\"פ ה' שיחיד ואחד שוין ביחודם ממש כנ\"ל דהיינו שאין שינוי בין קודם הצמצום שהי' לבדו ואחר הצמצום שיש ע\"ס באו\"כ באבי\"ע ואיך יקרא יחיד אחר הצמצום לומר בו דאיהו וחיוהי חד ממש כמו דאיהו וחיוהי חד בעצמותו ואם מטעם הנ\"ל דישראל עלה במח' מ\"מ הרי בא לכלל צמצום בשביל זה יהי' איך שיהי' כו' אך הנה תחלה יש להקדים בגוף ענין הזה במה שנתצמצם מבחי' יחיד לאחד איך יוכל להיות מעצמות הפשוט בתכלי' בחי' הריבוי והתחלקות גם אחר כמה צמצומי' ועוד שהרי גם לפני הצמצום שיער בעצמו בבחי' ריבוי והתחלקות כנ\"ל אלא מוכרח לומר שגם בחי' הריבוי וההתחלקות הוא בתכלית היחוד הפשוט כמו שהיחוד עצמי ופשוט בעצמותו כו' והיינו מ\"ש דאיהו וחיוהי וגרמוהי חד ממש כמו שהוא יחיד לבדו ממש ולפ\"ז לא יקשה ג\"כ ענין ההשתוות שלפני הצמצום ואח\"כ שזהו בחי' השתוות היחוד דאחד ויחיד כנ\"ל משום דייוכל להיות בעצמותו ממש באין שינוי כלל (והיינו מפני שבידיעת עצמו הוא יודע ומשער בעצמו בכח חריבוי והתחלקו' באח\"פ ממש) וכמ\"ש אנת הוא דמייח' לון כו' וביאור הדברי' הנה תחלה יש להבין ענין הידוע מה שבאור א\"ס יוכלו לומר שאין לו שיעור למעלה ולמטה עד אין תכלית איך שייך בחי' מעלה ומטה לפני הצמצו' הראשון שהיה אור א\"ס ממלא כל החלל כו' למעלה ולמטה ואיך יפול לשון העלאה למעלה והתפשטות למטה רק אחר הצמצום דקו שם יפול לשון בחי' מעלה ומטה כו' והענין ידוע דהכוונה הוא על בחי' הכח הנעלם בעצמות אא\"ס שכלול מב' מדרגות ששניהם שקולין כי כל יכול הוא והיינו כח העליי' עד אין שיעור בעילוי אחר עילוי בעצמותו כו' וכח הירידה וההתפשטות למטה עד אין תכלית והוא מה שאנו רואי' אחר הצמצום בקו וחוט שיש בו בחי' מעלה ומטה גלוי אור ב' מדרגות הללו וקודם הצמצום היו הם בהעלם עצמותו ולכאורה אין זה מובן שהרי יש שיעור להתפשטות מראשית הקו לסופו וממילא יש לו שיעור למעלה מאחר שכל עיקר בחי' הקו הוא רק כדי שיהיה בחי' מעלה ומטה כמ\"ש בע\"ח וא\"כ נהפוך הוא מכמו שהיה קודם הצמצום וכידוע שלזה היה עיקר הצמצום בבחי' מק\"פ וחלל כו' שלא יהיה הכל בבחי' א\"ס ממש למעלה ולמטה שלא יכול להיות מקור לאבי\"ע כלל כו' אלא מוכרח לומ' דמ\"ש אא\"ס למעל' עד אין קץ כו' קאי על בחי' הרשימו שנשאר אחר הצמצום הראשון שהוא במבאחי'"],[1700400098,"כח ההסתלקות והעילוי בעצמותו וע\"ז אמר שאין קץ בעילוי אחר עילוי כו' ומ\"ש למטה עד אין תכלית קאי על בחי' הקו שנמשך להיו' מקור לאבי\"ע וכמ\"ש במ\"א שבחי' הנקוד' מורה על הסתלקות העצם עד שלא נשאר רק נקודה וגם היא בהעדר ההתפשטו' דוק' אבל הקו הוא היפוכו שבא ונמשך למטה מטה כו' אך עדיין אינו מובן בקו זה למה לא יתפשט עד אין שיעור למטה ועוד יש להבין מה שאנו מוצאים בספרי הקבלה שבקו זה דוקא יש בו מאור א\"ס עצמו שלפני הצמצו' ע\"כ יש כח בקו הזה ליחד כל יחודים דע\"ס באו\"כ וכמ\"ש אנת הוא דמייחד לון ומקשר לון דקאי על אור א\"ס עצמו ונק' אנת שמאיר בקו זה דווקא (כמ\"ש במ\"א באריכות בענין וי\"ו דוהנורא כו') אך הענין ידוע דקאי על בחי' רבוי היחודי' שוני' בג' קוין שע\"י הקו הזה מתייחדי' עד אין שיעור למטה בכלים מכלים שונים עד אין תכלית (כמ\"ש בס\"י בהתחלקו' ורבו הצרופי' דאותיו' מכאן ואילך צא וחשוב עד אין שיעו' כו') וכידוע דריבוי הכלי' נק' אין שיעור להתפשטו' למט' והיינו משום דאיהו וגרמוהי חד פי' שיש אור מאור א\"ס עצמו בקו זה שבכחו לעשות יחוד רבוי יחודי' עליוני' באורו' דע\"ס לייחדן בעצמו' המאציל עד אין שיעו' למעל' מעל' בעצמותו והיינו משו' דאיהו וחיוהי חד בקו זה דוק' וב' הפכי' הללו דלמעלה ומטה באו\"כ בא בקו זה מצד בחי' הרשימו שממנו הקו שכלול מדב' והיפוכו בחי' העלאה והמשכה וכמ\"ש במ\"א באריכו' ששרש כחות המגבילים מהרשימו ושרש ההתפשטות מהקו ושניהם היו כלולים באור עצמות א\"ס לפני הצמצום ומאיר בקו זה שאחר הצמצום וא\"כ אין שינוי כלל בין קודם הצמצום לאחר הצמצום מאחר דאיהו וחיוהי וגרמוהי חד אחר הצמצום באין שיעור למעלה ולמטה ממש כמו שהיה קודם הצמצו' ואינו מובן לכאורה לאיזה טעם היה הצמצום מתחלה מאחר שאינו מצמצם כלום ובאמת עיקר הצמצום הי' כדי שיהי' בחי' עמל' ומטה דווקא כידוע ועוד יש להבין במה ששיער בעצמו קודם הצמצום ששיעור זה ודאי הוא צמצום בעצמו עד אין שיעור למעלה מהן וגם הרי נק' אותיות וכלים הבאים בהתפשטות שזהו דבר והיפוכו א\"כ אף קודם הצמצום היה בב' מדריגות דאיהו וחיוהי וגרמוהי שאחר הצמצו' הוא באו\"כ ממש ולפ\"ז יובן ג\"כ ענין הנ\"ל איך שיוכל להיות בחי' יחוד עצמי ופשוט בריבוי והתחלקות כמו שהוא יחיד לבדו וזהו גם בריבוי והתחלקות שבעצמו שלפני הצמצום ובזה שוין יחיד ואחד משום דהיינו אך ממש מטעם הנ\"ל דאור א\"ס למעלה ומטה עד אין שיעור בהעלם עצמותו שנק' יחיד בחיוהי וגרמוהי בעצמו הוא עצמו אותו האור שבקו וחוט שמייחד לון ביחוד עצמי ופשוט באו\"כ ממש כנ\"ל וד\"ל ומעתה יש להבין בכל עיקר ענין הצמצום מהו דודאי כל עיקרו היה רק לצמצם ולהסתיר עצמו' אא\"ס כמ\"ש ישת חשך סתרו כידוע ואחר שאין שינוי כלל וכלל אין זה נק' צמצו' והסתר כלל והנה הגם שבכל זה מתורץ ענין הקושי' הנ\"ל איך נתצמצם מיחיד לאחד שהוא מיחוד פשוט להיו' בחי' הריבוי והתחלקו' כו' מאחר שהיחוד בריבוי זה כמו בעצמו מטעם הנ\"ל אין זה צמצום כלל וכלל עכ\"ז עדיין אינו מובן מאחר שבידיעת עצמו ממש יודע ומשער בעצמו שיעור וצמצום דריבוי זה והריבוי היפך היחידות שבעצם הגם שבריבוי זה יש כח דעצמו משום דאיהו כו' מ\"מ איך יהיה דבר והיפוכו כו' מיחידות לריבוי כו' אלא מוכרח לומר שלזה היה ענין הצמצום הזה ואינו הסתר לאור עצמותו לגמרי אלא שאינו מאיר כאור הראשון כמ\"ש בע\"ח בענין הרשימו וביאור הדבר תחל' יש להבין בענין מח' כללי' הנ\"ל דהנ' מבוא' למעל' בענין מח' כללית דכוללת"],[1700400099,"כל פרטי התחלקות ענינים נבדלים לאין שיעור ועכ\"ז במח' זו עצמה לא ניכר שום התחלקות כלל עד שנקראת בשם מח' א' פשוטה בתכלית והדמיון לזה מבואר למעלה בשני דברים הא' כמו עד\"מ כאשר עולה רצון כללי למו\"מ או בנין גדול שעולה כללותו לבד כו' והב' כמו שמצייר דבר מה בכללותו בלבד כו' ושני הדמיונות הללו מורי' ענין וכוונה א' שהוא סובל ב' הפכי' פשוט ומורכב שהרי הרצון בכלל הבנין ומו\"מ פשוט וגם מורכב מכמה חלקי' בהעלם כנ\"ל ויש עוד אמצעי ביניהם והוא אשר נסקר הרבוי חלק' כא' שאינו לא כעצם הרצון הפשוט שאין בו ענין סקירת הפרט לכלול ולא כמורכב שיש בו התחלקות וקדימה לקצתו על קצתו כו' והנה אנו רואים עוד שמח' כללית הנ\"ל הגם שנק' בחי' מקיף כללי לכלול כל חלקי הפרטי' שבה אבל לגבי עצם הנפש שמושלל מבחי' רצון ומח' לגמרי (גם מרצון מוחלט הנ\"ל) הרי כל עיקר ענין התהוות מח' זו הכללית בחי' ירידה וצמצום העצמו' מאד והוא מה שמתכווץ עצם הנפש בעצמ' כדי לבא לכלל רצון ומח' ולא עוד אלא שהמח' הזאת היא הנק' בשם מח' אחת לבד כי היא פשוטה בסקירה א' לבד ואנו רואים שאדם המצמצם א\"ע במח' א' צמצום א' צמצום הזה צמצום גדול הוא ביותר כי מח' א' לבד תקצר לנפש להתצמצם בה זמן מה כו' משא\"כ מחשבות רבות וחלוקות ברבוי התפשטות תתפשט הנפש בהן יותר ולא תקצר לנפש כל כך והצמצום בעצם בא ומכח העצם דווקא כמו אותו כח הבא בהתפשטות ורבוי ממש בשוה כידוע ואמנם במחשבה כללית הנ\"ל שבאה לריבוי פרטי' אח\"כ יש בה צמצום והתפשטות יחד והוא בחי' האמצעי הנ\"ל אשר נסקר כל ריבוי החלקי' הפרטי' כא' וכמובן מב' דמיונות ומשלים הנ\"ל וד\"ל ומעת' יובן בדוגמא למעל' בבחי' מח' כללי' (שנק' טה\"ע ותתאה כנ\"ל) שמה שבידיע' עצמו הפשוט משער בריבוי והתחלקו' בעצם (שנק' גליפו בטה\"ע) יש בזה צמצו' גדול במה שהמח' אחת לבד פשוטה בסקיר' א' כוללת כל מה שמשער בריבוי כו' ובריבוי זה הנכלל יש כח העצמות בהתפשטות דאיהו וחיוהי הוא בא בב' מדרגו' בעצמו שהוא כמו דבר והיפוכו כנ\"ל והאמצעי הוא בחי' מח' אחת הכוללם יחד והוא מה שנסקר הריבוי כא' כנ\"ל ונמצא מבחי' יחיד הפשוט בעצם בא לבחי' צמצום זה שנק' מח' אחת פשוטה וכולל ב' דברי' צימצום העצמות והתפשטו' שלו והוא כח ובחי' מעלה ומטה שבא אח\"כ למטה בטה\"ת שנק' אחד פשוט בכלל והוא מח' כללית הבאה מהעלם העצמו' לידי גילוי לכללו' כל השתלשלות דאבי\"ע ממש להקיף ראש וסוף ממש כנ\"ל וה\"ז כמספר האחדי' רבי' שנכללים הכל ממש מספר א' כולל כמו אלף וכה\"ג שודאי עתיד להתחלק במספר אלף חלקים ממש וכן להיפך כאשר כבר נספר לחלקיו ונתחלקו ממש יכולים להתאחד במספר א' כך מח' שצופה כו' בסקיר' א' מראש הקו לסופו הרי כולל בעצמו ב' דברים צמצום והתפשטות ובחי' האמצעי המחברם יחד שהוא מה שסוקר הכל כא' כמו במח' כללית שבעצמות ממש הנק' טה\"ע רק שזה בעצמות וזה יוצא להיות מקיף לעולמות ואמנם כל מה ששיער בעצמו בא לידי גילוי במח' המקפת לאבי\"ע בכלל ובפרט ולהיות שאין ערוך בין זה לזה כמו המצייר דבר מה בכלל ובפרט שודאי יש הפרש גדול בין ציור זה שבעצמות לציור אותו הדבר שנבדל מן העצם ובא בגילוי חוץ מעצמו כמו המצייר כדור הארץ שכבר נבדל מעצמו שהמחשבה הוא בדבר שחוץ מעצמו ואעפ\"י שלא יתכן לומר כן למעלה שאין לך דבר חוץ מעצמו וגם מה שיודע את הכל הוא בידיעת עצמו ולא בידיע' שחוץ ממנו כידוע מ\"מ לענין בחי' העלם וגילוי שייך לומר גם למעלה שהוא בלתי ערוך בין העלם מח' בכלל ובפרט בעצמו למה שיצא אח\"כ בבחי' גילוי ע\"ד דוגמא מרצון המוחלט בעצמו שנתעורר לבא לרצון בגילוי כד שיובא בפ\"מ וד\"ל ומעתה"],[1700400100,"יתורץ היטב ענין הצמצום שהוא בין מה ששיער בעצמו למה שבא בגילוי בקו בבחי' מקיף ופנימי בכלל ובפרט כמו שהיה בעצמו שהוצרך להיות הפסק בנתיים והוא הנק' מק\"פ וחלל ריקן כידוע ואמנם אין צמצום זה רק להיות במדריגה נבדלת שלא כאור הראשון ממש שהוא מה ששיער בעצמו במח' כללי' ופרטי' כו' אבל לא צמצום בהעלם והסתר גמור כנ\"ל ולזה הטעם נמצא כח של עצמו' אור א\"ס הנק' יחיד פשוט בקו וחוט באבי\"ע ג\"כ כמו שהוא בעצמו בב' דברים שביחוד או\"כ שהוא ענין איהו וחיוהי וגרמוהי חד כנ\"ל מפני שבזה שוין יחיד ואחד דהיינו טה\"ע וטה\"ת מטעם זה שאינו צמצום גמור רק שאין אורו כאור הראשון ממש וכמ\"ש באורך נראה אור (ורישא דקרא כי עמך מקור חיים ית' בסמיוך) פי' באורך בחי' טה\"ע בכלל ובפרט שנק' מח' כללי' בעצמו ונראה אור כזה שנק' הארה דהארה בבחי' טה\"ת שהוא מקיף כללי דאבי\"ע ואמנם אין הפסק גמור ביניהם כמכך וכה\"ג רק מק\"פ וחלל כו' שאין זה הפסק גמור רק העדר גילוי אור העצמי כמשל הפוסק מלחשבו מחשבת עצמו וחושב מח' זו עצמה בדבר שנבדל מן העצם להביאה לענין מעשה וכה\"ג וד\"ל (משא\"כ מאצי' לבי\"ע יש מסך מפסיק ושם נפסק הארת הקו וכמשי\"ת בענין בשכמל\"ו אבל ע' רבתי דשמע וד' רבתי הוא ביחוד גמור בלתי הפסק כלל וא נבדל ביניהם והיינו ישראל שעלה במח' הכללית שעליהם א' עד ה' בכם דוקא וד\"ל):\n(יב) <b>והנה</b> עדיין יש להבין בפי' ה' אלקינו דאלקינו זה קאי בין ב' הויות דיחיד ואחד הנ\"ל מה ענינו ובהיות ידוע דבחי' בינה נק' אלקי' חיים כמ\"ש בראשית ברא אלקי' בראשית בחוכמתא ברא אלקים בבינה והוא בי\"ת דבראשית דבחכמה יבנה בית ונק' היכלא דנקוד' חכמה כידוע ולכאורה אין זה מובן דהלא מבואר למעלה דהוי' הא' קאי בבחי' יחיד שהוא ע\"ס הגנוזות בעצמות ממש ושם הוי' זה כולל ע\"ס כח\"ב כו' שבעצמו' ממש וא\"כ מה ענין אלקינו זה דווקא שאומר שה' אלהינו ה' אחד אלקינו דווקא שהוא בבחי' בינה שבעצמות שנק' מבין ולא בבינה ידיעא כו' ולשון אלקינו משמע שהוא שלנו דוקא דהיינו אלקי ישראל שעלה במח' שהזכיר קודם כנ\"ל וכו' אך הנה יש להקדי' תחלה בביאור הפסוק דכי עמך מקור חיים באורך כו' דלא דמי רישא לסיפא וסיפא לרישא דרשיא דקרא מדבר במקור חיים וסיפא מדבר בענין אור וחיים ואור ב' עניני' הן ולא עוד דגם אם ענין א' הם כמ\"ש כי טוב חסדך מחיים וחסד נק' טוב וטוב נק' אור וכתיב באור פני מלך חיים למה סותר צסיפא לריש' כי עמך משמע עמך ממש לאחדים בלי שינוי המהות ובאורך נרא' אור ה\"ז בא בשינוי המהות הנק' האר' דהארה כידוע והנה מבואר למעלה דסיפ' דבאורך נראה כו' שאי בענין טה\"ע וטה\"ת הנ\"ל שנראה אור ולא כאור הראשון ממש כו' כנ\"ל ולפ\"ז כי עמך מקור חיים דרשיא דקאי על ע\"ס הגנוזות שבאו לידי גילוי אחר הצמצום כידוע סותר זה דמשמ' כי עמך ממש בלי שינוי כלל וכלל ובאמת משמע דסיפא פירושא דרישא דמה שא' כי עמך מקור חיים מפרש דבר זה היאך הוא והיינו מ\"ש באורך נראה כו' אמנם הנה באמת רישא וסיפא הכל ענין א' וזה פי' וביאור לזה דהנה מ\"ש כי עמך מקור חיים יש להבין מהו כי עמך דווקא ומהו מקור חיים ותחלה יש להקדים בכללו' ענין יחודא עילא' דע\"ס דאצילות איך שמיוחדי' במאצילן כדמיון שלהבת הקשורה בגחלת כמ\"ש בס\"י וכה\"ג דהנה לכאורה ממשל ודמיון זה כשלהבת הקשורה בגחלת לא יובן רק בדרך ענין העלם וגילוי בלבד שאין הגילוי מן ההעלם דבר חדש במציאות כלל וכלל דהיינו שאותו הדבר הנגלה כבר היה כמו שהוא במציאותו ממש בעילה שלו רק"],[1700400101,"שהיה כלול שם בהעלם עדיין כו' שאין כל חדש רק התגלותו מהעלמו לבד כעובר שיוצא מהעלמו בבטן וכאוצר הנגלה מהעלמו בקופסא וכך הוא בהעלם וגילוי דמח' ודיבור שמהות הדיבור היה כלול במח' וכן גם מהות המדו' שבלב שיצאו לגילוי היו במציאות ממש במוח כלולים שם בהעלם וכמו שלהבת שקשורה בהעלם הגחלת שהוא דמיון כולל כל אלה וכיוצא בהן דגם ששלהבת גלוי' מהות אחר שלא כצהו' השלהבת כמו שהיא בהעלם בגחלת היינו אך ממש רק שנראי' במהות גילוי אור כך מהות התפעלות המדות אינם מהות חדש אלא מן מהות התפעלות מדות אוי\"ר שבמוח שבהעלם ממש ואין כל חדש רק מה שיצאו לגילוי בלב כידוע ואעפ\"י שנק' המדות שבלב בשם תולדה אין זו תולדות התהוות חדשה רק כלידת הולד שיצא מהעלמו ולא כתולדה של טפה רוחניות שבמוח שמתהווה מציא' חדש וגם לא כהתהוו' צומח דעשב ותבוא' מכח הצומח שבארץ הרוחני לפי שכל כח המוליד שבחי וכח המצמיח שבארץ יש בו ענין ובחי' התהוות חדשה שנק' התהוות יש מאין עכ\"פ כידוע וסימנו שמהווה לאין שיעור ולא יכלה כוחו כלל ואם היה בדרך התהוות עילה ועלול שנק' התהוות יש מיש כמו התהוות המדות משכל ודיבור ממח' וכה\"ג ודאי היה כלה כח שפע זו לפי שכלה כח עצם מציאותן שכבר מוגבל הוא ועומד בלי תוס' ומגרעת גם בעודנו בהעלם וכמו שאנו רואי' שיכלו אותיות הדיבור כשיכלו קצבת אותיות המח' וכן יכלה התפעלות הלב כשיכלו המוחין שבמדות שבשכל והכרח יש הפסק למדו' שבשכל כי קצובים המה ואם אנו רואי' שלא יכלה התפעלות האהבה שבמוח לדבר הנאהב והיראה מדבר שמפחד הימנו אין זה מצד עצם השכל והטעם של אוי\"ר זו רק מצד כח עצם הנפש שמתפעלות באוי\"ר זו וכו' והנה יש עוד מדריגה ממוצעת בין בחי' העלה וגילוי הנ\"ל ליש מאין החדש ממש הנ\"ל והוא הנק' בלשון כח ופועל דהנה כל מה שיוצא לידי פועל מכח הפועל אי אפשר לומר שזהו כמו העלם וגילוי הנ\"ל שהרי פעולה זו הנגלית היתה בהעלם כלולה בכח הפועל שבכחו לפעול כל פועל גם טרם שפועל מאומה וא\"כ אין כל חדש בגלוי הפעולה רק מה שיצאה לגלוי מהעלמה בלבד כנ\"ל בכל ענין העלם וגלוי כו' דודאי אין דמיון בין זה לזה כלל דבכח הפועל הרוחני לא היה מציאת פעולת גשמי' זו כלל וכלל רק מה שהיה בכח הפועל לפעול גשם הזה אין זה רק כח הרוחני כולל הנק' היולי ופשוט ולא יגרע כוחו מכח הצומח הרוחני שודאי הוא כח היולי ופשוט להצמיח כמה תבואות ואילנות שא\"א לומר בו בחי' העלם וגלוי הנ\"ל כלל אדרבה קרוב הוא לבחי' מהווה התהוות חדשה מאין ליש כמו התולדה כי הצמיחה משתווה לתולדה ממש כמ\"ש והולידה והצמיחה (וכמשי\"ת) כך א\"א לומר בכח הפועל הזה שיש בו בהעלם איזה פעולה מיוחדת במציאת רק כח היולי להניע כל תנועה ופעולה קרוב הוא לערך הגלוי הנפעל מכחו עד שידמה לומר שגלוי זה הנפעל מהעלם כח הפועל בא כדמיון גלוי השלהבת מהעלמה בגחלת ואינם דומי' זה לזה דבגחלת הרי יש מציאת אותו הניצוץ הנבדל ויוצא בגלוי ולא בבחי' כח והיולי יקרא אלא בשם מקור והתפשטות יתכן לקרותו כמו כל בחי' עצם והתפשטות שא\"א לומר שההתפשטות מן העצם יוגבל לחלקי' כי וודאי העצם שאינו מוגבל התפשטותו בלתי מוגבלת ואם הוא מוגבל התפשטותו מוגבלת ואמנם התפשטות זאת אינו דומה לגלוי ההעלם שישנו במציאותו בתחלה ממש כנ\"ל והתפשטות זאת לא היתה ניכרת במציא' כלל בעצם וגם היא בלתי מוגבלת כמו העצם משא\"כ הגלוי מהעלם שהוא מוגבל כנ\"ל וא\"כ א\"א לומר בהתפשטות מן העצם שאין כל חדש בו כהעלם וגלוי"],[1700400102,"וגם א\"א לומר בו שידמהלהתהוו' חדש' יש אמין שהרי אין התפשטות זו חדשה מעיקר' שבודאי כח העצם מביא להתפשטות זו בגדר בלתי מוגבל כמו שהוא. כנ\"ל וכמו כלו התפשטו' זאת של הפעולה הנגלית הבא' מכח של הפועל העצמי שכולל בכוחו לפעול כמה מיני התפשטות פעולות אשר לא יגמור ויגבול פעולותיו גם אם יחיה אלף שנה ויותר דכמו שעצם כח הפועל לא יכלה כל זמן שהוא חי וקיים כך התפשטותו לא תכלה ותוגבל לעולם וזהו שלא כענין העלם וגלוי שיכלו בעילה ועלול כנ\"ל וגם פעולת הגשם לא היה במציאת בעצם כח הפועל כנ\"ל ואעפ\"כ א\"א לומר שהתהוות חדשה היא לגמרי כנ\"ל ולפ\"ז מה שנק' כח ופועל לא יקרא רק בשם התפשטות ולא שם התהוות ומהווה ומעתה יש להבין במה שנק' היולי ופשוט אם שם מתהווה יקרא להוות חדשות ממש כתולד' וכה\"ג או שם כח ופועל שהוא עצם והתפשטו' יקרא לפי שאנו רואי' בו מעין שניהם שהן כמו ב' הפכי' חדש ואינו חדש שהרי כמו גלוי ההתחכמו' מכח השכל שכח השכ' נק' כח היולי ופשוט שבכוחו להמציא כל מיני השכלות בגלוי בכל ענין שירצה בו כו' הנה וודאי אינו דומה להתפשטו' הפעול' מכח הפועל שגם כח הפועל לכאורה יחשב גם הוא בשם כח היולי ופשוט שכולל בעצמו כמה מיני פעולות שעדיין לא פעל ולא יפעול לעולם כמו כח ההיולי של השכל להתחכם גם טרם שידע כל חכמה ולא יתחכם בהם לעולם כו' דודאי אינם דומי' זה לזה להקרות בשם א' אם בשם היולי או בשם עצם והתפשטו' הנ\"ל דהנה מה שיש בכח הפועל לפעול כל תנועה זהו הכרחית טבעיות עצמיות שכבר הוכן בטבע הכח הזה להניע כל תנועה בגילוי דוק' וכח המניע הזה ישנו במציאותו וטבעו תמיד להניע בגלוי דוקא ולא יקרא התנועה בגלוי רק התפשטו' העצם לבד כנ\"ל משא\"כ ההתחכמו' מכח המשכיל ההיולי הרי עדיין לא יש בכח זה המשכיל הכרח כח טבעי להוליד ולהמציא שכל והתחכמו' זאת שהרי אנו רואי' שגם באדם שיש בו כח המשכיל להשכיל כל דבר חכמה הרבה יטריח למצוא שכל והתחכמו' ולא יכול ואם הי' כמו טבע כח המניע להניע למה לא אלא ודאי שמהות התחכמו' כמו תולד' חדשה תקרא שתוליד ותצמיח מכח המשכיל ההיולי כדרך שתצמח העשב מכח הצומח ושבארץ דגם שבודאי יש כח הצומח להצמיח אין זה נק' עצם והתפשטות שיכריח הטבע בתמידי' שהרי הרבה מקומות בארץ שלא יצמיחו ולא יעשו פרי תבואות ועשבי' ואילנות כלל וכן כח המוליד שבתי יחרב ויבש כמעיין מן התהום שזהו מפני שנק' תולדה חדשה וכמ\"ש והחכמ' מאין תמצא מאין ליש דווקא (ועכ\"ז אינו דומה לכח המוליד שבטפה שהוא נק' מהווה מציאת נפש חדשה והמשכיל ההיולי אינו הוא מצמיח שכל לבד אבל עכ\"ז נק' בשם צומח שהו' כהתהוו' יש מאין ולא התפשטו' לבד) ואחר כל זה יש להבין בענין הבדל שבין אור למאור גשמי ורוחני שהוא אור וחיות הנפש בגוף דהנה כמו כח התנועה במניע כך בודאי אור המאיר הכלול במאור עצמו שיקרא בשם התפשטות מן העצם (ולא העלם וגילוי שהרי מה שנק' הארה כמו מציא' חדשה שלא היה במאור עצמו ונק' זיו המתפשט שהמאור בלתי התפשטו' זיו יקרא בשם מאור כידוע) ובאמת אין זה דומה רק כמו חיות הנפש שמחיה בגילוי כמו שהוא כלול בהעלם בעצם החי שבכחו להחיו' כל דבר כידוע שבודאי זה בא כמו בבחי' התפשטות ועצם הנ\"ל ואינו הכרחי בקירוב הערך כמו תנועת המניע רק דילוג הערך ממהו' למהות שהרי ברצונו לא יאיר ויתפשט כלל בגוף כדמיון גלגול הנפש בדומם כידוע וממה שחסרון אור בכח הראוי בכלי העין אינו עושה גרעון בעצם אור הראיה הכלולה בנפש שהרי סומא מוליד שלם ועכ\"ז הנפש עצמה תתפעל ממאורעו' קלקולי כלי חיות המאירי' מן הנפש"],[1700400103,"בגוף א\"כ אין זה לא כעצם והתפשטות כו' ולא כהעלם וגילוי רק ממוצע מורכב משניהם וזהו הנק' בשם התלבשו' (המבואר במ\"א באריכות וית' בסמוך) וא\"כ יובן מזה בדמיון דשלהבת הקשורה כו' שנק' העלם וגילוי שזהו בבחי' התפשטות ועצם ואין זה דמיון אמיתי אלא בבחי' כוחות הנפש המתפשטים שנק' בשם התלבשות דוקא כנ\"ל וד\"ל:\n(יג) <b>אך</b> הנה באמת א\"א לומר באור וחיות הנפש בגוף שיקרא רק בשם התלבשות לבד כנ\"ל אלא בשם התפשטות יקרא שהרי יש ב' מדריגות גופין ולבושין כמ\"ש כמה גופין תקינת לון דאתקריאו גופין לגבי לבושין דמכסיין עליהון כו' וידוע שזהו בחי' ע\"ס דאצילו' כשהן בכלים כמו חסד דרועא ימינא כו' שנק' גופא ואינו נק' לבוש כו' וכאשר אנו רואים שהלבוש נפרד ונבדל מן עצם הנפש הרבה יותר מן הגוף והוא בב' דברי' הא' מה שהלבוש דבר זר נחשב ולא יתאחד כלל בנפש להיות התפעלות הנפש מחסרון וגרעון או יתרון שבו ופושט ולובש בלתי שינוי בעצם כלל והב' מה שלא תניע הנפש תנועה בלבוש גם כשירצ' ויחשוב שינוע משא\"כ כשירצה להניע ידו תנוע מ\"ד ממילא וב' דברים הללו מורי' אחדות וחיבורוקישור חיי הגוף עם הנפש עצמה שאינו כזר נחשב ואע\"פ דלכאורה חיי בשר הגשמיי' שבדם הוא הנפש בבחי' לבוש זר בא אור וחיות הנפש שם כי הנפש רוחניות היא לגמרי ומורכבת מד' יסודות רוחנית והדם שבו הנפש מורכב מד\"י גשמיי' ואיך יתחבר רוחני' בגשם בבחי' חיבור התפשטות שהי' מתפעל וינוע בתנוע' כאילו הן א' ממש ולכאורה גם הצומח דלבוש לא רחוק ערכו המורכב מיסודות גשמיי' מערך הרכבת החי בדם שבו ועכ\"ז הפרש גדול ביניהם שבחי בא הנפש בבחי' התפשטו' וחיבור עד שתתפעל הנפש ממאורעות חיי הגוף בגרעון או יתרון וגם תניע תנועות חיי האברים כאילו הן דבר ומציאות א' כנ\"ל אבל במה שלא יהי' גרעון בעצם הנפש מגרעון אחר וחיות הגוף כסומא שמוליד שלם כנ\"ל בזה נראה שאינו בא רק בבחי' התלבשות כנ\"ל וענין ההתלבשות כזר נחשב כנ\"ל ולכאור' זהו כדבר והיפוכו אך הענין הוא דיש יתרון מעלה בלבוש מה שאין בהתפשטו' דהיינו במה שיוגדר המלבוש בלבוש זה והוא מה שיתפס בו כולו ולא יצא ממנו כ\"א בהפשט' שפושט א\"ע מן הלבוש משא\"כ בהתפשטות שאין כולו נתפס בו וא\"צ הפשטה כי אינו מוגדר ומובדל כולו בהתפשטות זאת ככח הפועל בפעולתו וכזיו ואור השמש המתפשט שאין עצם השמש ועצם הפועל מגודר בזיו המתפשט (ובזיו וכח השמש לא יתכן גם בחי' התפעלות כי אינו נק' התפשטות גמורה משא\"כ הפעול שיתפעל מפעולתו מפני שהוא בהתפטו' דבר מה חוץ מן העצם והוא הכח שבעצ' שבא לחוץ משא\"כ הזיו ממילא יבא מן השמש ולא יקרא בשם התפשטות דבר מה מעצם השמש כו' וכמ\"ש במ\"א בענין ההפרש בין ג' שמות הללו דאור וכח וחיות הנזכ' בלק\"א שאין א' דומה לחבירו דאור השמש וכח הפועל וחיות הגוף חלוקי' זה מזה בכמה אופנים שונים) אבל בחיות הגוף הרי הנפש עצמה מגודרת ונתפסת בהאברי' כי א\"א לאות' הנפש שבגוף זה עכשיו לבא בגוף אחר מפני שכבר נתפסה בזה וכמו שאדם המגודר בלבוש ובית זה אינו נתפס אז בבית ולבוש אחר (וראי' ממה שמצינו בזהר באליהו שלא הי' באדרא מפני שהי' מציל באותה שעה לרמב\"ם וחבירו לפי שהוצרך להתפס בגוף שאז לא יוכל להיות במקום אחר ומה שאליהו נמצא בכמה מקומות ששם ברית מילה זהו בחי' הארתו כמו שהוא בלא גוף כמ\"ש במ\"א) וכך הוא באור חיות הנפש בגוף אעפ\"י שבאמת באה בבחי' התפשטו' שהוא בקשר וחיבור א' עד שתהי' מתפעלת ממקרי הגוף מ\"מ באה ג\"כ בבחי' התלבשות והוא מה שנתפסת בו (ואמנם גלגולי' דנפש"],[1700400104,"בדומם נק' תפיסה והלבשה בלתי התפשטו' ע\"כ שכל בדומם ולא תנועה משא\"כ נפש בגוף ששניהם יש בה התפשטות והתלבשות כמ\"ש יוצר רוח האדם בקרבו כשהוא נתפס ונתלבש כמו ויצר בחרט כו') ומצד בחי' התלבשות דנפש אין ערך לחיי בשר עם חיי רוחני דנפש עצמה עד שלא יהי' שינוי בעצם מגרעון אור חיות העין כנ\"ל כי אין זה רק העדר הגילוי בכלי העין וקרו' הוא לבחי' העלם וגילוי [שבגלגולי' הנפש בהעלם בדבר שבו נתגלגל ובגוף בא בגילוי כו'] ולפ\"ז בחיו' הנפש בגוף מורכב מג' דברים בחי' התפשטות והתלבשות וגילוי ההעלם הנ\"ל וד\"ל ומעתה יש להבין בענין המאמר הנ\"ל דגופין תקינת לון כו' שיש בזה שלשה מדרגות נשמתא וגופא ולבושין כו' וידוע דבחי' אורו' וכלים שנק' גופא לפעמים נק' לבושי' ג\"כ וכמ\"ש עוטה אור כשלמה שהוא אור החכמה שנתלבש בה כשלמה כו' וכמאמר בעשרה לבושי' נתלבש כו' בחכמ' ותבונה ודעת כו' ולכאורה אורות הללו דע\"ס דאצי' הן בבחי' העלם וגלוי דווקא לפי הדמיון דשלהבת הקשורה הנז' בס\"י ולא בבחי' התפשטות מן העצם ככח הפעול אלא כאור וחיות הנפש הכלילה בעצם תחלה להחיות ואח\"כ יוצא לידי גלוי להחיות הגוף כידוע והיינו חכמה מוחא כאור השכל המאיר בכלי המוח וכן חסד דרועא וכה\"ג וצריך לומר לפ\"ז דשלהבת הקשורה אע\"פ שדמיון גשמי הוא אבל הכוונה בו כהעלם אור חיי רוחני דנפש שבאה לידי גלוי בגוף כך הוא העל' השלהבת כשקשורה בה שלא ניכר במציאות שלהב' כלל ונבדל ויוצא ניצוץ (ודלא כדלעיל שנק' יש מיש ממש כמטמון הנגלה אלא כמו מח' ודבור) וזהו פי' אצילות מלשון ויאצל מן הרוח כו' שהובדל חלק מחלק כמו ניצוץ מן השלהבת ממש ותחל' הי' רוח זה כלול בעצם רוחו של משה ונבדל ויצא לחוץ ותנח רוחו על הזקני' וכך למעלה אפיקת י' תיקונין אפיקה זהו יציאה מהעל' העצמות בשלהבת היוצא מן הגחלת נק' אצילות [וכן לשון אצל וסמוך כמ\"ש במ\"א שזהו מ\"ש דאיהו וחיוהי חד שמיוחדים בעצמות גם לאחר שנבדלו וכמ\"ש כי עמך מקום חיים וכמשי\"ת] ואמנם הרי נקרא בשם אורות אור החכמה אור החסד וכה\"ג שזהו כדמיון אור וזיו השמש שהוא בבחי' נבדל מן העצם לא ככח הפועל (וגם אינו נק' מתפשט דבר מה מן העצם כנ\"ל לכך אינו בבחי' התפעלות ושינוי כו' כנ\"ל וז\"ש ע\"ס בלי מה בלי מהות כו') ושניהם אמת דהנה מבואר למעלה בהפרש בין מאור ואור גשמי לרוחני שהאור גשמי דמיונו כתנועת החי שהכרחי הוא וזה א\"א לומ' למעלה באורו' דע\"ס כי ברצונו הפשוט האצילן כידוע אלא כאור רוחני שהוא אור חיות הנפש בגוף דוקא ואמנם כמו שאור גשמי בלתי מתפעל ומשתנה כך אורות דע\"ס בזה כדמיון אור השמש וכמ\"ש באורך כו' וכתיב אני ה' לא שניתי וכתיב כי שמש ומגן כו' ועכ\"ז נק' בשם גופא כדמיון חיי הנפש בגוף ממש שהוא מורכב מב' דברי' התפשטות והתלבשות שהוא כבחי' העלם וגילוי (ולא ככח היולי ופשוט שזהו ערך קרוב לכח המוליד שהוא יש מאין שאין זה רק למעלה דע\"ס שבעצמו' כמשי\"ת בסי' שאח\"ז) וז\"ש וכד אנת תסתל' מינייהו אשתארו כו' כגופא בלא נשמת' שזהו בחי' הכלי' בלא אורות דנשמת' היינו בחי' אורות דע\"ס כמו שהן נמשכין ובאין ומאירי' בכלים מכלי' שונים כדמיון אור וכח השכל שבנפש שמאיר ובא בכלי המוח וכה\"ג וזהו חכמ' מוחא כו' כידוע ובחי' הכלים דאורות הללו נק' גופא (וע\"ז א' איהו וגרמוהי חד כמו דאיהו וחיוהי חד כו') ואמנ' אנו מוצאי' במקו' אחר שאורות דע\"ס באי' בבחי' לבושי' ג\"כ לגבי העצמו' וכמו שא' איהו תפיס בכולהו עלמין ולית מאן דתפיס בי' ופי' תפיסה הוא בחי' התלבשות הנ\"ל שהרי א' ולית מאן דתפיס בי' שאין זה כאור בכלי שנק' חומר וצורה שהוא בבחי' התפשטות הנ\"ל שהכלי יש בו תפיס' ממש באור ומתאחד בו ממש כנ\"ל בענין תנועת"],[1700400105,"האיברים ומהתפעלו' הנפש בהתפעלות האברים כו' וזהו היפך התלבשות דאיהו תפיס ולית מאן דתפיס בי' שזהו כאדם שנתפס בבית כנ\"ל ואעפי\"כ הנה גם זה אמת מטעם הנ\"ל בחיי הגוף שנבדל ערכו מחיי הרוחניות דנפש עד שנק' ג\"כ בשם לבוש לבד ולכן יתכן לומר בעשרה לבושים נתלבש כו' בחכמ' שאור החכמ' הגם שנק' אור נאצל מן העצמות ע\"ד זיו המתפשט או כאור השכל שבנפש שמאיר במוח כו' מ\"מ נק' ג\"כ בשם לבוש כי וודאי רחוק ערך אור השכל שבמוח לאור השכל שבעצם הנפש כשנק' נפש המשכלת כידוע עד שנק' לבוש זר לגבי' (כערך לבוש התחכמו' ענין דבר מה שנק' לבוש לגבי כח השכל ההיולי שזהו בבחי' צומח שנק' לבוש כתרגום תדשא הארץ תתלבש כו' שהרוחני מתלבש בגשם מפני שאין ערך ביניהם וכנ\"ל בענין התולדה והצמיחה כו') ואמנם הנה יש יתרון מעלה בלבוש במה שמגודר בו ונתפס כולו בו עד שצריך להפשט' כו' וכך איהו תפיס בכולהו עלמין אע\"ג דלית מאן דתפיס בי' וכמ\"ש את השמים כו' אבל בכח המתפשט אינו כן כנ\"ל וזה א\"א למעלה דכאשר נתפס באבי\"ע מגודר הוא שבלתי יוצא בלי הפשטה כו' שהרי נאמר השמים ושמי השמים לא יכלכלוך כו' מרום וקדוש כו' אי זה בית כו' אלא נתפס ואינו נתפס והיינו שא' ולית מאן דתפיס בי' שאם היה כתפיסת אדם בבית הרי יש מי שתופס בו וזהו מארז\"ל הוא מקומו של עולם ואין העולם מקומו הרי ב' הפכי' בנושא א' דהיינו הוא מקומו של עולם דתפיס בכ\"ע ואין העולם מקומו כמ\"ש המלאכים איה מקום כבודו לפי שנאמר כי הנה מקו' אתי ולכך אומרי' ברוך כבוד ה' ממקומו לפי שאין העולם מקומו העצמי וכמ\"ש וכד אנת תסתלק פי' למקומו כמ\"ש אלכה אשובה אל מקומי כו' ואין זה שינוי כלל דאינו כמו פושט ילובש כו' משום דלית מאן שתפיס ביה שיקרא פושט כו' ונמצא מובן מכל זה עכ\"פ בענין מאמר הנ\"ל דגופין תקינת לון דאתקריאו גופין כו' היינו בחי' הכלים לאורות דע\"ס דאפיק מהעלם עצמותו וגם שנק' גופין נק' ג\"כ לבושין לגבי אור עצמות המאציל וכמאמר דאיהו תפיס כו' ולא נק' גופין רק לגבי לבושי' דמחשבה דו\"מ שהן עולמות דבי\"ע שנמשכים מחיצוניות הכלים דאצי' כידוע וזהו שדקדק לומר דלא אתקריאו גופין רק לגבי לבושין דמכסיין כו' כי לגבי עצמות המאציל נק' גם הם בשם לבושי' וכמאמר בי' לבושי' נתלבש כו' (ומ\"ש אשתארו כגופא מבואר במ\"א איך אפשר בכלים בלא אורות מאחר שמהתעבות האור נעשה כלי כחומר וצורה דמלאכי' וגלגלי' כו' ואם נק' לבושים ג\"כ לא יתכן מאחר שהוא כהדין קמצא דלבושי' מניה וביה כו' שאין הלבוש מציאת בפ\"ע כלל כו' ולכך איהו וגרמוהי חד כו' אלא מפני שיש שרש להתהוות הכלים קודם שיתהוו האורות כו' ע\"ש ולפ\"ז מ\"ש ולית מאן דתפיס ביה לא קאי על האורות דודאי הכלים תופסים לאורות מטעם ששרשם במקיפי' כו' אלא קאי על עצמות אא\"ס שנק' איהו שלגבי עצמותו נק' בשם לבושי' כנ\"ל אבל לית מאן כו' דגם המקיפים דשמים ושמי השמים לא יכלכלוך כו' וד\"ל):\n(יד) <b>והנה</b> כל הנ\"ל בענין התפשטות והתלבשו' והעל' וגלוי וכה\"ג הכל הוא רק באור וחיות הנפש שבגוף באברי' שבא בדלוג המהות מחיי רוחני וגשמי כנ\"ל ויש בזה חלוקי אופנים שוני' מאד אם בבחי' התפשטות כתנועת החי או כח הפועל או רק גלוי העלם ואם כזיו ואור גשמי והחלוקים שביניהן בהתפעלו' ושינוי וכה\"ג מבואר למעלה באריכות והדמיון מכל זה אינו רק בבחי' ע\"ס דאצי' כשהן כבר בכלים מכלים שונים שנק' גופא כנ\"ל בענין אפיקי' י' תקונין כו' דהיינו כשלהב' היוצא לגלוי נבדל מן הגחלת וכן לשון אצי' שכבר נאצל והובדל ובא בהתלבשות בכלים כמו"],[1700400106,"חכמה מוחא חסד דרועא כו' וכה\"ג כנ\"ל ומעתה יש להבין בכחות הנפש עצמם טרם שבאו לאברי הגוף באיזה אופן הן מתהווי' בעצ' הנפש אחר שעצם הנפש היא אור פשוט והיולי בלתי מורכב ממציאת דבר מה מושללת מכל מדה גם מרצון ותענוג שהרי מה שאנו רואים שהנפש עצמה תתפעל בתענוג ורצון שלה זה אינו מעצם מהותה כלל רק שתתפשט או תתלבש בעונג ורצון זה אז תתפעל כו' וראי' לזה שאם אין הנפש רוצה להתענג לא תתפעל מאומה וכן במציא' השכל הגם שהנפש עצמ' תתפעל בהמצאת שכל ונק' נפש המשכלת שכל אין זה מעצם מהותה כלל רק שתתפשט או תתלבש להשכיל שכל וכן תתפשט להיות מטיב חסדו וכן הנצוח והתפארות והתנשאו' הכל יש בעצם הנפש טרם בואה לגוף וכמו נפש המדברת שהוא דבור רוחני כך נפש רוצה רצון רוחני ומשכלת שכל רוחני וכן בנצוח הותפארות הכל בחי' כחות רוחני' בערך רוחניות אור עצמותה רק שאינם נחשבי' מעצמותה ממש אלא כוחותיה מתפשטי' הימנה ויש להבין באיכות אופן זה אם הוא כהתפשטות תנועת החי כפועל בפעול' או כזיו ואור השמש או כהתלבשות ותפיס' ע\"ד כל הנ\"ל בחיי בשר כו' והנה ודאי א\"א לומר שהכחות הללו הן רק בחי' אור וזיו לבד שאינו בא בקשר וחיבור שיתכן בו ההתפעלות ושינוי כנ\"ל ובכחות הללו הרי מתפעלות העצם של הנפש עד שיוכל אדם לבא בכליון נפשו באיזה רצון ועונג הבא מעצמות נקודת נפשו או להיפך מצער המנגד כו' וכן בנצוח והתפארות והתנשאות יגיעו לכל עצם הנפש ממש כידוע והיינו לפי שהכוחות הללו הן נקראי' כחות עצמיי' הנטועי' בעצם הנפש ממש וכל עצם בלתי מתחלק ובחלק ממנו יומשך כל העצם (כמ\"ש למעלה בססי' חי\"ת) ולזה הטעם ג\"כ א\"א לומר שאורו' וכחו' הללו מן הנפש באין בבחי' ההתפשטות לבד שההתפשטות נבדל מן העצם כהתפשטות התחכמות מעצם כח השכל וכהתפשטות הפעול' וכה\"ג שאינו נוגע לעצם רק במקצת מקצתו לבד כידוע ואמנם עכ\"ז אנו רואים שהנפש עצמה מושללת מכל בחי' רצון ומדה כנ\"ל וצאיך לומר בהכרח שהכחות הללו הגם שהן עצמיי' אבל נטועין הן בנפש בכח היולי עדיין ובלתי עצם הנפש לא יבואו לעולם לגלוי מציאת רצון ועונג וכה\"ג דהיינו שכלולין ובטלין במציאותן לגמרי בעצם הנפש ועכ\"ז נטועים שם בבחי' שרש לבד והוא הנק' כח היולי ופשוט כמו הרצון והעונג לדבר טוב נטוע הוא בעצם הנפש בבחי' כח היולי ופשוט עדיין בלי מציאת נכרת כלל רק בבוא הדבר הטוב שיתענג בו יוצא כח העונג ההיולי זה מהעלמו בנפש לידי גלוי מציא' עונג או רצון ואז תתפעל גם הנפש עצמה ממנו כנ\"ל וכן מדת הנצוח נטוע בעצם בבחי' שרש היולי ובהגיע לזה יצא זה השרש בהתפשטות וגלוי וכך לכל מדה וגם להשכלות שכל יש שרש מיחוד נטוע בנפש שנק' כח היולי להשכיל כל שכל ובלמדו דבר חכמה יצא משרש הנעל' ויאיר בגלוי ונק' אור החכמה ועדיין אינו מציאת חכמה ממש אלא אור וכח המשכיל בגלוי לשכל הבא בכלי המוח וכך הוא בכל עונג ורצון ונצוח וכה\"ג יש בזה ב' מדריגות א' יציאתן מהעלמן ההיולי שעדיין לא באו בכלי הגוף והב' כאשר יבואו בכלי וזה ההפרש יפול בו החילוק בין התפשטות לעצם דהיינו כשהכחו' כלולים בעצם בבחי' היולי עדיין נק' עצמיי' גם בהתגלו' מציאותן נקראו גילוי עצם מציאותן וכל זה טרם הארתן בדבר נבדל רק כמו שהן בעצם רק שיצאו מהעלמם ההיולי לבד אבל בהארתם בכלי כמו האור דחכמ' כשהוא מאיר בכלי המוח שנק' אז אור השכל בשם השכלה ממש זהו הנק' בחי' התפשטות מן העצם לבד שיפול בו שינויי' ואינו נוגע לעצם וה\"ז עד\"מ כניצוץ היוצא ונבדל מן השלהבת שנק' התפשטות חלק ממנו שאינו נוגע לעצם משא\"כ בעודנו"],[1700400107,"בהתכללו' בשלהבת וגם בהיותו בכלל גילוי עצם אור השלהבת נחשב מעצמותו וכמו כן שלהבת הקשורה בגחלת הנ\"ל הרי התקשרות השלהבת בגחלת עצמו' ה\"ז כמו כוחו' הנטועי' בהעל' ושרש עצמי בנפש הנ\"ל ושלהבת היוצא ונבדל יש בזה ב' מדרגות הא' כשהו' אחוז וקשור בגחלת ולא בא רק בהתגלו' שיצא מהעלמו לבדו והב' כשהוא נבדל ויוצא שאינו אחוז וקשור בעצם והיינו כשהניצוץ נבדל ובא ומאיר בדב' מה כמו אור הנר שנמשך משרשו ההיולי באש היסודי שאש היסודי אינו מציאת אור ממש רק הוא בחי' כח היולי למציאת אש ואור הגשמי הנתפס בראות כידוע וכאשר נמשך ממנו אור גשמי אין זה כ\"א כאשר בא בכלי להדליקו ואם לאו לא ימצא מציאת אור כלל כי השלהבת אור בלא כלי תסתלק למעלה בשרשה באש היסודי כידוע וכדמיון זה א\"א לומר בכחות עצמיי' דנפש בלא כלי גוף אין להם מציאת אור כלל שהרי הנפש בלא גוף נק' נפש המשכלת נפש המדברת כו' אלא שמציאותן עצמי ורוחני והארתן בכלי גוף נק' אור הבא בכלי שזהו מדריגה הב' דלעיל והוא שנקרא בשם התפשטות דוק' כי עיקר שם התפשטו' אינו רק כשמתפשט בדב' מה חוץ מן העצם ולא כשנתפש' חוץ מן העצם ולא בא התפשטותו בכלי כלל שזהו לא נק' התפשטות אלא אור וזיו ולא אור הארה בעלמא שאינו שייך לעצם כלל אלא אור פשוט ועצמי שנחשב חלק מן העצם וכמו כח השכל ההיולי שבנפש בילד הוא בהעלם ושרש לבד ובזקן שקנה חכמה בנפשו נק' אור עצם החכמ' שמאיר הארתו ושפעו תמיד בכלי המוח להשכיל השכלות ממש כו' וכן בשארי המדו' כשנגדלי' משרשן העצמי בנפש האדם מקטנותו לגדלותו הוא ג\"כ עד\"ז דוקא שנקראו אור עצמי כו' ונמצא שניהם אמת שהכחות העצמיי' הנ\"ל נק' אורות ואמנם הן באי' ג\"כ בבחי' התפשטות ונקראמ' אורות בב' אופנים א' עצמיי' טרם בואם בכלי והב' התפשטו' מן העצמיו' כשבאין בכלי וד\"ל ואמנם הנה יש ב' מדרגו' כמו שמבוא' למעלה בחיי הגוף שיש בזה ב' מד גו' התפשטות והתלבשות וההתלבשות אינו מן העצם כלל רק שנתפס בו בלבד כו' דהנה ענין המאמ' שאמ' גופין תקינ' לון כו' הרי משמע שהיו בלא גופין תחלה והיינו ע\"ס הגנוזות בעצמות טרם שמתפשטי' בהתפשטו' בכלי' שנק' חכמה מוחא כו' אלא נק' אור החכמ' כמו שהיא טרם בואה לכלי עדיין והוא מ\"ש חכים ולא בחכמ' ידיעא (וכמשי\"ת בסי' שאח\"ז באריכות) ויש בזה ב' מדרגות לפי המובן מכל הנ\"ל בכחו' הנפש א' יציאת אורות הללו העצמיי' מעצמות המאציל וכמ\"ש אפיק' י' תקונין וקרינן לון י' ספירן כו' ונחשבי' בבחי' העצמות ממש עד שא' עליהן איהו וחיוהי חד ממש הגם שבאו לבחי' גילוי מהעלמן ושרשן ההיולי הפשוט בעצמו' אא\"ס שנק' עצם אור פשוט בתכלית הפשיטות מושלל מכל ספי' ומדה לגמרי וכמ\"ש אנת הוא חד ולא בחושבן י\"ס כו' אך שרש מיוחד יש לכל ספי' שנמשכת מן העצמות כמו נפש המשכלת כנ\"ל באריכות אמנם גם בגילוי השרש הזה יש ב' מדריגו' הא' כאש' אחוז וקשור בעצמו' ממש דאיהו וחיוהי חד והב' בחי' התפשטותו בדבר נבדל שהוא בחי' הכלי' דע\"ס כמו חכמה מוחא כו' והנה מבואר למעל' שהתפשטות האורות בכלים נק' ג\"כ בשם לבושי' שנתפס ומתלבש בכלים כו' לפי שנבדל ערך החיו' הזה שבגוף הבא בשינוי המהו' כמו השכל גשמי' שבכלי המוח לגבי אור השכל הרוחני שבנפש כו' ע\"כ ה\"ז כמו לבוש ובית שאדם נתפס בו ופושט ולובש כו' וכך יובן בעצמיות האורות דהיינו בכחות עצמיי' דנפש טרם בואן לכלי הגוף עדיין דהשגם שמבואר למעל' שהנפש תתפעל בכחות הללו בהיותן חלק מחלקי העצמיי' שבה עכ\"ז בבואן לידי גילוי והתפשטות נק' לבושי' לנפש שהנפש תתלבש בהן ונתפסו"],[1700400108,"בהן ויכולה לפשוט אותן כו' וכמו שאנו רואי' בחוש שאם לא תחפוץ הנפש להטות א\"ע להתפעלות ענג או צער לא תתפעל כלל וכלל ואם היה זה מבחי' עצמותה ממש איך תפשוט א\"ע מהם כאדם שפושט את לבושו הנפרד מגופו ואמנ' אנו רואים להיפך שהרצון והעונג חלק עצמי ממנ' עד שתתפעל כל עצמות' ותכלה ממנו לגמרי כנ\"ל א\"כ ה\"ז ממש ע\"ד הנ\"ל בחיי הבשר הגשמית שיש בזה ב' הפכים א' שתתפעל ממקרי הגוף והב' שלא יהיה בה שינוי כלל בגרעין אור חיי הבשר כו' וכמו בגלגול הנפש כו' וכך יובן בעצמות כחות הנפש יש ב' הפכים הללו א' שהכחות מושללים ממנה לגמרי עד שלא יהיה בה שינוי והתפעלות כלל מהם והב' שתתפעל כל עצמותה כו' ובהכרח לומר שיש כאן הרכב' מב' מדרגו' הנ\"ל התפשטו' והתלבשו' שהלבוש מורה העדר החיבור וקישו' עצמיי' העצמי והתפשטות מורה על אחיזה והתקשרות ובפרט בכוחות עצמיי' טרם בואם להאיר בכלי כנ\"ל ועכ\"ז נק' לבושים לעצם הנפש וגם נק' התפשטות ושניהם אמת וד\"ל והנה מבואר למעלה ביתרון מעלת הלבוש במה שנתפס כולו כו' אך אין זה בבחי' אור וכלי שנק' חומר וצורה שיהיה בו בחי' תפיסה באמת כתנועת האברים והתפעלות הכאב בחיי בשר כנ\"ל ולמעלה יובן מזה במ\"ש איהו תפיס בכולהו עלמין ולית מאן דתפיס ביה כו' הנ\"ל באורות וכלים דאבי\"ע דקאי גם בע\"ס דעצמות אור המאציל דאיהו תפיס ומלובש בהן וע\"ז אמ' ג\"כ בעשרה לבושים נתלבש כו' עד\"מ מכחות עצמייםדנפש שיתכן בזה בחי' התלבשות כנ\"ל אבל לית מאן דתפיס בי' מלבד שאין זה כאור וכלי חומר וצורה אלא שגם בבחי' תפיסה והלבשה אין זה כאדם שנתפס בבית זה שלא יכול להיות אז בבית אחר כו' דהיינו שא\"צ הפשטה מלבושים הללו כלל כנ\"ל והענין בעצמות דע\"ס קודם בואן להאיר בכלי דהיינו חכים ולא בחכמ' כו' לית מאן דתפיס בעצמותו כלל עד שא\"צ פשיט' מלבושי' הללו וכמאמ' לית מח' תפיס' בך דהיינו גם מח' דחכמ' הקדומ' דא\"ק ולמעל' מעל' עד גם בחי' חכמ' העצמי' שבעצמו' המאציל ממש שנא' לתבונתו אין מספר וכה\"ג לא יש לה תפיסא בך בעצמותך ממש מטעם הנ\"ל הגם שנק' בשם התלבשות אין הלבוש נבדל ממנו שיצטרך לפושטו וכמארז\"ל אין העולם מקומו וכנ\"ל באריכות וד\"ל (גם מובן דכמו שיש מציאת לכלי בלא אור כנ\"ל בפי' אשתארו כגופא כו' משום דיש להן שרש מיוחד כו' ומ\"ש לית מאן דתפיס היינו משום דקאי על עצמותו שנק' איהו כנ\"ל כך יש מציאות לע\"ס הללו שבעצמו' שנק' לבושי' וגם נק' התפשטות גם קודם שתיקן להם גופין בכלים ודאי יש להם שרש בעצמות וע\"ז א' ולית מאן דתפיס בי' ג\"כ משום שהשמי' ושמי השמי' שזה טה\"ע וטה\"ת ע\"ס הגנוזות בהעלם עצמותו ובחי' התגלותן העצמי הנ\"ל הכל לא יכלכלוך אפי' בבחי' כלי' חיצוניו' כו' והגם שא' איהו וחיוהי חד ממש אין זה ערך לגבי עצמותו הפשוט וע\"ז א' איהו תפיס בכולהו עלמין ולית מאן כו' אפי' מח' ורצון ותענוג שבעצמו' ממש וכמ\"ש אנת הוא חד ולא בחושבן י\"ס כלל אפי' בהעלם ושרש היולי כו' וד\"ל:\n(טו) <b>ובכל</b> זה יובן ענין הפסוק דכי עמך מקור חיים דרישא וסיפא הכל ענין א' וזה ביאור ופי' לזה כנ\"ל דהנה בחי' יחודא עילאה דע\"ס דאצילות בכלים שנק' גופא כנ\"ל הרי זהו מ\"ש באורך נראה אור שהוא אור נבדל ובא בשינוי המהות כדמיון חיי הגוף באברי' שנבדל מאור עצם הנפש עד שנק' בשם התלבשות וגם הוא בבחי' התפשטו' שהוא בא בבחי' התפעלות והרגשה ושניה' אמת כנ\"ל וזהו שא' באורך העצמיי' שהן ע\"ס העצמיים טרם בואן לגילוי אור בכלי כשלהבת היוצא"],[1700400109,"בבחי' התפשטו' בכלי כו' נראה אור אח\"כ בשינוי המהות כשבאי' בכלים וכמו אור החכמ' הנאצל כשבא בכלי מוחא היינו נרא' אור העצם דחכמה בבחי' הארה דהארה כמו אור הנראה מתוך הלבוש בשינוי המהות ועכ\"ז הרי מיוחדין האורות דע\"ס בעצמות המאציל כמ\"ש איהו וחיוהי חד ממש ונק' יחו\"ע בין שהוא בהתפשטו' הרי מתאחד כאילו הוא עצם א' בקשר גמור עד שיתכן ההתפעלות כנ\"ל בחיי בשר שתתפעל הנפש כו' ובין שהוא בהתלבשות שנבדל בערך מ\"מ מאחר שאין הלבוש מציאת בפ\"ע כמ\"ש ולית מאן דתפיס בי' כנ\"ל ה\"ז יחוד גמור ולא נק' אור בשינוי המהות כלל ובין שהוא בבחי' העלם וגילוי כשלהבת הקשורה כו' או כזיו השמש הכל אין זה שינוי המהות כלל שאין לך דבר חוץ מן העצמות והרי גם מה שנמצא מציאות גופין או לבושי' בע\"ס הכל ממנו וכמ\"ש גופין תקינת לון שהוא תיקון והמציא' והיינו שרש התהוות הכלים בעצמו' שהוא ע\"י בחי' צמצום הראשון או בחי' לבוש להעלים וכה\"ג דלבושי' מיני' ובי' כו' ולכך א' איהו וגרמוהי שהן הכלים חד כמו באיהו וחיוהי ממש משום דשרש או\"כ הכל בעצמותו וזהו שאמר בסיפא באורך כו' בדרך פירוש וביאור לרישא דכי עמך כו' ורישא דכי עמך פי' וביאור לסיפא כו' והכל א' ממש דהנה מ\"ש כי עמך מקור חיים קאי בע\"ס שבעצמות שהדמיון הוא כשלהבת בעודנה קשורה בהעלם עדיין בגחלת ולא יצא לחוץ וכמ\"כ הן י' כחות הנפש הנטועי' ומושרשי' בבחי' שרש והיולי פשוט בעצם הנפש הפשוטה כנ\"ל בענין רצון ועונג הבא מן הנפש שכלול ג\"כ מדבר והיפוכו בבחי' התפשטות והתלבשות דהיינו שהנפש מושללת לגמרי מהם וגם תתפעל כולה מהם כו' ושניהם אמת כנ\"ל באריכות עד דמ\"ש ולית מאן דתפיס בי' קאי גם על חכמה העצמי' ממש דהיינו מ\"ש בכללות לית מח' תפיסא בך כלל כו' וזהו פי' הפשוט דרישא דקרא כי עמך מקור חיים פי' מקור חיים הוא בחי' ההעלם דע\"ס דאצילות כמו עד\"מ המקור למעיין שהוא בהעלם והמעיין נובע בגילוי ונמשך ממנו נהר והיינו מן התהום שנק' מקור נעלם כמעיינות תהום שנק מקוריים נעלמי' לגבי מעיינות הנגלים שא' עליהם השולח מעיינים בנחלים (שזה נק' מאין ליש וזה נק' מיש לאין וכך בחי' מקור חיים שבהעלם נמשך מיש האמיתי לאין ובחי' גלוי ע\"ס שבעצמות שיש בזה ב' מדרגות כנ\"ל א' יציאתן מהעלמן לבד ועדיין לא באו בכלי וזהו נק' אין שבע\"ס והב' התלבשות' והתפשטות' בכלי היינו מאין ליש שע\"ז א' נראה אור כנ\"ל) והנה מ\"ש כי עמך מקור חיים דקאי בע\"ס העצמיי' מדבר בג' אופני' ועל הכל א' כי עמך טפל ובטל ונכלל בעצמותו ממש הא' הע\"ס שהן בעצמותו ממש כענין רצון המוחלט הנ\"ל שזהו כמו בחי' כח היולי בעצם טרם שיצמיח ויוליד מאומה דמה שיצמח ויוליד רצון של חסד וכה\"ג נק' מאין ליש גם בעצמות הע\"ס כמו כי חפץ חסד הוא בעצם ע\"כ עלה בגלוי ברצונו הטוב כו' וכה\"ג וע\"ז אמר כי עמך ממש דאפי' תענוג וחכמה שהוא בכח היולי בעצם טרם שתבוא לגלוי נכללת בעצמותו ממש (ובכלל היינו מה ששיער בעצמו בכח בבחי' טה\"ע ואינו כמו כח ופועל דהעלם וגלוי מיש ליש אלא מיש לאין דהיינו מיש האמיתי לאין דמה שיצמיח התעוררות רצון פשוט להאציל וכה\"ג נק' אין דכלא חשיב לגבי העצם שכולל כמה רצונות כאלה שאינו בגדר התהוות רצון זה עדיין כו' ונק' בעל הרצון) והב' מה שע\"ס שכלולים בעצמות המה כבר בבח' מציאותן רק שהן כלולים בבחי' העלם כשרש הנעלם שיצמיח בגלוי כמו כשעלה ברצונו להטיב טובו כו' וכן בחכמה וחסד אבל עדיין לא באו לגלוי אור כלל והיינו כשלהבת הקשורה בהעלם שעתיד"],[1700400110,"מיד לצאת לגילוי התפשטו' בכלי נבדל כו' (או כמעיינות תהום שנק' מקור עכ\"פ רק שהוא בהעלם והגם שזהו מיש לאין כנ\"ל אבל נק' אין ליש כו') או כמו כח השכל שנעשה מקור נעלם לגילוי שכל בטרם שיצמיח ועתיד להצמיח ולהוליד שכל זה וכמו כח התנועה שעתיד ומוכן להניע וכאור וחיות שבנפש שמוכנת להחיות חיי בשר גם בטרם שתחיה כו' והג' מה שע\"ס דעצמו' באין בבחי' התפשטו' אור ונק' אור החכמ' או אור החסד ממש אך לא באו בבחי' כלי עדיין ונקראו אורות עצמיים בלתי מוגבלים וכנ\"ל בענין אפיקת י' תקונין כו' שגם גילוי מציאות ע\"ס העצמיי' טרם הארתם בדבר נבדל כשהוא אחוז וקשור בעצמו' כעצמו' ממש יחשב ולא נק' עדיין בשם התפשטות חוץ מן העצם אלא התפשטות העצם כמו נפש המשכלת ומדברת בלא גוף עדיין שנק' אור פשוט ועצמי מעצם הנפש ע\"ד דוגמא מזקן שקנה חכמ' בנפשו שנק' אור עצם פשוט שמאיר שפעו תמיד להשכיל בכלי המוח משא\"כ בקטן הרי נשאר בהעלם ממש ולא ישכיל מאומה כו' וכך שארי המדות שנגדלין משרשן הנעלם מקטנות לגדלות בנפש האדם ונמצא נק' אורות עצמיי' גם בטרם בואם בהגדלה בכלי ואח\"כ באין בהגדלה וריבוי בהתפשטו' בכלים שע\"ז א' גופין תקינת לון כו' וד\"ל ועל ג' אלה אמר כי עמך מקור חיים שהכל נחשב מן העצמות דאיהו וחיוהי חד ממש גם בהארתן בגלוי עצמותן שנק' מקור חיים בגלוי וע\"ז מפרש דבריו באורך נראה כו' דהיינו גם בע\"ס הללו כשבאין בהתלבשות בגופים שהן הכלים כמו חכמ' מוחא כו' הרי באורך העצמי נראה אור זה הבא בבחי' כלים ולבוש משום דעמך מקור חיים ג\"כ דלית מאן דתפיס בי' כלל והא בה תליא דמשום דעמך מקור חיים בהעלם הע\"ס ע\"כ גם בהתגלותן בהתפשטות והתלבשות באורך נראה בלי שינוי כלל וגם זה אמת דמה שעמך מקו' חיי' נכללי' בעצמותו ממש כנ\"ל משו' דבאורך העצמי ממש נראה אור דגם הע\"ס העצמיי' באין בבחי' לבוש כמ\"ש ולית מאן דתפיס בי' אפי' מח' הקדומ' בעצמו' וכמ\"ש אנת הוא חד ולא בחושבן י\"ס אפי' בהעל' וכח היולי הפשוט הנז' במדרג' הא' וד\"ל ונמצ' מובן מכל זה דאין הפרש כלל בין בחי' יחיד לבחי' אחד דהיינונ כמו שעמך מקור חיים בהעלם עצמותו שנק' יחיד ביחוד עצמי ופשוט כנ\"ל כך באורך נראה אור ביח\"ע באו\"כ שנקרא אחד ואין הפרש ביחוד' משום דדרך כלל גם אחר הצמצו' הרי באורך נראה אור הקו ולא נבדל מן העצמות עד שגם פוש' ולובש לא יתכן משום דקמי' כחשיכ' כאור' כו' וכנ\"ל בפי' השמים כו' וד\"ל ועדיין אין מקרא זה מתיישב לנכון דמה ענין חיים עם אור דפתח במקור חיים ומסיים באורך כו' ומה שא' מקור חיי' בריש' והדר באורך ולכאורה באורך על עצמו' אא\"ס קאי שנרא' אור הקו כו' אח' הצמצו' היה לו להזכי' תחלה ושייך שפיר ע\"ז הפי' דכי עמך מקור חיים דאין הצמצום שינוי כלל כנ\"ל אבל אחר כי עמך כו' באורך אין זה לפי סדר ההשתלשלות ואם הכוונה באורך נרא' על האורות בכלים כנ\"ל למה שינ' מרישא שקור' לע\"ס בשם אור ותחל' קור' למקור' בשם מקו' חיי' ולא מקור אור הנק' מאור וכה\"ג ולא סיים במה שהתחיל כלל כו' אך הנה יובן הכל ע\"פ הנ\"ל דיש כמה מדריגו' חלוקו' בין בחי' אור וזיו השמש הגשמי לאור הרוחני שהוא אור החיים דחיו' הנפש בגוף ויש בזה מה שאין בזה דודאי אור הגשמי דשמש אין חדש בו כלל דמוכרח הארתו מחמת הבהירות העצמי שבגוף המאור שממילא יאיר אבל אור וחיות הנפש כמו בחי' היולי הוא שבלא גוף לא נק' בשם חיות כלל וכלל רק בגוף יקרא בשם חיות וגם זה לא מוכרח כטבע כח המניע להניע אלא יתפשט ולא יתפשט וראי' מנפש בגלגולי' וכן מגרעון החיות באבר שלא יהיה שינוי בעצם (וגרעון"],[1700400111,"שבעצם השמש בליקוי יעשה גרעון הזיו שלו בהכרח ובזה גם הנפש בעצם גרעון שבה יעש' גרעון בהתפשטו' כמו הסריס שחסר כח המוליד בנפשו בעצם וכה\"ג ויש רבי' שאין החסרון מצד העצם רק מצד קלקול כלי הגוף כמ\"ש במ\"א) עד שיקר' בשם התלבשו' או העלם וגילוי ולזאת יש לקרות לנפש עצמה בשם מקור חיים כי גילוי החיות בגוף נק' חיים ומקור חיים הוא בחי' כח היולי שבנפש להיות מחי' לגוף שתבא בו כו' וכמו באור המתפשט מן אש היסודי הרי אש היסודי נק' מקור הנעלם בבחי' היולי עדיין ומה שנמצא האש למטה אינו אלא בבואו בכלי להדליקו ואם לאו יסתלק השלהב' ויוכלל באש היסודי כנ\"ל כך חיות הגוף כאשר יקולקלו כלי הגוף יסתלק אור חיות הגוף ויוכלל בעצם הנפש שנק' היולי שאינו בגדר חיו' בשרי כלל וכלל שלזה לא יקרא התפשטו' מן העצם כזיו השמש אלא כדרך העלם וגילוי או התלבשות שנראה במהות נבדל מן העצם כך חיי בשר וכן צומח גשמי מכח הצומח הרוחני שנתלבש הרוחני בגש' כתרגום תדשא תתלבש כו' וכנ\"ל (ועכ\"ז לא נק' יש מאין כתולד' ולד שלם כנ\"ל) ובזה יש יתרון מעלה באור וזיו גשמי דשמש במה שאין בו התפעלו' (ולא גרעון ושינוי בעצם המאור כשישנו הזיו משא\"כ בגרעון ושינוי כלי המוח ישונה בהכר' כח ואור עצמי דנפש המאי' במוח כו') ומעת' יובן בפי' הפשו' דבאורך נראה אור שיש ב' מיני אור הא' אור עצמי ופשוט (כמו אור האש היסודי טרם שיבא לכלל מציאו' אור גשמי) והב' מה שנראה אור אחר מאור זה העצמי בשינוי המהות (והוא כאור נר גשמי הדולק) שזהו ממש כאור עצם הנפש שנק' היולי ופשוט שאינו בגדר חיות עדיין ונק' מקור חיי' ואח\"כ בא בשינוי המהות בגוף שנק' חיי בשר כנ\"ל ולפי\"ז רישא וסיפא דקרא זה בענין ואופן א' מדברים והוא במה שיש הבדל בין אור גשמי דשמש לאור רוחני שממנו נמצא אור גשמי דודאי דומה הוא למקור חיים דנפש בגוף ממש כנ\"ל וזהו כי עמך מקור חיים מקור זה היא הנק' חי ולא בחיים והיינו בחי' עצמות אא\"ס הפשוט שנכללים בו ע\"ס בהעלם שבלתי כלי כלולי' הן בעצמו' ונק' חכי' ולא בחכמה ידיעא כלל כו' וכנ\"ל בג' מדרגו' שבהן על הכל נאמר כי עמך מקור חיים והיינו שמפרש האיך יקר' מקור חיי' ואח\"כ יבא לכלל גלוי חיים שהן ע\"ס דאבי\"ע וז\"ש באורך כו' ועוד יתפרש באופן שאו' גשמי דשמש יותר עצמי מאו' היסודי כו' והיינו כמ\"ש כי ה' אלקיך אש אוכל' הוא וידוע דהיינו אשא אוכמא אור הדולק שהוא בא בכלי כמו וירא מלאך ה' בלבת אש מתוך הסנה כו' ונק' אור השורף שבא בכלי ונק' נהורא תתאה ושרשו מנהורא עילאה הנק' באורך העצמי שהוא למעלה מעצם האור דאש היסודי הנ\"ל ולמעלה מעצם הנפש שנק' חי ולא בחיים כמשי\"ת בסמוך וגם הוא עמך דהנה אורך הפשוט העצמי שנק' נהורא עילאה ממנו נראה אור תתאה שהן ע\"ס דאבי\"ע ולכך פתח במקור חיים ומסיים באורך שהכל ענין א' ממש ולא יקשה דהא באורך זה קאי על עצמו' אא\"ס וודאי זה אמת והיינו פ' דרישא דכי עמך כו' לפי שעצמות אא\"ס כמו שהוא לפני הצמצום נק' טהירו עילאה כמו כעצם השמי' לטוהר הוא ממש כמו אור עצם השמש דהגם שמבואר למעלה באור השמש אין כל חדש כו' שהרי מה שבעצם השמש בא הארתו אבל מ\"מ זהו המעלה שנקרא עצם אורו בלי שינוי המהות עכ\"פ ולא נק' בחי' היולי כאור העצמי דנפש שזהו יותר עצמי מבחי' היולי דנפש להחיות והיינו באורך טה\"ע נעש' בשינוי המהות נהורא תתאה הבא בכלי אבל לא כמו מאש היסודי וכנפש בגוף אלא באורך עצמו נראה אור כו' וכענין שרגא בטיהר' שהארתו בלתי ניכרת אז ובהסתלקו'"],[1700400112,"השמש ניכרת כך באורך כבר נראה בהעלם ובא לידי גילוי ניכר אחר הצמצום הראשון הנק' מק\"פ והיינו שהוא פי' וביאור גמור לרישא דכי עמך הי' בהעלם מקור חיים זה והיינו שבאורך הי' נראה ולא בגילוי כו' ולפ\"ז אין פי' כי עמך מקור חיים כדלעיל בחיי הנפש בבחי' היולי והתפשטות אלא אדרבה כי עמך בטל מה שעתיד להיות בהעלם והתפשטות כשרגא בטיהרא כו' ומה ששיער בעצמו אין זה כהיולי ג\"כ אלא מה שעתיד להיות בהעלם והיולי עדיין וד\"ל:\n(ט\"ז) <b>ואחר</b> כל זה יש להבין במ\"ש שמע ישראל ה' אלקינו אלקינו זה מהו דהנה ידוע שהחכ' נק' חי ובינ' נק' חיי' ופי' חי הוא בעצ' טרם שיבא לכלל התפשטו' עדיין כדוגמת הטפה דאבא שרמ\"ח אברי הולד כלולים בה בהעלם ואח\"כ בבטן אימא מתפשטי' ומתגדלי' בגלוי (כמ\"ש בזהר ע\"פ מראש צורים אראנו כו' דמסטרא דאימא אתמתח כו') (והיינו שאין צור כאלהינו צר צורה כו' כמ\"ש במ\"א) דבחי' החכמ' הוא ביוד שהוא בחי' אין ההעלם והצמצום הכולל שהוא בבחי' היולי ואח\"כ בבינה בא מאין ליש בהתפשטו' אורות בכלים כו' וזהו ההפרש בין חי שבעצם לחיים שבהתפשטו' ומחי בעצם יבא לכלל התפשטו' בפרטי חלקי' וגלוי' וכולם היו כלולים בהעלם דאין דחכמ' שנק' חי (כמ\"ש במ\"א בענין נשמת כל חי נשמתא דפרחא מחי דעולמי' כו') וזהו ג\"כ ענין הכולל בפסוק זה דשמע ישראל דוקא שעלה במח' דהיינו חשב מ\"ה דחכמ' שנק' מח' כללית מקפת כל הפרטי' כו' והוא הוי' דחכמ' ואח\"כ אלקינו אין צור כאלהינו כו' שהוא בבחי' בינה שנק' אלהי' חיים בהתפשטות חלקי או\"כ פרטי' הבאים בגלוי שלזה אמר אלקינו שלנו דוקא הבא בגלוי בכל נשמה אלקית לפום שיעורא דילה כידוע ששרש ס\"ר נשמות ישראל הוא מבחי' ז\"א דאצי' שבא בכלי' והתפשטותו באו\"כ בא מסטר' דאימא דווקא כמ\"ש כי מראש צורים כו' ושרשו הכללי הוא במוח אבא כמ\"ש מה שמו מה שם בנו והיינו ישראל שהוא בחי' ז\"א שעלה במח' בכלל ובא לבחי' התפשטות בפרט בבטן אימא כו' שמשם נחצב שרש ס\"ר נשמות ישראל כמ\"ש הביטו אל צור מחצבתם ואין צור כאלקינו דווק' כנ\"ל וז\"ש ה' אלקינו דוקא וד\"ל אך הנה להבין ביאור זה ולמה אלקינו זה בין ב' הויו' דיחיד ואחד ואשר לזה אומר לישראל זה דווק' ה' אלקינו הוא ה' אחד ואיך יתכן בחי' התפשטו' או\"כ בע\"ס הגנוז' בעצמו' שהוא בחי' הוי' הא' עד שא' ה' אלקינו הוא ה' אחד שבע\"ס דאצילות באו\"כ כו' ויש להקדים תחלה ענין א' הידוע בע\"ח שיש ב' מיני כלים בז\"א פנימיי' וחיצוניי' ושרש כנ\"י מפנימי' הכלי' והמלאכי' מחיצוני' הכלים כו' כי הנה בנשמה האלקי' נאמר בצלם אלקי' כו' בבחי' צלם אדם העליון משום דכח המוליד בדומה לו ושרש הנשמו' מיחוד זו\"נ דאצילות שהוא בבחי' פנימי' הכלים דוקא וביאור הדברים ידוע היות ההפרש בין פנימי' הכלי לחיצונית הכלי בגשמית יובן ע\"ד דוגמא ממה שאנו רואי' בכלים גשמיי' שיש ב' מיני כלים מקבליהן ופשוטיהן כמו בית קיבול שבכוס שעשוי לקבל היין והמקשין הנה העיקר הוא בית חללו דווקא ששם המשקה מתאחד בו ואין הבדל בין המשקה לדופני חלל הכוס המחזיקו משא\"כ חיצוניות הכוס שאינו עשוי לקבלה כלל רק שיוקח ביד בלבד זה אינו עיקר רק טפל משמש לגוף הכלי והוא במה שיכול השותה לשתות על ידי לקיחתו בחיצונית הכוס וכה\"ג וכך הוא בכל כלי קבלה שפנימי' שבו הוא עיקר הכלי המחזיק מה שבתוכו ומתאחד בו ממש כו' וכלי מקבל כולל גם מה שיש בכלים מפשוטיהן שהוא כמו כלי הסכין שאינו עשוי לקבל כלל רק שיחתוך בו הלחם והבשר וכה\"ג שעיקר תועלת הוא"],[1700400113,"מחיצוניותו שעובר ע\"י כח התנועה שביד שבלעדו לא הי' פועל החיתוך והרי הסכין כמו אמצעי בין כח התנועה שביד לדבר הנחתך לחברם יחד וזהו כמו שפע הנמשך ע\"י ממוצע כמו ע\"י שליח וכה\"ג שעובר העצם של השפע דמשפיע ע\"י השליח למי שצריך להשפיע וליתן לו ואינו נותן ביד עצמו וזהו הנק' דרך מעבר הבא בשינוי המהות ע\"י אמצעי וגם בכלי מקבלהן חיצוניות הכוס וכה\"ג לכאורה כאמצעי יחשב להביא הכוס לפיו לשתות שהעיקר הוא השתי' והבאת הכוס ע\"י לקיחתו כמו אמצעי בין עצם הכוס לעצם אדם השותה ואין זה דומה לזה דמה שהיד בעצמו לוקח הכוס בלא אמצעי ומחברו לפיו הרי הוא מחברו לפיו ומה שלוקח הסכין בידו הוא להיפך להרחיק תנועת ידו שיניע ע\"י הסכין דווקא לפי שלא יפעול בידו החיתוך שזהו הנק' התפשטו' שחוץ ממנו וכל כה\"ג כלי חיצוני יחשב וכמו כלי ההבטה על העין כדי שיביט למרחוק יותר ה\"ז בחי' התפשטו' הראי' דרך מעבר בזכוכית זו כמו התנועה ביד דרך הסכין ממש כדי שיביט יותר לחוץ מעצמו אשר לא הי' ביכולת כלי העין עצמו להתפשט לראות למרחוק כ\"כ משא\"כ כלי העין וכלי היד עצמם נק' כלי קבלה שהעין מקבל כח הראיה הרוחניות שבתוכו ומתאחד בו כחומר לצורה וכן כלי היד לתנועה חיונית שבה מתאחד בה ואין בזה הבדל כלל כאלו הן עצם א' ממש ומ\"מ כולל בעין ויד מה שיכולי' להתפשט לחוץ מן העצם והוא מה שכלי העין רואה בעצמו והיד מניע בעצמו וזהו בחי' החיצוניות שבהם אע\"פ שכל עיקר העין אינו אלא להביט ועיקר היד אינו אלא לפעול ולהניע מ\"מ גדול מעלת עצמם ומהותם טרם שפועלים בחוץ מן עצמם כמו כלי החלל דכוס בטרם שישתה השותה שזהו עיקר הכלי דווקא כנ\"ל כך מה שיש בחומר העין הכנתו לקבל צורת אור הראיה בעצם גם טרם שיפתח העין להביט בה זהו עיקר פנימי' כלי העין וכן מה שיש ביד תנועת החי בעצם טרם שיפעול התנועה הוא עיקר הכלי ולא בחי' התפשטות כלי העין והיד בפעולת' וכמו\"כ כלי המוח שהוא חומר מוכן לקבל צורת אור השכל כידוע יש בזה ג\"כ פנימית וחיצוני' הא' מה שיפעל כלי המוח בהתפשטו' שחוץ מעצמו שנק' חיצוניות היינו מה שיושפע דרך מעביר בחוץ ממהותו להאיר שם הארתו כמו השכל שבמוח שיומשך להיות מוחין למדות וכן מה שיומשך מכלי המוח לאותיות השכל הנק' מחשבת שכל שאין זה מעיקר אור השכל רק מכלי המזיגה שבמו' כמו קר ולח או חם ויבש דמוח החכמ' הוא הממציא השכלות החדשות לפי שטבעו קר ולח ומוח הבינה םח ויבש בטבעו אינו מוליד חדשות רק להרחיב ולהטעי' אור השכל בדברי' כהוייתן ששומע ונמצא בזה הרבה חלוקי המדרגו' שונות והכל הוא בבחי' כלי חיצוניו' שלהם דהיינו מה שיוצא מהם דרך מעבר לחוץ מעצם מהות' אבל עצם מהותם הפנימי היינו ממש כבית קיבול דכוס או ככלי עין שהוא עצם ספיר מוכן לקבלת הראי' כך עצם המוח דחכמ' שהוא קר ולח בכלל מוכן לקבל' אור דחכמ' להוליד מושכלו' חדשות גם טרם שיוליד וישכיל עדיין זהו הנק' פנימי' כלי המוח דחכמ' ומה שיומשך מכלי מוח זה בכל עת שירצה להתייגע בו להוליד שכלים היינו בחי' חיצוניו' שבמוח זה וכך הוא במוח בינה בחי' עצם החומר שהוא חם ויבש בטבעו מוכן לקבלת ההשגה וההבנה זהו פנימי' הכלי שבו ומה שישיג בכמה אופנים שונים בהרחב' דברי' בהסבר זהו חיצוניות הכלי כמו חיצוניות העין והיד בפעולתם וכחיצוניות הכוס והסכין וכה\"ג וד\"ל: והנה הולד דנולד ממוח החכמ' נלקח מטפה שבמוח שהוא מעצם פנימי' כלי המוח שהוא בטרם שישכיל מאומה ולכך מוליד נפש משכלת כל שכל כו' ומזה יש הוראה גמורה ששרש פנימי' הכלים הנ\"ל הוא בפנימי' ועצם האורות כמו אור"],[1700400114,"החכמה יש בה עצם והתפשטות העצם שבו הוא כח ההיולי דחכמה שבנפש עצמה טרם שתאיר בהתפשטו' עדיין כנ\"ל וכמבואר למעלה בזקן שקנה חכמ' בנפשו להוליד חכמות חדשות כו' זהו נק' גילוי העצם אבל עצם הכח היולי בטרם שיבא לכלל גילוי זה משם שרש התהוות עצם הנפש הנולד כעצם הגרעין שיצמיח תפפוח שלם כמ\"ש במ\"א) והיינו ענין כח המוליד בדומה לו שיוליד בצלמו כדמותו באברי' שהוא בבחי' כלים הפנימי' דוקא ולא ישתחווה לפעולת אברים כי עצם הנפש המוליד כולל כל הכחות הכלולים בעצמו בבחי' עצמיות והעיקר בעצם דחכמ' ומה שנק' נפש המשכלת הוא התפשטו' וכלל זה ידוע דכל עצם בלתי מתחלק ויש בפרט שבו מכללותו ואמנם בעצם שבנפש החכמה דווקא כלול כל חלקי' העצמיי' שלה ולזאת הטפה שבעצ' מוח דחכמ' דווקא תוליד נפש שלימה כלולה מהכל בדומה לצורה וחומר שלו בכל פרטיהם בהיות שהפנימית של כל האברי' שרש' מפנימיו' ועצם כל הכוחו' הכלולי' בעצם הנפש וכול' כלולי' בעצ' דאו' החכמ' כו' משא\"כ השכלו' חדשו' שנמצאו ממוח החכמ' הוא רק חיצוניו' שבאו' החכמ' שבעצ' הנפש כו' וד\"ל והנמש' מכל זה יובן באו\"כ דאצילות שפנימי' הכלי' דז\"א כמו חכמ' מוחא חסד דרועא יש בזה שרש מפנימיות האורות דחכמ' וחסד כמו שהן בעצמו' המאציל דאיהו וחיוהי חד בג' מדריגו' הנ\"ל (בסי' שקודם זה) והוא חכים ולא בחכמ' ידיעא מבין ולא בבינה כו' וכאשר יוליד הנשמה אלקי' בצלמו כדמות כו' היינו מצד בחי' פנימי' ועצמו' המוחין דז\"א שכולל כל פנימי' עצמו' האורו' שבו משרש' הראשון העצמי שדוק' במוח החכמ' כלול הכל בהעלם והוא למעלה ממוחין חדשים שנמשך כמו שכל חדש וכך הוא עד למעלה מעל' גם בחכמ' דא\"ק שנק' אדם דבריאה בכללות ופנימיות הכלים דווקא המה כמו חומר עצמי מוכן לקבל עצם האור כמובן ממשל הנ\"ל במוח ועין ויד כו' ולכך יוליד בצלמו כדמותו בחומר וצורה כלול מהכל דווק' משא\"כ המלאכים שמקבלים מחיצונית הכלים שפועלים בפעולה שאין בזה מבחי' העצמיות דאדם העליון כלל לכך הנשמו' נק' אדם דווק' כידוע וד\"ל ובכל זה יובן ענין ה' אלקינו דווקא שהוא אמצעי בין ב' הויות דיחיד ואחד הנ\"ל בהיות שישראל עלה במח' היינו במח' כללית ועצמי' דחכמ' הקדומ' בעצמות אא\"ס ממש והו' הנק' חי בעצם שכולל כל חלקי' העצמיי' שבבחי' שארי המדות העצמיי' שביחיד כנ\"ל וז\"ש שמע ישראל דווקא הוי\"ה אלקינו הוי\"ה זה הוא בעצ' החכמ' דעצמו' שמוליד בדומה לו ממש והן ישראל שעלה במח' עצמי' וכללית ואח\"כ אין צור כאלקינו שבא בדרך פרט להתחלק בציור רמ\"ח אברי' שהן קומ' שלימ' ראש וגוף כו' והוא מ\"ש אלקינו שלנו ממש בכל נש\"י כו' ולמעלה הוא שרש דשרש לכל פרט נש\"י שנמשך ממוח החכמה דז\"א שע\"ז אמ' כי אתה אבינו וכידוע בענין מה שמו מה שם בנו דישראל נק' בני בכורי כו' ומה הראשון הוא מה דחכמה שהו' פנימי' ועצם המוחין דחכמה דאבא שבז\"א כו' שנק' אביהם שבשמים כידוע וז\"ש ה' אלקינו הוא בחי' אלקים חיים דבינה שבא בהתפשטו' פרטי' שצר צורה כו' וכמ\"ש הביטו אל צור כו' ואמנם מובן מכל הנ\"ל דע\"י ישראל זה שבו ה' אלקינו חו\"ב שבעצמות בבחי' עצמיות דווקא ע\"כ ע\"י יהי' ה' דיחיד וה' דאחד שוין ביחודם כנ\"ל דמה דאיהו וחיוהי חד בעצ' ומה דאיהו וגרמוהי חד בהתפשטו' או\"כ הכל א' מצד ישראל דווקא שעלה במח' והוא בחי' הממוצע וכנ\"ל ולזה א' שמע ישראל דווקא ולא לזולתו וד\"ל:\n(יז) <b>ומעתה</b> יש להבין בשרש בחי' יחודא תתאה שזהו ענין בשכמל\"ו כידוע ושרש יח\"ת זה הו' בדלי\"ת רבתי דאחד שהוא בחי' לאה שמקבלת ממל' דתבונה הנה מבואר למעלה בענין גדול אדונינו כו' דגם למעל' מעלה"],[1700400115,"בעצמו' אא\"ס אדונינו זה הו' בחי' מל' דא\"ס שהוא שם א\"ד כמו יגדל נא כח א\"ד כו' ולתבונתו אין מספר הוא בחי' תבונה שבעצמו' והיינו כללו' ענין דאא\"ס למעלה עד אין קץ ביח\"ע שבעצמו' ולמט' עד אין תכלית ביח\"ת דבשכמל\"ו ששרשו מעל' דא\"ס כמ\"ש אני ראשון ואני אחרון וכן ראו כי אני אני הוא ואני ה' לא שניתי כו' ולהבין כ\"ז יש להקדים בכללות ענין יח\"ת זה דבשכמל\"ו שזהו בחי' מל' דאצילות שמסתתרת בבי\"ע דוקא שזהו שם כבוד מלכותו כו' וידוע בענין ה' אחד ושמו אחד דיח\"ת שוה ממש ליח\"ע כמ\"ש בפי' כגוונא דאינון מתייחדי' לעילא שהן ע\"ס דאצילות במאצילן שזהו לעיל' לעיל' אוף הכי ממש אתייחדת המל' לתת' בכורסיי' שהוא עולם הבריא' כו' ברזא דאחד למהוי אחד בא' ממש כידו' וכך מצינו בדברי רז\"ל דבשכמל\"ו זה השבטי' אמרוהו ליעקב כשם שאין בלבך אלא אחד שזהו בחי' יח\"ע דאצי' שיעק' הו' בבחי' ח\"ת דז\"א דאצילו' שמתייחד למעל' ביחוד עליון דאצילות כמו שא' יעקב משמש במרו' שעול' עד הכתר שזהו ענין קו האמצעי שנק' בריח התיכון כו' וזהו כשם שאין בלבך אלא א' דיח\"ע עד רום המעלות בבחי' יחוד שבעצמו' ממש דאיהו וחיוהי וגרמוהי חד ממש בשוה באצי' כך אין בלבבינו אלא א' שזהו בעולם הבריאה דגם שמל' דאצילות מוסתר שם אחר הבדל המסך המפסיק בין אצי' לבריאה והמל' בוקע המסך ונעשה כתר דבריאה כידוע עכ\"ז אין בלבבינו אלא אחד הגם שהשבטי' הן בבריאה וכידוע בענין הפסוק ששם עלו שבטי' כו' דשבטי' דנוק' הוא בו\"ק דבריאה ואמנם אמר ששם עלו שבטים מבריאה לאצילות ועולין בבחי' ו\"ק דז\"א דאצילות והן י\"ב גבולי אלכסון דאצילות ונק' שבטי יה שבטים דעלמא דדכורא כידוע ולזה אמרו כשם שאין כו' כך ממש אין בלבבינו כו' דיח\"ע ויחו\"ת שוין ממש ואין המסך מפסיק כלל וכמ\"ש כגוונא דאינון כו' כגוונא ממש בלי שום שינוי כלל ביניהם (וכמ\"ש במ\"א בענין ביום ההוא יהיה ב\"פ י\"ה כו' וגם מבואר במ\"א בענין ועד בחילופי אתוון דאחד ממש) והנה אנשי יריחו היו כורכין את שמע ולא היו אומרי' בשכמל\"ו ואין הלכה כאנשי יריחו (ומ\"מ במי שתורתו אומנתו דפטור מן התפלה וחייב בק\"ש כר\"י הנשיא לא היה אורמ רק שמע כו') ובמקדש היו אומרי' בשכמל\"ו בקול רם משום שהיה אז יחוד פב\"פ בבחי' זו\"נ דאצילות שאין שם מסך מפסיק כלל ויח\"ת שוה אז ליחו\"ע ממש וכן לע\"ל דכתיב יהיה ה' אחד כו' (ומה שבקול רם דווקא מבוא' במ\"א משום דא\"ח עט\"ב ויש עלי' למל' למעל' מז\"א ונק' קול כלה שלמעלה מקול חתן והוא בחי' קול גדול ולא יסף כו' ולכך או' ז\"פ כי ה' הוא האלקי' בעליי' המ' ביוה\"כ בקול רם דווקא) אך הנה בזמן הגלו' דאתתא כו' ואין היחוד בפב\"פ ואדרבה רישא שכיבת לעפרא שזהו בחי' חב\"ד דנוק' שירדו למטה בע' שרים שזהו ענין גלות השכינה כמ\"ש מקים מעפר דל שהוא מהסתר המל' בבריאה שנק' עפר שבקרקע המשכן כו' ועכ\"ז אנו אומרי' בשכמל\"ו דאין הלכה כאנשי יריחו ולא עוד אלא שעיקר היחוד הוא בבשכמל\"ו שנק' יח\"ת במה שהוא שוה ממש ליח\"ע שהרי ד' רבתי דאחד שמאריך בו הרי עיקר המכוון בו על בחי' יח\"ת דבשכמל\"ו דווקא שהרי א' תמליכהו בשמים וארץ וד' רוחות כו' שהן ו\"ק דבריאה שנק' מקום כידוע וד\"ל ועוד ראי' לזה ממה שאומרים פסד\"ז קודם כדי שיסדר אדם שבחו של מקום ואח\"כ יתפלל כידוע ולכאורה זהו פלא דהלא כל השבחי' שבפסד\"ז אינו מדבר רק בכל הנבראים בע\"ג איך שמהללים ומשבחי' כו' מצד בחי' ביטול היש לאין כמו הללו את ה' מן השמי' כו' וכן המלאכי' כו' וכולן לא נבראו רק מבחי' אותיות הדיבור העליון כמ\"ש בדבר ה' כו' כידוע שזהו אינו אלא בבחי' מל' דאצילות שמסתתרת בצמצום בבי\"ע אחרי"],[1700400116,"בקיעת המסך המבדיל בין אצילות לבריאה כידוע וזהו נק' שבחו של מקום דהיינו שבחו של כח האלקי שבא בבחי' כח הפועל בנפעל בזמן ומקום ואמנם נבדל ערכם מערך שבח עצמות אור האלהי כמו שהוא בחי' האצילות טרם שמחי' את הכל מאין ליש שנק' חי העולמי' ולכאורה עיקר השבח הי' ראוי להיות בגדולת עצמו' אור א\"ס ומדותיו שבאין בהתפשטו' או\"כ באצילות ואיך דאיהו וחיוהי חד שזהו ענין פסוק ראשון דשמע כו' וההקדמה לק\"ש בפסד\"ז בסידור שבחו של מקום הוא בלמטה הרבה מיחוד עליון שבק\"ש וזהו פלא דשבח דיח\"ע הרבה יותר נעלה ומשמעות הענין דפסד\"ז שבח עליון יותר כמי שישבחו להמלך קודם שיבא לשאול דבר ולקרב אליו כו' וגם מה שאנו רואי' בכל סידור שבחי' שבס' תהלים כמו בברכי נפשי וכה\"ג הכל מדבר בגדולת הבורא בריבוי הנבראי' יש מאין ואינו מדבר בשבח עצמו' האצי' ולמעלה כו' כלל וכלל ואין זה כ\"א שבהכרח יש בזה סוד ה' שבבחי' יח\"ת במל' שבבי\"ע שם נמצא כמו ושבח עצמו' אור הא\"ס יותר מבחי' יח\"ע דאצילות ע\"כ השבחי' הללו הכנה ליח\"ע דק\"ש משום דנעוץ תחלתן בסופן דווקא וכמשי\"ת בענין גדול אדונינו ורב כח כו' ובזה יובן ג\"כ איך דבשכמל\"ו יש בו יתרון מעלה מיח\"ע דפסוק ראשון (ובזמן הגלות יותר מבזמן בהמ\"ק אעפ\"י שהיו אומרים בשכמל\"ו בקול רם כמשי\"ת) ועוד ראי' לזה ממה שמצינו במצות היחוד העליון שהוא בבחי' יח\"ת דווקא דהיינו יחוד קודב\"ה ושכינתי' למטה על כל מצוה מעשיית וכה\"ג וכן במצות ידיעת אלקות שא' וידעת היום כו' וכן אתה הראת לדעת כו' הרי לא אמר רק לידע כי ה' הוא האלקים דווקא שזהו בחי' יח\"ת דאלקים בבי\"ע איך דהוי\"ה ואלקים כולא חד ואע\"פ שנא' כי שמש ומגן ה' אלהים וידוע דהמגן הוא בחי' הצמצום להסתיר שם הוי\"ה דז\"א דאצילות וכמארז\"ל ברישא חשוכא כו' והוא בחי' המסך המבדיל הנ\"ל וכידוע בענין באורך נראה אור שנק' אור של תולדה שאחר בקיעת המסך כו' עכ\"ז אדרבה עיקר מצות הידיעה לידע האמת איך שהוי\"ה ואלקים כולא חד ממש בלי שינוי כלל וכלל שזהו עיקר בחי' יח\"ת כידוע וגם מה שאנו מוצאי' בזוהר תרומה בענין ידיעת יחוד אלקו' שא' כל ב\"נ דלא אשתדל למידע ליה לקודב\"ה טב לי' דלא איברי כו' וכן מ\"ש לכבודי בראתיו בגין דישתמודעין ליה דוקא הרי ודאי מה שאנו יכולים להשיג באלקות אינו רק מבחי' התפשטו' פעולותיו בשמי' וארץ ובעולמות העליונים איך שנבראו מאין ליש ואין זה רק מבחי' שם אד' דאשתמודע אדון על כולא ונק' שם אד' שם הפעולה ולא שם העצם כידוע ואיך אמר שישתדל ב\"נ למינדע לי' לקוב\"ה עצמו וכן מ\"ש בגין דישתמודעין ליה לעצמו וכמו נודע בשערים בעלה בכל חד לפום שיעורא דיליה בהשגתו וידוע דבעלה זה היינו בחי' ז\"א שנק' סובב כ\"ע שלמעלה מהשפעה אלקי' בנבראי' שהוא שם הויה הנק' שם העצם דמה דאיהו וחיוהי חד נק' שמו העצמי דהיינו כמו ד' שמות ע\"ב ס\"ג כו' שם ע\"ב בחכמ' דאצילות וס\"ג בינה דאצילות ומ\"ה במילוי אלפין במדו' דאצילות כו' וכללותם נק' רזא דשמא קדישא אבל שם הפעולה דבחי' אד' שע\"ז א' ושמו אחד היינו מצד כח פעולותיו המתפשטי' חוץ מעצמותו בדיבור ובמעש' כידוע ואיך יכירו מזה במהות ועצמות דשם הוי\"ה דאצילות אלא ודאי שמזה דווקא יכירו בקוב\"ה עצמו אע\"ג דלית מח' תפיסא בעצמותו כידוע לפי שנעוץ תחלתן בסופן וכמ\"ש גדול אדונינו דווקא שבשם אד' דווקא ניכר עצם גדולתו העצמיות שלגדולתו אין חקר למעלה מעלה כו' וכמ\"ש גדול ה' ומהולל מאוד ולגדולתו אין חקר הרי מ\"ש ומהולל מאד מדבר בשבחו של מקום הנזכ' בפסוקי דזמרה דווקא שמהולל ומשובח בריבוי תשבחות במלאכי' וכל הנבראי' וזהו נק' מהולל מאוד בלי גבול ממש כמו שלגדולתו העצמי' אין לה חקר למעל'"],[1700400117,"מעלה במילוי אחר עילוי בעצמותו כו' וראי' לזה ממה שאמרו ז\"ל ע\"פ כיוצא בזה גדול ה' כו' בעיר אלקינו כו' אימתי גדול כשהוא בעיר אלקינו דווקא וידוע דעיר אלקינו הן בחי' אותיו' שנבראו בהן כל העולמו' וכמ\"ש בס\"י ה' אבני' בונות ק\"כ בתים כו' מכאן ואילך צא וחשוב עד אין שיעור כו' והיינו בחי' ריבוי הצרופי' שאין להן שיעור למטה וזהו הנק' עיר אלקינו דווקא שהעיר היא מרוב בנין בתים ואין שיעור לגבוליה לדרום ולצפון כמ\"ש ופרצת ימה וצפונה כו' ימין ושמאל תפרוצי כו' (שהחומה מגבלת הגבולים ונק' חתום וחותם וזהו חומת ציון ובירושלים דלעתיד כתיב פרזות תשב כו' וכמ\"ש במ\"א) וז\"ש גדול ה' ומהולל מאוד בלי גבול דא\"ס ממש דהיינו בעיר אלקינו דווקא שאמר ע\"ז אימתי גדול כו' לשלול בזה הגדולה זולת זה והוא הרמז דמה שלגדלותו העצמית אין חקר היינו מפני שמהולל מאוד בנבראי' למטה מטה בבחי' עיר אלקינו דווקא וכל זה מפני שנעוץ תחלתן בסופן דווק' וכמ\"ש גדול אדונינו ורב כח וידוע דזהו שיעור קומה של יוצר בראשית שהוא רל\"ו אלפי' רבבות פרסאות כו' גי' ורב כח רל\"ו וכמ\"ש בס\"י ומבואר במ\"א שיוצר בראשית זה הוא בחי' ו\"ק דבריאה ויצי' עד עשי' שנק' שיעור קומה ויש בו כחו של אור א\"ס עצמו שלגדולתו אין חקר ולתבונתו אין מספר כו' מטעם כלל הנ\"ל דאא\"ס למעלה עד אין קץ ולמטה עד אין תכלית דהיינו ביח\"ע ויח\"ת כנ\"ל אמנם אימתי גדול כו' דהיינו דוקא ביח\"ת דבחי' מל' דאצי' בבי\"ע דוקא שיש שם יתרון מעלה מיח\"ע (והיתרון של הסוף על התחלה עד שאמר אימתי גדול כו' וכמובן מכל ראיו' הנ\"ל ית' בסמוך בשרש ענין המסך המבדיל הנ\"ל שבזה יתורץ הכל) (עד שגם בזמן הגלות שהוא בהסתר פנים יותר יש בו יתרון מעלה מבזמן בהמ\"ק שהי' יחוד פב\"פ כו' וד\"ל):\n(יח) <b>והנה</b> להבין את כל הנ\"ל בענין יתרון מעלה דיח\"ת דבשכמל\"ו על יח\"ע כו' יש להקדי' תחלה טעם כללי לזה שהוא אינו רק מצד ענין הידוע שבחי' יח\"ת דבחי' מל' בבי\"ע שם הוא התחדשו' הבריא' מאין ליש שנק' חידוש גמור ןוזה בא מסיבת המסך המבדיל בין אצי' לבריאה כנ\"ל שע\"ז נאמר באורך נראה כו' אור של תולדה שנק' אור חדש מעיקרו וכמשי\"ת וע\"ז אמר כיתרון אור מתוך החשך דוקא יתרון ממש על אור העצם דכל בחי' יח\"ע שאין שם חידוש גמור ממש הנק' יש מאין המוחלט וכמ\"ש למעלה דגם בענין הצמצום הראשון שנק' מק\"פ כו' גם הוא אינו בא בבחי' מסך מבדיל רק העד' גלוי אור הראשון וגם מאו' הראשון נשאר רשימו עכ\"פ כו' ונמצא כל מה שנמשך מהעלם עצמותו ע\"י צמצום הראשון הזה מטה\"ע לטה\"ת כנ\"ל הכל בבחי' גלוי אור עצמותו שאין כל חדש מעיקרו בזה עד בחי' התלבשות האורו' דע\"ס דאצי' בפנימיו' הכלי' כנ\"ל שע\"ז א' איהו וחיוהי וגרמוהי חד כו' לפי שכל זה אינו רק גלוי העלם עצם אור העצמו' כל' אצי' ויאצל מן הרוח כו' ונק' אדם דאצי' אדמה לעליון ממש משום דאיהו וחיוהי חד בעצמו כו' וכמובן מכל מה שמבואר למעלה בפסוק ראשון דשמע עד א\"ח דלית רבתי דאחד שכלול הכל רק במאמ' אחד דס\"י כדמיון שלהבת הקשורה כו' אבל כל עיקר בחי' יח\"ת דמל' בבי\"ע אינו רק ע\"י בחי' הבדלת המסך הנ\"ל שדם כבר נפסק הארת הקו וחוט הראשון כידוע וכל עיקר יח\"ע בפרטות אינו רק ע\"י הארת הקו שם דוקא והמסך המבדיל לא יגיע שם הארת הקו ונפסק שם יחוד וקש' אל העצמות ואמנם יתרון מעלתו אינו רק מצד שהארת עצמות א\"ס ממש נמצא שם יותר מבהארת הקו שנמשך אחר צמצום הראשון משום דמה שאא\"ס למטה עד אין כו' יותר גדול כמ\"ש גדול אדונינו ורב כח וקאי על בחי' יח\"ת דוקא כנ\"ל בענין גדול"],[1700400118,"ה' ומהולל מאד וכמארז\"ל אימתי גדול כו' דמשמע שזהו יותר נעלה וכנ\"ל והכל רק מצד שהבריאה יש מאין בזה נמצא רב כוחו של העצמו' יות' מבתחלת אצילות המאציל כי הבריאה מן הבורא חידוש גמור ואצילות מן המאציל אינו חידוש גמור וכמ\"ש קורא הדורות מראש מהעלם לגילוי וכנ\"ל וד\"ל ולהבין ביאור הדברים בדרך פרט הנה תחלה יש להבין מה שיש לכאורה סתירה בענין זה דלפעמים משמע דאין יתרון מעלה כלל ביח\"ת מביח\"ע רק אדרבה שניהם שוין ממש וכמו לעתיד דכתיב והיה אור הלבנה כאור החמה ולא יותר מאור החמה והיינו כשבחי' זו\"נ שוין בקומתן כידוע וכל המאמרי' שבזוהר ודברי רז\"ל מורין ע\"ז כמו מאמר דכגוונא דאינון כו' אוף הכי אתייחדת לתתא ולא ביתרון מעלה אלא למהוי אחד באחד ממש בשוה וכן מאמר רז\"ל בשבטים דכשם שאין בלבך כו' כך אין בלבנו כו' ולא יותר ממה שבלבך כו' דאיך יהיה יתרון למקבל על המשפיע ולפעמים משמע דיש יתרון מעלה ביח\"ת משום דא\"ח עט\"ב והוא בחי' עליי' המל' למעלה מן המשפיע וכמ\"ש ביום ההוא יצאו מים חיים מירושלי' חצים אל הים כו' (וכמ\"ש במ\"א בענין כל אשר תאמר אליך שרה שמע בקולה דהטעימן מעין עוה\"ב שהוא לאחר הבירור דא\"ח עט\"ב ונקבה תסובב גבר ולכך תשמע בקולה כו') והיינו כל הנ\"ל בענין בשכמל\"ו בקול רם כו' ובמה שפסד\"ז בשבח הבריא' יש מאין מבחי' מל' יותר עליון מיח\"ע דק\"ש כו' וכן ממצות היחוד דה' אלקי' כו' עד ששם הפעולה דאד' למעלה משם העצם דהוי' וכמ\"ש גדול אדונינו כו' ואימתי גדול כו' וכנ\"ל באריכות והנה מטעם הכלל דנעוץ תחלתן בסופן וסופן כו' א\"כ אין יתרון לסוף על התחלה וגם משמעו' הענין דאא\"ס למעלה עד אין כו' ולמטה עד כו' אינו מורה כלל שיהי' יתרון מעלה בלמטה מלמעל' מאחר שעצמו' אא\"ס ממש אין בו בחי' מעלה ומטה רק ע\"י הארת הקו כו' וא\"כ מה שנמצא ממנו ב' מדרגות דלמעל' עד כו' שניהן שוין בבחי' א\"ס ולמה יש יתרון למט' יותר מלמעלה ואם מצד שלאחר הבירור כמו בעוה\"ב יש יתרון למטה יותר מטעם דא\"ח כו' היא גופא יש להבין למה יפעול ענין הבירורים דרפ\"ח כו' יתרון אור מן העצם כמו שהוא שנאמר לגדולתו אין חקר למעל' כו' ואדרב' ממה שנק' העוה\"ב יום שכולו ארוך הרי למט' ולמעל' שוין דהיינו כמו שאין לו תחלה כך אין לו תכלה והיינו הך ממש דארוך בראשו וסופו כו' ואם מפני שנא' כיתרון אור כו' הרי זה נא' בצמצום הראשון הנק' מק\"פ כו' דכתיב ישת חושך סתרו ואינו נק' מבדיל ממש אך כל זה יובן בהקדמה א' והוא בהפרש שבין מאמר הראשון יהי אור למאמר השני דיהי רקיע כו' דהנה ידוע בענין אור מים רקיע דמאמר יהי אור קאי בבחי' אור החסד שהוא ביום הא' ומאמר הב' דיהי רקיע קאי בבחי' הגבורה שהוא ביום ב' מפני שבא הרקיע הזה להבדיל בין מ\"ע שהוא לצמצם ולהסתיר ממש כו' והנה אמר בזוהר בראשית ע\"פ יהי אור אור קדמאה כו' והענין הוא כידוע בענין ב' מדרגות בע\"ס בבחי' אור ישר ובבחי' או\"ח דע\"ס דא\"י שרשם מבחי' החסד עצמי שבעצמו' אא\"ס ממש כי חפץ חסד הוא בעצם מהותו ע\"כ עלה ברצונו אנא אמלוך כו' וכמ\"ש כי אמרתי עולם חסד יבנה היינו חפץ חסד העצמי כמ\"ש בע\"ח ושרש ענין החסד שיורד מגבוה לנמוך דהיינו במקום גדולתו שם ימצא ענוה שם דווקא שמפני רוממות עצמותו למעלה עד אין כו' זה גורם ירידתו בחסד להיות רצון פשוט ולשער בעצמו כו' והיינו פי' יהי אור דמשמע יהי אור אחר ההעלם והצמצום דישת חושך סתרו וכמ\"ש באורך נרא' אור דהיינו שהיה אור הגנוז בעצמותו שנק' טה\"ע וצמצם א\"ע להיות נראה אור מתוך העלם אור העצם"],[1700400119,"דוקא והוא טה\"ת בבחי' קו וחוט כו' מקיפי' ופנימי' מתעגל וחוזר ומתעגל כו' והוא בחי' ע\"ס דא\"י בכלל כידוע וצמצו' זה חסד הוא כדי שיוכל להיות בחי' מעלה ומטה ע\"י הקו כו' והיינו כללות ענין דיח\"ע שהן ע\"ס דאצילות שנאצלו מן עצמו' המאציל מהעלם לגלוי שעצם שרשם אינו רק בחי' חפץ חסד העצמי וכמ\"ש יומ' יצוה ה' חסדו יומם דווקא שהוא נק' טה\"ע והוא מ\"ש באורך והחסד הי' שיצמצם א\"ע וזהו ויאמר אלקי' יהי אור שיתהווה אחר ההעלם דחשך סתרו ונק' אור קדמאה בב' אופנים הא' קודם הצמצום שנק' טה\"ע והב' אחר הצמצום שנק' טה\"ת (כי אור דטה\"ע שהוא חסד יקרא עכ\"פ והחסד נק' אור רק שהו' אור עצמותו ממש כו') וכל מה שיוצא ונמשך ובא בהשתלשלות הקו הזה עד ע\"ס דאצילות בכלים מכלים שונים כל זה רק מצד חסד הפשוט שאמר עולם חסד יבנה והיינו שאמר והי' העולם שאמר בחסדו העצמי רק מ\"ש ע\"ז כיתרון אור מתוך החושך אינו מסך מבדיל רק שאינו כאור הראשון כנ\"ל ומפני זה יש יתרון והיתרון הוא מה שגובר חסדו זה בהמשכת ע\"ס דאו\"י עד שבוקע גם המסך שבין אצילות לבריאה ומאיר גם בבריאה יצירה עשיה שנפסק שם אור עצם הקו רק מצד יתרון האור שבו שבא מתוך ההעלם דוקא וכמ\"ש במקום אחר בענין ויהי הענן והחושך ויאר שהחושך האיר היינו ההעלם בא לגלוי שהוא יותר מכפי המדה במאמר קו המדה שבקו זה לכך בוקע המסך שבין אצילות לבריאה ונעשה יחוד מל' בבריאה כמו באצילות ממש ועוד יורד חסד זה מבריא' ליצי' ובוקע המסך שבין בריאה ליצי' וכן מסך שבין יצי' לעשי' עד שיאיר אור א\"ס במל' דעשי' כמו במל' דא\"ס שבקו כו' בלי שינוי כלל וכלל כידוע והיינו מפני הכלל הידוע בע\"ח דאור החסד אינו מתעבה כו' פי' שאינו מתעבה ומחשיך אורו בירידתו גם בהיותו יורד למטה מטה מאד עד מל' דעשי' בגלגלי' וצבא השמי' הגשמיי' מקור ד\"י הגשמיי' וכמאמ' ומסד' את הכוכבי' דגלגלי' כרצונו הפשוט שבעצמו שעלה ברצונו להאציל ממש בשוה וכמ\"ש מגיד מראשית אחרית מראשית הקו לסופו וגם מקדם לקו אשר לא נעשה מגיד והוא בסוף העשי' כו' וזהו מאמר דיהי אור מתוך החושך והצמצום דהיינו כל עיקר יח\"ע וע\"ז א' כגוונא דאינון כו' אוף הכי ולא יותר וכן כשם שאין בלבך כך אין בלבנו ולא יותר רק הרבותא מה שבוקע המסך ומאיר למטה כמו למעלה בשוה ממש ואמנם מה שלפעמי' משמע דיש יתרון ביח\"ת יותר מיח\"ע כנ\"ל בענין אימתי גדול ובענין א\"ח עט\"ב כו' וכל הראיות דלעיל כ\"ז מדבר בבחי' מסך שמבדיל בין אצי' כו' שזהו ענין מאמר הב' דיהי רקיע בתוך המים כו' דרקיע זה היינו בחי' המסך שמבדיל בין מ\"ע דאצילו' למ\"ת כו' והרקיע הזה נא' בו ויעש כו' ובאור וחושך נאמ' ויבדל אלהי' בין האור ולא נזכ' במה הבדיל רק לפי שהי' אור וחושך משתמשין בערבוביא תחלה הבדילם והוא ענין צמצום הא' דמק\"פ כו' משא\"כ הרקיע ביום הב' הוא מסך ממש להסתי' הסת' גמור ומה שנרא' אור מתוך המסך נק' אור חדש לגמרי כו' ולא כאור מתוך החושך שאין כל חדש בו כנ\"ל והענין הוא דרך כלל שזהו בחי' ע\"ס דאו\"ח והיינו סוף מעשה שעל' במח' תחל' והוא סוף הרצון שעיקרו המעשה דווקא והיינו חידוש הבריאה יש מאין שלזה הי' תחלת הרצון לרצון בתחלת התעוררות חסדו העצמי כו' והן הן גבורותיו שיוכל לצמצם ולהסתיר לגמרי כדי שיהי' בריאה יש בע\"ג כו' ובחי' גבורה זו יותר נעלה מבחי' חסד שבתחלה כשעלה ברצונו כו' ונק' גבורה שבחסד עד שמחמת זה דוקא יש יתרון מעלה ביח\"ת מיח\"ע והוא מה שמורין כל הראיות הנ\"ל מ\"ש ויעש ה'"],[1700400120,"את כו' וכל זה טעם כללי לענין יתרון המעלה ביח\"ת בכל מה שמבוא' למעלה בענין א\"ח עט\"ב ובענין אימתי גדול כו' ודרך פרט ית' בסמוך בעזר\"ה וד\"ל:\n(יט) <b>ולהבין</b> בתוס' ביאור דרך פרט במאמר יהי רקיע הנ\"ל שהוא המסך המבדיל כו' הנה כבר מבואר למעלה (בסי' ב') בפי' ויעש אלקים את הרקיע כו' שזהו כמו חצר הכבד כו' וקרומא שבמוח כו' שדבר המבדיל מורכב מאמצעית תכלית הרוחני לבא בהגשמה כדמיון הממציא משל מדבר זר לעומק רוחניות אור השכל כו' וכמו הרקיע שעל ראשי החיות כו' כדי שיוכלו לקבל השגות זיו השכינה כו' ע\"ש באריכות והבדלה זו מבחי' גבורות וצמצומי' להסתיר כ\"כ אור העצם ולהביאו בהגשמ' אור כדי שיוכל להיות חידוש הבריאה יש מאין שאין ערוך לו לבלתי בע\"ג כנ\"ל וע\"י הבדלה זו נבדל רוחניות דמ\"ע דח\"ע שבמדות דז\"א לתכלית העילוי וירדו בחי' מ\"ת דהיינו ח\"ת דמל' בג' עולמות למטה מטה עד שא' כולם בחכ' עשית עד אפי' הגשמת הדצ\"ח כו' לפי שזהו דרך וטבע המסך המבדיל להבדיל במה שהי' מעורב תחלה כו' כנ\"ל שם באריכות והיינו והמים אשר מעל השמי' כו' אך יש להבין זה איך שייך זה למעלה להיות מסך בין אצי' כו' ששרשו בחי' חיצוניו' דבינה הנק' חשמ\"ל ונמשך עד למטה מתחת רגליהם להבדיל כו' והנה מבואר למעלה באריכות בענין פנימי' הכלים וחיצוניות הכלים (בסי' טז) דהתפשטו' הפעול' חוץ מן העצמות הוא באמצעות חיצוניות הכלים דז\"א כמו חסד דרועא ימינא דקודב\"ה ע\"ז א' אף ידי יסדה ארץ וכה\"ג בכל אורות שפע האלקי' מאצילות לבריאה כו' הכל הוא רק מחיצוניות הכלים דנה\"י דז\"א (שהן למ\"ד כלים שמהם נעשים נר\"ן בבי\"ע והן שרשי' לבחי' המל' ונק' שלשים מעלות והן הגבורים אשר לדוד וכאשר כפולים מחג\"ת ונה\"י נק' ס' גבורים מגבורי ישראל דלעילא כמ\"ש בזוהר ע\"פ הנה מטתו שלשלמה כו' משום דעיקר בנין המל' מהגבורות) ע\"פ הנה מטתו שלשלמה כו' משום דעיקר בנין המל' מהגבורות) ובזה עיק' ענין הפרסא שנק' רקיע המבדיל כו' בין מ\"ע דמוחי' דז\"א בבחי' פנימי' הכלים ובין חיצוניו' הכלי' דנה\"י שהמל' מלבשת שזהו ד' רבתי בחי' תנה\"י דז\"א שמלובש במח' ודבור כו' וכאשר מלובשים במח' שהוא בחי' לאה נק' ד' רבתי ויורדת לדבור שהוא ענין עקבי לאה נכנסי' תוך ראש רחל כידוע בענין מה שעשת' ענוה דלא' עקב לסולית' עשתה יראה שהוא המל' עטרה לראשה ונק' כת' מל' וז\"ש עקב ענוה יראת ה' וזהו ענין תמליכהו במל' דתבונה במח' בחי' לאה בו\"ק שמקבלת מז\"א שהן שמים וארץ כו' ונמשך להיות בבחי' כח הפועל בנפעל במל' דאצי' בבי\"ע בו\"ק שבדיבור שהוא ענין בשכמל\"ו כידוע אך עיקר ענין תמליכהו היינו כמ\"ש המלך המרומ' לבדו המתנש' מימות עולם וכמ\"ש דוד ארוממך אלהי המלך כו' וידוע שזהו בבחי' כתר מל' שמרומם לבדו ומתנשא על ימות עולם שהן ו\"ק דשמים וארץ כו' וזהו תמליכהו בהתנשאו' דבחי' כתר מל' וזהו העטר' דמל' שמקבלת מד' רבתי שבמח' כמ\"ש עקב ענוה כו' כנ\"ל ונמצא דברו' שם כו' זה הוא בבחי' כתר מל' כמו ויעש דוד שם שהוא שם ומל' דוד מאצי' בבי\"ע להיות מלך על עם וכמו שידוע בענין ה' מלך גאות לבש כו' והיינו המלך המתנשא כו' וידוע בע\"ח דכתר זה למעלה הוא תמיד בבחי' האצי' וכמו שכתוב לעולם ה' דברך נצב בשמים פירוש דברך עצם כח הדבור העליון שהוא בחי' כתר מל' שדבוק תמיד בחזה דז\"א כו' שזהו נק' שמים עליונים ורק בחי' ט\"ס דמל' יורדי' למטה מאצי' לבריאה ע\"י בקיעת המסך שהמל' בוקע המסך ונעשה ראש לשועלים כו' כידוע (וכמ\"ש במ\"א בענין ישמעאל בני ברכני אמר יהי רצון מלפניך כו' שזהו כתר דבריאה שאחר המסך וא' יהי רצון מלפניך מכתר"],[1700400121,"מל' דאצי' שלפני המסך כו') ויש להבין מהו בחי' כתר מל' שמובדל ומרומם ומתנשא כו' ועכ\"ז ה' מלך גאות כו' שבזה עיקר ומקור כל התהוות הבריא' יש מאין מחכמ' ולמטה בג' עולמות דבי\"ע כידוע שע\"ז אמר כתר מל' איהו כתר עליון דאצי' משום דנעוץ תחלתן בסופן כו' (וכמ\"ש בפי' תהלה לדוד ארוממך בך' פשוטה כו' באריכות ע\"ש) ע\"כ הוא מרומם לבדו כו' שהרי הד' רבתי נחשב מבחי' יח\"ע ממש וביאור הדברי' הנה יש להקדים תחלה ביאור הפסוק דכל אשר חפץ ה' עשה בשמי' וארץ בימים וכל תהומות כו' ויש להבין מהו הרבות' דכל אשר חפץ עשה מאחר שהכל ברצונו עשה וכתיב בראשית בקדמין שזהו ברצונו כו' וגם מה שמרבה בכל אשר חפץ דמשמע ריבוי רצונות מחולקו' וכל אשר חפץ עשה כו' מהו הרבותא בזה ועוד יש להבין מהו הריבוי דכל אשר חפץ בב' אופנים דוקא בשמי' וארץ וימי' כו' דמשמע שיש רבותא בכל א' מה שאין בזולתו וכמו הללו את ה' מן השמים כו' עד והמים אשר כו' ואח\"כ הללו כו' מן הארץ בפ\"ע כו' וכן אתה עשית את השמים שמי השמים כו' הארץ כו' והנה ג' דברי' מזכיר שמי' וארץ וימי' וכל תהומו' כו' להיות ידוע במ\"ש יקוו המים כו' שהי' קודם הבריאה רק מים וביום ב' הרקיע הבדיל בין מ\"ע ומ\"ת ואח\"כ ביום הג' ויאמר אלקי' יקוו המים כו' ותרא' היבשה כו' ויקרא אלקים ליבשה ארץ ולמקוה המי' קרא ימי' ובאותו יום ויאמ' אלקים תדשא הארץ כו' ונמצא מה שקרט לרקיע שמי' וליבשה ארץ הי' בב' ימים הללו דוקא במ\"ש ביום ב' יהי רקיע להבדיל ואז אמר ויקרא אלקי' לרקיע שמי' וביום ג' שא' יקוו קרא ליבשה ארץ ולמקוה המים ימים אבל קודם שנקוו המים מתחת השמי' היתה היבשה נבלעת במי' ואעפ\"י שכבר נבדל בים ב' בין מ\"ע למ\"ת ונק' הרקיע שמי' אבל לא היתה יבשה ולא ימים עד שא' יקוו המים ועי\"ז נתגלה היבשה ונק' ארץ וגם למקוה המים שנקוו למקו' א' קרא ימים והרי יבשה וים ביום ג' נעשו והרקיע שנק' שמים ביום ב' אבל ביום א' שא' יהי אור לא הי' עדיין רקיע שנק' שמים ולא יבשה וים ומ\"ש והארץ הית' כו' קאי בארץ שהית' מובלעת במי' עליונים ותחתוני' מעורבי' יחד ומ\"ש בראשי' ברא כו' השמי' ואת הארץ והלא שמי' שהו' הרקיע ויבשה שנק' ארץ ביום ב' וג' נבראו לאחר שהבדיל בין מ\"ע כו' ואיך אמר בראשית דמשמע פשוטו שראשית להכל נבראו שמי' כו' והלא האור נברא תחלה אלא צ\"ל שבמח' דחכמ' נבראו' (וכת\"א בחוכמתא) וכידוע דבמאמר א' יכול להבראו' כו' והוא מאמר דבראשית כו' ואח\"כ באו לידי פועל במאמר יהי רקיע ובמאמר יקוו כו' ומשום דסוף מעשה דשמי' וארץ עלה במח' תחלה לכך א' בראשית ברא כו' משום דנעוץ סופן בתחלתן כו' (ומה שהי' הבדלה בין אור לחושך בים הא' עדיין לא הי' רקיע וארץ ועכ\"ז הי' יום ולילה כמ\"ש ויקרא אלקי' לאור יום כו' וע\"י המאורו' ביום ד' שנתן אותם ברקיע השמי' א' ולהבדיל בין האור כו') והנה להבין כ\"ז הנה מבואר למעלה (בסי' טי\"ת) שהרצון נחשב עם המעשה לא' ממש כי כל עיקר הרצון אנו אא בשביל המעשה ולעולם לא ימצא מציאת רצון בהתפעלו' לדבר מה אם אינו לפעול הדבר כרצונו (וגם בדבר חכמ' עיקר הרצון להשכיל בשכל אינו אלא להטות כל השכל כפי רצונו בחסד או בדין כך יהי' טעם לרצון כמו השוחד שמפני הרצון תלבש בטעם לחסד ונק' חסד דחכמ' ועיקרו כשבא לידי פ\"מ ואז נשלם רצונו וגם בלתי מעשה רק המשפט של חסד וזכות ג\"כ נק' סוף של הרצון שזהו כל עיקר הרצון ובלעדי זה לא נמצא מציאת רצון כי כל מהות רצון אינו מהות בפ\"ע כמהות שכל שגם שאין השכל בא במדות ומעשה היא מציאת שכל אבל אין מציאות לרצון לבדו בלי התחברותו בדבר מה אם בשכל או עונג או מדה או מעשה ומח' וכה\"ג הן המדות אהבה או שנאה"],[1700400122,"וניצוח תחילת מציאותן מחובר לדבר מה לאהוב דבר או לשנות דבר ששרש המדו' ברצון הוא רק שהן מוגבלין על ידי השכל שעוברין דרך טעם ושכל לרצון עד שמזה הטעם יתפעל באהבה בשכל ואח\"כ יתפעל בלב רק כפי אופן הגבלת השכל באהבה שבשכל כידוע) ונמצא שכל חילוקי המציאות שנמצאים דרך פרט ברצון כמו שכל וטעם שברצון מה שרצונו למעשה דוקא הכל נמצא דרך פרט במעשה עצמה לאחר שהובדל' מן הרצון ע\"ד דוגמא כאשר עולה ברצון לבנות בנין ועדיין אינו פועל במעשה הבנין כלל רק שרוצה שיהיה לו בנין וכלול הרצון הזה משכל וטעם ומדות פרטיי' כו' ואופן המעשה של הבנין ונסקרים כל הפרטי' בכללות רצון א' ואח\"כ פוסק מזה הרצון שרוצה בעצמו ומתחיל במעשה הבנין להשלים רצונו שאז המעשה נבדל מן הרצון כי אינו עוסק רק בפ\"מ רק שבא פ\"מ זה מכחו של רצון שרצה בזה המעשה ואמנם מפני שהרצון והמעשה א' הוא שהרי עיקר התחלת התעוררות הרצון לא הי' כלל במציאת אם לא למעשה בפ\"מ דווקא כנ\"ל א\"כ בהכרח לומר שכל מה שנמצא פרטיות חלקי' ברצון אותן הפרטי' ממש ימצאו בגופה של מעשה דהיינו אותו השכל הבא ברצון באופני' פרטיי' לזה הרצון הוא עצמו הבא באופנים שונים הללו בהשכלת אופני המעשה שהוא קיום הרצון ומה הפרש יש בין שכל וטעם בפרט לרצון לשכל וטעם לקיום מעשה שבו עיקר הרצון וכה\"ג כל פרטי התחלקות המדות שברצון חו\"ג וכה\"ג הכל יבואו דרך פרט כמו שהן ברצון באופנים מיוחדי' בגוף מעשה זו כמו אם להאריך או לקצר ונק' מדות שבעשי' שהן אותן מדות שברצון ממש וכנ\"ל (שם) בפי' מגיד מראשית כו' ומקדם כו' באריכו' וא\"כ כמו שיש פרטי רצונות רבות לכל פרטי השכל ומדות שברצון הכללי כך יש פרטי רצונות רבות במעשה של הרצון ומן הרצון הכללי מאיר כל פרט ופרט בשעה שעושה מעש' הבנין בכל פרט שבו שיהי' כפי' שהי' ברצון דוק' לא יגרעולא יוסיף מאומה כידוע ולפי\"ז אין הפרש בין המהות של עצם רצונו קודם שיבא לידי מעשה לרצון שבגוף המעשה שבודאי לא ישנ' בהכרח בפרטו' המעש' הכל כפי הרצון שהי' בו' תחל' ואע\"פ שיש הבדל וריחוק ביו רצון הרוחני שבנפשו לבנין זה להמעש' בפועל ידיו שמלובש בו רצונו בהתלבשות ותפיסא כאברים שנשמעי' לרצונו כו' ה\"ז כמו עד\"מ כשמצייר אדם בלוח בידו בתנועה גשמי' בכל הפרטי' שבמחשבתו ורצונו בציור מיוח' הזה לא יוסיף ולא יגרע דבר שמתאחד ודאי התנועה בפ\"מ עם רוחניות המח' ורצון שבמוח בכל פרט ופרט שבתנועה וד\"ל:\n(כ) <b>והנמשל</b> מכל הז יובן למעלה במ\"ש כל אשר חפץ ה' עשה דמשמע ריבוי רצונו' וכל אשר חפץ הכל עשה הענין הוא דכמו בבחי' יחו\"ע דמה שעלה ברצונו להאציל כו' הי' ברצון זה כלל תחלה ופרט דהיינו פרט התחלקות בשכל ומדות כו' ויצא אח\"כ לגלוי ברצון הבא לקיום דבר זה שהוא ענין אצי' עצמה וגם הוא יבא דרך פרט ממש כאותן פרטי' שהיו ברצון לעצמו להאציל כמובן ממשל הנ\"ל ברצון לבנין כך ממש בבחי' יח\"ת דהיינו בחי' הרצון לברוא הבריאה יש מאין כו' כלשון הזוהר כד סליק ברעותי' למברי עלמא כו' ורצון זה עיקר התחלתו רק בשביל גלוי רצונו במעשה שהוא גופה של התהוו' הבריאה מאין ליש שהוא ע\"י בחי' המל' כידוע וכנ\"ל במשל שהרצון והמעשה א' הוא ממש בכל פרטי חלקיהם כו' א\"כ ודאי דכל מה שהיה ברצון זה לברוא דרך פרט בחכמה וטעם לרצון ומדות פרטיי' כו' הכל נמצאו דרך פרט כמו שהן בבוא הרצון לידי מעשה שהוא להוות הבריאה כו' ומה שעלה ברצונו לעצמו למברי עלמא הוא בבחי' נבדל בערך מבחי' הרצון הבא בגלוי בפ\"מ זה שהוא להוות הבריאה"],[1700400123,"יש מאין רק שהוא בא באותו הדוגמא ממש בכל פרטי חלקיו כמו שהיה ברצון לעצמו ולא יוסיף ולא יגרע דבר ולא חצי דבר מכפי התחלקות השכל ומדו' שבעצם הרצון בשביל עולם הבריאה כמו המצייר דבר בלוח ע\"פ רצון ומח' בפרט שבמוח כנ\"ל וד\"ל וזהו כל אשר חפץ ה' לעצמו והיה דרך כלל ופרטי פרטו' דהיינו רבוי התחלקות רצונות לכל פרט של כל שכל ומדה באותו הרצון הכללי הכל הביא בבחי' גלוי הרצון בפ\"מ שהן ע\"ס דבריא' להוות הבריאה מאין ליש בפ\"מ וד\"ל וזהו פי' ברוך שאמר והיה העולם פי' שאמ' שרצה שהרצון היינו האמיר' שבהעל' כידוע וכתיב כי הוא אמר ויהי כו' וכן ההוא אמ' ולא יעש' משמע שיש אמירה שברצון שלא בא לידי מעשה עדיין רק שאמר לעצמו עדיין וכמו וה' פקד את שרה כו' כאשר אמר פי' כאשר אמר ברצונו לעצמו כידוע והיינו ג\"כ פי' ברוך שאמר לעצמו עדיין שיהי' העולם עולם הנאצל ועולם הנברא כו' עד עולם העשי' וכמ\"ש בראתיו יצרתיו אף עשיתיו כו' וזה והי' לשון עתיד שעתיד להיות וגם משמעו שבאמיר' זו בא ההויה מיד וזהו שאמ' ומיד והיה העולם ע\"י אמירה זו לפי שרצון זה שלעצמו אינו אלא למעשה דווקא וכל המעשה רק מכחו בא בכל פרט ופרט שבמעשה כנ\"ל וזהו ברוך המשכה עצמיי' תחלה לעצם מהות הרצון להיות העולם בפ\"מ ומיד והיה העולם וכמ\"ש ברוך אומר ועושה שמתלבש הרצון בכל פרט מהעלם לגלוי וז\"ש ברוך הוא בהעלם של הגלוי שנק' הוא (משא\"כ ברצון של עצמו לא נק' הוא כי כלול בעצמו ממש דלא ידע ליה בר איהו בלחודוהי כו' והוא בחי' רדל\"א וכמ\"ש בסידור ומבוא' במ\"א) והיינו פי' אתה הוא משנבר' כו' ואתה הוא קודם שנברא כו' בלי שינוי כלל כי אין המעשה נבדל מן הרצון כמו שלא נבדל התנועה בידו מרצונו שבמוח בכל פרט כנ\"ל וד\"ל (ומ\"ש ברוך גוזר ומקיי' אינו כפל ענין שלא לצורך אלא מה שבברוך שאמר ואומר ועושה מדבר בכללות הרצון שלעצמו שבא כמו שהוא בכללותו לגלוי בפועל ממש כך גם בפרטית ההתחלקו' של הרצון שלעצמו באין ג\"כ בהתחלקו' בפרטי' האלה בגלוי בפועל ממש וזהו גוזר לגזרים וחלקים פרטיי' ומקיים כל פרט כמו שהוא בכח הכלל כו' ופי' עושה בראשית היינו מגיד מראשית אחרית וכמו שי\"ת בסמוך והנה מ\"ש כל אשר חפץ ולא אשר רצה מפני שיש הפרש בין חפץ לרצון שהחפץ הוא בפנימיות חיות של הרצון כמו כי חפץ בבת כו' כי החפץ ותשוקה א' הוא כידוע והיינו כשהרצון לעצמו עדיין שיש בו חפץ ותשוקה משא\"כ בגילוי הרצון לבא לידי מעשה אין שם החפץ בגילוי רק בהעלם ולזה א' כל אשר חפץ הביא בגילוי רצון לעשות והנה כתיב אשר ברא אלקי' לעשות דווקא וז\"ש כל אשר חפץ עשה דווקא ולא א' כל אשר חפץ ברא משום דסוף מעשה דווקא עלה בתחלת המח' ורצון הנק' חפץ שהוא פנימית הרצון ועיקר המכוון שבו דודאי ברצון יש כמה דברים שבכולם חל הרצון ואמנם עיקר תמציתו הוא רק על דבר מיוחד שלזה נטפלו כל הרצונות פרטיי' והוא המעש' דוקא ולכאורה אין זה מובן דהלא בכל רצון יש בו סופא שלו והוא אשר בא לפ\"מ שלו כמו ברצון לשכל לזכות וחסד הרי סופו אינו המעשה של חסד דוקא אלא הטיית זה השכל לזכות כנ\"ל רק שמ\"מ עיקר פנימי' הרצון חל יותר במעשה של חסד בפ\"מ המסתעף מזה השכל של חסד יותר משהוא חל בהשכל של חסד מפני ששכל זה של חסד טפל הוא ברצון שעיקרו לפ\"מ דחסד ולא לשכל של חסד ומה שנתלבש הרצון בשכל של חסד אינו רק בשביל שיפסוק למעשה כך ולא מצד עצם השכל הזה שא\"צ לו אם היה החסד נעשה בלעדו אם כן טפל הוא לגבי המעשה וכמ\"כ יובן למעלה במ\"ש כי אמרתי עולם חסד יבנה כי אמרתי ברצון וחפץ כמו שאמר והי' העולם כנ\"ל ונתלבש בשכל"],[1700400124,"וטעם לרצון לחסד זה שיבנה העולם מחמתו ובודאי עיקר השראת החפץ הפנימי הוא בפ\"מ דחסד שהוא גוף הבריא' שזהו עולם יבנה ואע\"פ שנא' בחכמ' יבנה כו' והוא מאמר דבראשית כמ\"ש כולם בחכמ' עשית כידוע היינו רק חכמ' וטעם לרצון להטות כלפי חסד ועיקרו רק בשביל מעשה החסד בפ\"מ ואם הי' נעשה גם בלעדי השכל וטעם לרצון ה\"ז שלימות רצונו כמו עכשיו ע\"י הטעם כו' וד\"ל ובזה יתפרש פסוק דמגיד מראשי' אחרי' שהוא רצון שבשכל וחכמ' שק' ראשית הבא בפ\"מ הנק' אחרית והוא כמו מאמר דבראשית וגם מקדם לרצון זה היינו בקדמין ברא שהוא פנימית הרצון טרם שבא בשכל כו' אשר לא נעשה שלא בא לידי מעשה כי אינו רק לעצמו עדיין כנ\"ל שהחפץ ופנימית הרצון אינו רק לעצמו כו' גם הוא מגיד וממשיך והוא כאשר נשלם המעשה בכי טוב כמו וירא אלקים את כל אשר עשה והנה טוב כו' שנתקיים הפ\"מ כמו שהיה בפנימית רצונו דוק' לפי שבסוף מעש' דוק' היה היותר פנימי' שברצון תחלה לעצמו וד\"ל וזהו אשר ברא אלקים לעשות פירש כי בו שבת מכל מלאכתו וירא את כל אשר עשה כו' שנשלם פנימית רצונו דוקא שלזה ברא אלקי' במאמר דבראשית בחוכמתא רק לעשות דוקא מטעם הנ\"ל אבל מ\"ש ברוך שאמ' וגם מ\"ש אומ' ועושה שהוא מפנימי' רצונו הכללי שבא כמו שהוא למעש' היינו כמ\"ש ומקדם כנ\"ל וד\"ל והנה עדיין אין זה מובן מ\"ש כל אשר חפץ ה' עשה דוקא שבמעשה דוקא בא הריבוי דכל אשר חפץ כו' וכן במ\"ש וירא אלקי' את כל אשר עשה ולא כל אשר ברא ויצר והאציל כו' אך הנה יש להקדי' ענין המבואר למעלה (בסי' יו\"ד) שיש מח' כללית ומח' פרטית והכללית נק' מח' אחת דוקא שצופה וסוקר עד סוף כו' שנסקרתחלה וסוף כא' מבלי שיוקדם לא' על זולתו כאדם המביט בכדור עגולי שמקיפו בהשווא' מראשו לסופו כו' עד שאין כאן ראש וסוף כלל ולפ\"ז מהו שא' סוף מעשה עיקר יותר אלא מוכרח לומר שאין זה מצד שבסוף יש עיקר הרצון יותר מבתחלה מאחר שנסקר תחלה וסוף מבלי נודע בחי' ראש וסוף ולמעלה מבואר שבסוף דוקא יש עיקר ופנימית החפץ יותר מהתחלה אך צריך לומר משום דבפרט מן הרצון אין שום שלימותו עדיין רק מכללות כל חלקיו כא' שם הוא כל שלימותו העצמי עד\"מ מו\"מ או בנין בכל פרט שבו יש עונג ורצון בפרט ואינו שלימות הרצון רק אחר גמר כל חלקי הבנין או עסק המו\"מ לא יחסר דבר אז יושלם הרצון והעונג ונמצא זה השלימות אינו מצד הסוף לבדו אלא מפני שבו הגמר של כל הענין וכללותו נכלל בו וזהו יתרון מעלת הסוף כי מצד עצמו אנו רק חלק פרטי העומד בסוף רק דוקא מפני שבו כלול הכל משא\"כ באמצע ובתחל' דגם שבתחלת הרצון כולל הכל אבל לא בפ\"מ עדיין ונמצא שניהם אמת שהסוף עיקר הרצון בו יותר ולא מצד חלקו לבד אלא מפני שהוא הגמר של הכל שבו כלול הכל ולא מצד ההתכללות לבד שהרי הכל הי' כא' בטרם שבא למעשה אבל מצד המעשה בעצם שזהו עיקר הרצון דוקא ומצד שיש במעש' מהכל דוקא ע\"י אמצעית שניהם נמצא בו דוקא עיקר פנימי' הרצון שהי' בכללות המח' כמו עונג שמגיע לאדם מכללות כל העסק מו\"מ או הבנין לאחר גמרו דוקא כנ\"ל שם וד\"ל והנמשל מזה יובן למעלה במח' ורצון כללי דכל אשר חפץ ה' עשה כו' דודאי כל אשר חפץ זה כולל כמה רצונות וחפצי' פרטיי' שכלולים בכללות המח' ורצון לעצמו בסקירה א' מבלי שימצא בזה קדימה לראש על סוף ולא לסוף על ראש ומ\"ש סוף מעשה עלה תחלה במח' היינו כשהמח' באה להתחלקות פרטיי' שיש בו תחלה וסוף כו' ואמנם ענין"],[1700400125,"סוף המעשה שלזה עיקר הרצון הי' יותר שע\"ז א' סוף מעשה עבמ\"ת אינו רק כאשר במעשה יכלול הכל דוקא ולא מצד חלק המעשה לבד וכמובן ממשל הנ\"ל ברצון לבנין או מו\"מ וז\"ש כל אשר חפץ בריבוי הכל דוקא מכל אשר חפץ ולא יחסר גם חפץ ורצון א' פרטי שבפרט השכל ומדו' שברצון ובתנאי השני שיהי' הכללו' כל אשר חפץ בפ\"מ דוק' שהמעש' הוא הי' עיק' פנימי' הרצון אז הוא שלימו' של הרצון דווק' וכן יתפר' וירא את כל אשר עשה והנה טוב כו' שזהו דוק' כאשר עשה בפ\"מ דוקא וכל אשר עשה דוקא שלא נחסר דבר שבאמצעו' שניהם בכללו' הכל הבא בפ\"מ שם דווק' ויהי' עיק' השלימו' ברצון הקדום הנק' טוב מאד וכמ\"ש במ\"א בענין עליות העולמו' בשבת שעול' סוף מעשה בגמרה דווקא כמ\"ש כי בו שבת מכל מלאכתו מכל דווק' וירא את כל אשר עשה כו' וגם כל אשר חפץ ריבוי דכל במעש' נשלם הרצון וחפץ ה' והיינו במ\"ש בשמים וארץ בימי' וכו' שאם הי' כל אשר חפץ בשמי' לבד כמו ואלקינו בשמי' כל אשר כו' או בארץ לבד כו' אין זה שלימו' עדיין רק מכל אשר עשה בשמים וארץ מכללותם יחד וכן בימים ותהומות כו' מטעם הנ\"ל וד\"ל (וענין שמי' וארץ וימי' כו' ית' בסי' שאח\"ז בענין תמליכהו כו') (ובזה יתפרש פי' ברוך שאמר בהיפך מפי' דלעיל דהיינו שאמר והי' בפ\"מ דווקא שבזה נשלם שלימו' הרצון שהי' לעצמו והיינו ברוך הוא בעל הרצון שמתעורר מחמת זה להיות אומר ועושה מחדש שזהו עיקר סיבת חידוש מע\"ב בכל יום כמ\"ש כי אמרתי כו' בכל יום כו' וגוזר ומקיי' הכל בפרט הבא בשכל ומדות שז\"ש ברוך עושה בראשית פי' עושה מה שגוזר כמ\"ש ותגזור אומר ויקם כו' וכה\"ש מבואר במ\"א ע\"ש):\n(כא) <b>ומעתה</b> יש להבין מ\"ש כל אשר חפץ ה' עשה בשמי' וארץ דוק' דהנ' ידוע בביאור המחלוקת אם שמים קדמו כמ\"ש בראשית כו' את השמים וכו' ואם הארץ קדמה כמ\"ש ביום עשות ה' כו' ארץ ושמי' והמכריע ששניהם כא' נבראו (והוא אהו\"ה גי' טוב דאת השמי' כו' דאחיד בשמיא וארעא) והענין הוא דהשמי' הוא הרקיע המבדיל בין מ\"ע למ\"ת כנ\"ל וכמ\"ש ויקרא כו' לרקיע שמים והמי' עליונים שמעל השמי' טרם שנעשה הרקיע נא' בהם ורוח אלקים מרחפת על פני המי' כו' שזהו ביום הא' שאמ' יהי אור ומבואר למעלה שרקיע זה המבדיל כו' הוא בחי' המסך להעלים ולהסתיר שהוא מבחי' הגבורות והצמצומין כמו ועל ראשי החיות רקיע כעין הקרח דאגלידו מיא ושמים כלול מאש ומי' כו' שהגבורות הן מכווצי' וכמ\"ש במ\"א בעני' כבש באשא כו' ובחי' מ\"ע היינו ח\"ע שברצון ומח' הכללי' שלעצמו כמו כד סליק ברעות' למברי כו' וכנ\"ל דכל מה שהיה ברצון זה שכל וטעם לרצון ומדו' דרך פרט הכל בא לגלוי בבחי' מקור לבריאה יש מאין אח\"כ כמו המצייר בלוח כו' (כנ\"ל בראש סי' ד') וז\"ש כל אשר חפץ ה' לעצמו שנבדל הוא בערך מבחי' הרצון שבא מכחו לידי גילוי להיות ממש ברצון זה שנק' כתר דבריאה וכה\"ג ולזאת הוצרך להיות הבדלה ביניהם שהיא להעלי' ולהסתיר עצם רצונו זה הכלול מכל הפרטי' ולהיות נמשך בחי' הרצון לבא למעשה בפ\"מ עד\"מ מי שעלה ברצונו לעצמו כל מעשה הבנין שכאשר ירצה לבנות בפ\"מ בהכרח שיסלק ויעלים ויפסוק רצונו שלעצמו ולעסוק ברצון הגלוי לפ\"מ והוצרך להפסיק ולהעלי' עצם רצונו הפשוט שיורכב בהגשמת המעלה אזי נק' הרכבה מרוחניות רצונו שלעצמו עם ההגשמה דמעשה לעשות רצונו כו' וכך יובן למעלה שהרקיע הוא העלמת אור העצם דרצון הבא בלב דז\"א שנק' אדם דאצי' ולהביאו לגילוי במח' ודיבור לאה ורחל שהן י' מאמרות בהעלם וגלוי כו' וז\"ש לעולם ה' דברך נצב"],[1700400126,"בשמי' שהוא הרקיע שמבדיל כו' דהיינו בפי' כתר מל' שמהחזה דז\"א ולמטה כו' כמ\"ש בע\"ח וז\"ש ה' מלך גאות לבש כו' וכנ\"ל (בסי' י\"ט) באריכו' וזהו ענין ד' רבתי דאחד תמליכהו בשמי' וארץ כו' שמים הוא הרקיע שנעשה ביום ב' מבחי' הגבורות כו' והוא הטעם דמ\"ד שמים נבראו תחלה שבו העלם הרצון הכללי' שלעצמו כדי שיוכל להיות הבריאה יש מאין ממש מבחי' מ\"ת שהוא ח\"ת שברצון הבא בגלוי לפי שכטבע המסך להבדיל מן הקצה לקצה כו' כנ\"ל וע\"י אמצעות הרקיע הזה נעשה מקור כל הברואי' (וכמו הרקיע שעל החיות שמקבלים משם) ואעפ\"י שאמר ע\"ז המלך המרומם לבדו כו' היינו מפני שהוא נבדל בערך מירידה זאת גם להיות מקור לבריאה וזהו המתנשא מימות עולם הבריאה וזהו פירש תמליכהו בשמי' ג\"כ והיינו להיות שבחי' כתר מל' דבוק בעצם המדות דאצילות וז\"ש השמי' כסאי והארץ הדם רגלי כו' דשמי' זה שנק' רקיע נק' כסא המל' שיורד לישב להיות מלך כו' אבל בעצם מרומם לבדו ומתנשא כו' שהוא ענין הרצון שלעצמו עדיין שכלול בעצם המהות שע\"ז אמר ג\"כ ברוך שאמ' והי' כנ\"ל וד\"ל ומ\"ש כל אשר חפץ בארץ ג\"כ משמע שיש רבותא בארץ אשר אין בשמי' והוא כמ\"ד ארץ נבראת תחלה היינו משום דסוף מעשה הוא עיקר פנימית הרצון הנק' חפץ כנ\"ל (בססי' ך' באריכות) בפי' לעשות דבראשית הוא הטעם של רצון לחסד עיקרו רק בשביל מעשה חסד בפ\"מ ואם הי' נעשה בלעדי הטעם נשלם עיקר הרצון שלמעלה מן הטעם כו' וזהו כי אמרתי עולם חסד כו' ומבואר ג\"כ שם שאין זה מצד חלק דמעשה שהוא אחרון ונעוץ בסופן שהרי בסקירה א' באו תחלה וסוף במח' ורצון הכללי מבלי שיש יתרון זע\"ז כלום כו' אלא משום שהסוף מעשה יש בו ב' מעלות א' שהוא עיקר המכוין של הרצון מצד עצם המעשה בפ\"מ דווקא והב' מפני שהוא הגמר הכולל הכל וכמ\"ש את כל אשר עשה כל רבוי הכל ובפ\"מ כי הגמר יש בו ב' תנאי' א' שהו' הגמר במעשה ולא נשאר הדבר בדבור ומח' דלגבי כל הכחות רוחניי' המעשה הגמר האחרון שקודם שבא למעשה אין שלימות בדבר עדיין והב' שהוא הגמר בכל הפרטי' מראשו לסופו שיכלול בו הכל ולא יחסר דבר כו' וזהו מ\"ד ארץ קדמה לשמי' דסוף מעשה עלה בתחלה למח' ורצון הבא בגלוי בתחלה להיותו עיקר יותר והוא הגמר בב' מעלות הנ\"ל והיינו מאמר דתדשא הארץ ותוצא הארץ כו' שנק' עלמא דאתגליי' מאין ליש ממש שזהו הי' פנימי' הרצון והוא גמר הכל בכללות' יחד וע\"ז אמר ג\"כ כל אשר חפץ עשה דבו יש רבותא יות' מכל אשר חפץ עשה בשמים שאין שם ענין הגמר בבחי' המעשה בפ\"מ והיינו שאמר ג\"כ בימים וכל תהומות דהנה הים דומה לרקיע דוקא והענין הוא להיות שביום ג' אמר יקוו המים מתחת השמי' כו' ויש להבין למה ביום ג' דווקא ובזוהר אמר יקוו בארח קו מישר שהוא בחי' קו האמצעי דת\"י כי יהי אור בקו ימין חח\"נ ויהי רקיע בקו שמאל בג\"ה ויקוו המים ביום ב' מבחי' הגבורות להבדיל ולצמצם עצם האור כנ\"ל והן הן גבורותיו עד שיוכל להעלים כ\"כ במסך שבין יצירה לעשי' כו' להיות גלגלי' ודצח\"מ גשמיי' כו' והנה ע\"ס דא\"י וע\"ש דא\"ח המה ב' הפכי' (והן שמי' וארץ בע\"ס דא\"י השמים קדמו ובע\"ס דא\"ח הארץ קדמה כמ\"ש במ\"א) והמחברם וכוללם יחד הוא בחי' קו האמצעי והיינו יקוו המים כו' בהיות שגם אחרי שנעשה הרקיע להבדיל כו' עדיין הכל הי' בבחי' העלם ולא בבחי' גלוי גמור עד שנתגלה היבש' שנק' ארץ וא' תוצא"],[1700400127,"הארץ נפש כו' וכמ\"ש הכל היו מן העפר דווקא וכמארז\"ל כל מה שבים יש ביבשה כו' כמבואר במ\"א באריכו' בענין עלמא דאתכסיי' שנק' ים ועלמ' דאתגליי' שנק' ארץ עד\"מ מו\"ד שבמח' הכל בהעלם עדיין ובדבור בא הכל בגלוי כי הדבור יוצא בבחי' נבדל לחוץ ובמח' עדיין נכלל בהעלם העצמות והנה בודאי כל פרטי הדבור בהכרח נמצאי' במח' תחלה והיינו התחלקו' צרופי אותיות של המח' הנק' עקבי לאה שנעשין מקור לדבור כידוע בענין ב' ההין דשם הוי' שע\"ז אמר תרין נוקבין פריש שלמה לאה ורחל והיינו ענין ד' רבתי שהוא בחי' דבור גדול שבמח' וזהו ענין מאמר הנ\"ל דמה שעשתה ענוה עקב לסוליתה ענוה הוא בחי' לאה עלמא דאתכסייא (דענוה הוא בחי' הבטול בעצמו בלי נרגשלדבר מה והיינו עניו דמשה בחי' מ\"ה דאבא וענוה הוא בבינה ותבונ' עד בחי' לאה) ועקבי לאה היינו מה שיש בחי' הביטול עצמי באותיות המח' (כנשמות הסבות שנק' נוני ימא רבא כדגים המובלעים בים וכן ת\"ח כו' בבחי' ביטול עצמי דחכ' משא\"כ המלאכים שמקבלים מרוח הבל הדבור שהן נפרדי' כחיות האדם מן האויר כו' וכמ\"ש במ\"א וגם נשמות דבריא' שנק' פני אדם ה\"ז כאדם שהוא בא באור וחיות נפרד משא\"כ נשמות הכלולים באותיות המח' שנק' ים שמתאחדי' בעצם המדות דז\"א כו' והיינו למסור נפשו באחד ד' רבתי דוקא ששם מקורה האמיתי כמו ר\"ע שיצאה נשמתו באחד דוקא ומ\"ש ואהבת כו' בכל נפשך היינו נשמות שבגופים דוק' וכמשי\"ת) ומ\"ש דעקב ענוה שבמח' יראת ה' עשתה עטרה לראשה היינו בחי' כתר מל' טרם שבא הדבור בגלוי רצון ושכל ומדות כנ\"ל בפי' לעולם ה' דברך נצב כו' שהוא נכלל בבחי' הרצון שלעצמו ממש במח' בהעלם רק שמזה נעשה הרצון לדבור כמו כשרוצה להביא המח' בגלוי הדבור נק' רצון של הדבור שלא נגל' עדיין וע\"ז אמר המלך המרומם כו' כנ\"ל והנה כאשר האדם רוצה להביא מחשבתו ורצונו שבלבו לגלוי הדבור והמעש' מוכרח שיפסיק ויצמצ' א\"ע מטרדת מחשבתו ורצון בפרטי החלקי' וכולם יתאספו ויתכווצו להיות מקום לדבור ומעשה (משא\"כ אם אינו חפץ להביא בגלוי הדבור כמו לבא לפומא לא גלי' וכמו צדיק ורשע לא קאמר וכה\"ג נשאר המח' הסתומה כלולה בעצמו ואינה באה לגלוי הדבור כלל וכמו וינחם ה' כו' וכה\"ג) ואמנם אחר שצמצם כל המח' כדי לדבר הרי אדרבה כל מה שבמח' רוצה לגלות בדבור לא יעלים דבר וחצי דבר רק שמתגלין באופן מהות אותיות הדבור והוא הידוע בענין אתוון אתגליפו כו' שאותיות המח' כציורן במח' בכל פרט באין בדבור ע\"ד דוגמא הנ\"ל מן המצייר בכתב כל אותיות מחשבתו שאות א' שבמח' בא בציור גשמי כך כל אות שבמח' עליונ' שנבראו ממנו עלמין סתימין (כמו ביו\"ד שבמח' נברא העוה\"ב ובה\"א שבדבור נברא העוה\"ז כמ\"ש בה\"א בראם כו') נברא ממנו בדבור עלמין דאתגליין כידוע וזהו ענין יקוו המים מתחת השמים מים הללו הן מ\"ת שלאחר הבדלת הרקיע ביום ב' והוא בחי' חכמה שבאותיו' המח' וכאשר רוצה להביא לגלוי הדבור מוכרח להתצמצם ולהתכווץ כדי שתראה היבשה שנק' עלמא דאתגלייא שהוא עולם הדבור ואם לא יתצמצמו לעולם לא יבא לגלוי הדבור הנק' יבשה והוא באמת עיקר סיבת התגלות כל מה שבמח' הסתומה הנק' ים בכל פרט ופרט כו' וכמארז\"ל כל שיש ביבשה יש בים כו' ולא יחסר דבר בים מכל חלקי דצח\"מ שביבשה כידוע רק שבים הן בהעלם וכמו כמים לים מכסי' וז\"ש יקוו בלשון קו כי הי' התפשטות המח' לעצמו טרם שיוכל לבא לבחי' המשכה מצומצמת לגילוי כאדם שטרוד במחשבתו לא יכול לצמצם א\"ע לדבר וע\"י שצמצם א\"ע להיות בבחי' קו אמר יקוו והיינו מ\"ש ברוך ה' כו' מן"],[1700400128,"העולם ועד העולם כו' מעולם המח' לעולם הדבור (ומ\"ש אל מקום א' א' דוקא וכמארז\"ל שגער בהן כו' היינו ענין כח התחברות דמח' בדבור והוא מ\"ש את השמי' כו' שהוא בחי' יסוד שמצמצם א\"ע כדי שיוכל להשפיע עד\"מ מהמשפיע שכל לתינוק שא\"א כ\"א שיצמצ' א\"ע מאוד ולא ישאר בו כ\"א כפי הנצרך לקבלת שפע התינוק לבד ונק' יו\"ד זעירא דויקרא והוא מ\"ש יקוו בווין עש שנתצמצמו רק בבחי' יוד זעירא שהוא אל מקום א' כמ\"ש בזוהר ואז ותראה היבשה נראה בבחי' יש ודבר מה והוא עולם הדבור שבא בהתגלות יש ודבר שלזה נק' הדבור דבר וכמו ודבר דבר כו' והוא בחי' דבר מלך שלטון שגוזר בדבור כו' ונק' מטרוניתא או אימא תתאה כידוע) וזהו שאמר בזוהר דמאמר זה דיקוו המים ביום הג' דווקא להיותו בקו האמצעי דת\"י כו' להיותו כמו בריח מחבר מן הקצה לקצה מן המח' הסתומה לבחינ' הגילוי דיבשה שבהכרח לומר בכל ממוצע שיש בו משניהם וכך מאמר זה מאחר שבכוחו להבי' העלם המים שבים העליון לבחי' קו למקום א' להיות גלוי יבשה יש בו מהעלם וגילוי יחד וזהו שארז\"ל דים דומה לרקיע המבדיל דוקא שיש בו בחי' מורכבת מעליון ותחתון כנ\"ל וד\"ל:\n(כב) <b>וזהו</b> מ\"ד שמי' וארץ כא' נבראו שזהו כמו ענין מאמר דיקוו המים ביום הג' שהוא בקו האמצעי שמחבר מן הקצה כו' כנ\"ל ואמנם יקוו המי' מתחת השמי' כו' ותראה היבשה מחבר הוא לשמי' ויבשה שכבר המה במציאותם אבל מ\"ש דשמי' וארץ כא' ממש נבראו ה\"ז מדבר בבחי' מקור עליון שלמעלה משרש שניהם דהיינו למעל' מבחי' ע\"ס דא\"י וע\"ס דאו\"ח ששם כלולים שניהם כא' ממש מבלי שימצא ראש וסוף לומר שמי' נבראו תחלה או ארץ תחלה אלא כמ\"ש קורא אני עליהם יעמדו יחדיו כו' ולכאורה מן המקראות דיהי רקיע ויקוו המים משמע שזה ביום ב' וזה ביום ג' הרי הרקיע שנק' שמי' ביום מוקדם ויבשה שנק' ארץ ביום ג' שלאחריו ואיך א' שכא' ממש נבראו וא\"א לומר כמ\"ש במ\"א שבהעל' המח' ארץ קדמה דסוף מעשה עלה במח' תחלה ובגלוי השמי' קדמו למעל' מהעלם וגלוי שניהם כא' כו' שהרי ב' מאמרו' הללו הם בגילוי הדיבור באו ובגילוי השמי' קדמו דא\"כ לא יובן מ\"ש בראשית ברא שהיא במח' בהעלם כנ\"ל וא' השמי' תחלה ועוד דמ\"ד ארץ קדמה היינו ממ\"ש ביום עשות ה' אלקי' ארץ ושמי' הרי מצד בחי' המעשה דווקא ארץ קדמה ולא מצד בחי' העלם המח' דאדרבה בהעלם המח' שמים קדמו כמ\"ש בראשית ברא כו' וד\"ל אך הנה באמת מ\"ש ארץ קדמה אינו רק מצד המעשה שבאה בגילוי דוקא וכמ\"ש כל אשר חפץ ה' עשה בפ\"מ דוקא וכנ\"ל דעיקר הרצון הוא במעשה ולא מעשה שהי' בהעלם במ\"ת שלא נק' מעשה בגילוי רק המח' שעלה בה המעשה דמח' למעשה נקראת ולא גופה של מעשה עצמה כו' ולהבין שרש הדברי' הנה יש להקדי' בשרש ענין ע\"ס דא\"י וע\"ס דא\"ח שע\"ז מדבר במזמור דהללו כו' מן השמי' כו' וכל העליוני' ואח\"כ הללו את ה' מן הארץ כו' וכל אשר בה עד מלכי ארץ כו' כי נשגב שמו שהוא בבחי' או\"ח דהנה מבואר למעלה בענין מאמר דיהי אור שביום הא' שהוא בבחי' א\"י הוא אור ההולך ונמשך מלמעלה למטה להאיר אור חסד מגבוה לנמוך וגם לאחר שהבדיל הרקיע ביום הב' שהוא מבחי' הגבורו' שהוא מבחי' א\"ח (ויש בו יתרון מעלה שנק' גבורה שבחסד לחדש הבריאה יש מאין שזהו יח\"ת שהוא למעלה מיח\"ע וזהו סוף מעשה עלה במ\"ת כנ\"ל בססי' י\"ח בקצרה) עכ\"ז האור חסד זה בוקע המסך ומאיר עד סוף העשי' דהיינו עד הגלגלי' ומזלו' הגשמי' וכל צבאם שיש בהן בחי' הביטול והשתחואה לומר"],[1700400129,"שירה ואעפ\"י שהמסך מבדיל בין יצי' לעשי' בוקע הארת אור אלקי במסך להיות בחי' הביטול בכל המלאכי' דעשי' (כענין הושיט אצבעו הקטנה ביניהן ושרפן כו') וזהו הללו את הוי' דוקא מן השמי' אעפ\"י ששם אלקי' מגן ונרתק כמ\"ש במ\"א בענין כ\"ו כל\"ח דחסדי' דא\"י דהוי' בכל עולם בוקע במסך וצמצום דשם אלקי' וז\"ש הודו לה' כו' עד הודו לאל השמי' כל\"ח כי חסד אל כו' והיינו השמי' ומלאכי' עליונים וכל כוכבי אור כו' עד שמי השמי' והמים אשר מעל השמי' יהללו את שם ה' כי הוא צוה כו' חק נתן כו' פי' חק נתן להיות שאעפ\"י שמאיר אורות החסדי' דהוי' דאצי' בע\"ס דבי\"ע עד מל' דעשי' שבט' גלגלים שמקבלי' מחיצוניות הכלים כו' כולם נמשכו ע\"פ מאמר קו המדה שבמאמר יהי אור שכולל כל קצבת אור וכלי בכל עולם בשיעור ומדה ולא יוסיף ולא יגרע ולכך אנו רואי' שלא יהי' תוס' וגרעון בצבא השמי' אלא הן עומדי' מוי\"ב בלי שינוי בתוס' וריבוי כלל וז\"ש חק נתן ולא יעבור על המדה לא להוסיף ולא לגרוע (ואעפ\"י שאמר יוצר משרתי' בכל יום כו' היינו מבחי' הברורי' כו' שבארץ שנק' חציר דגדל על אלף טורין ובהמה רבה שתת לון בגמיעא כו' כידוע) וגם מ\"ש מחדש בכל יום כו' מע\"ב אין זה חידוש מעיקרו רק לחד' את או' ושפע מציאות' באור ושפע חדש' ולא חדשה לגמרי רק כמו חידוש החיות באדם בכ\"י כו' כידוע אבל הנה בארץ אנו רואי' דבר חדש שיש בה כח התחדשות הבריאה בהתהוות מציאות חדשה ממש שלא הי' מעול' במציאו' כלל והוא מה שאנו רואי' בחי' הריבוי ותוס' שמתהווה בארץ בכל חלקי דצח\"ם שבה יש מהן ע\"י זריעה כמו הזורע חטה בארץ שיתהוו חטי' חדשי' לגמרי ברבוי ותוס' והחטה הזרוע תרקב תחלה והי' לאין ועוד גם בלא זריעה תצמיח הארץ עשבי' ואלנות הרבה וגם הדומם הנמצא בה יתוסף ברבוי והתפשטו' חדשי' וגם חלקי המי' שבה יתהוו שם בתוס' וריבוי הנק' מ\"ח שנובעי' בארץ עד אין שיעו' וגם יסו' הרוח ואש שבה יבואו שם בארץ דוק' בריבוי ותוס' עד אין שיעו' כמו כח הצמיח' שבה שהוא מיסוד הרוח שבארץ וכמ\"ש במ\"א בענין מעלה נשיאים מקצה הארץ דהרוח שבארץ נק' זיקא דמקמי מיטרא שמעל' הענן כי אדי' העולים מן הארץ שנעשה מזה העבי' המה מחלקי יסוד המי' ואש ורוח שבארץ ויסוד האש שבהן הן הברקי' שבמטר והמטר עצמו מחלקי יסוד המי' ובחי' יסוד הרוח כוללם יחד והוא מ\"ש מוציא רוח כו' והוא זיקא דמקמי מיטרא כי ברוח מורכב כח העלא' והמשכ' ויריד' כמו מוריד הגשם ואמ\"ר זה דענן מן הארץ בא וחוזר ונמשך בארץ ללחלח היבשות ולהוציא צמחה כמ\"ש והרווה את הארץ והוליד' והצמיחה) וצמיחה זו ברבוי והתחדשות לאין שיעור ואם הי' אמ\"ר זה מאש ומי' ורוח שבאין מלמעל' אין בהן כל חדש לחדש התהוו' עד אין שיעו' שהרי אמ\"ר הרוחני מוגבל במדה ולא ימצא בהן רבוי ותוס' כלל מכמו שהן בעצם רק מפני שהעבי' והמטר מאדי הארץ באים ששם הכח של חידוש התהוות ואעפ\"כ אם לא הי' בוקע ועולה בבחי' א\"ח לא הי' אמ\"ר שבארץ מצמיח מאומה (אעפ\"י שכמ' מיני דומם וצומח הטמוני' בעפר יתהוו שם בריבוי גדול ע\"י יסוד המי' ורוח שבארץ עצמם וגם כמה מיני מתכת מיסוד האש (לפי שכמו בים מתהווי' חלקי דצח\"מ כך ביבשה מתהוים מכח עצמם) רק הפרי אילנות ותבואות יצטרכו לגשם מן השמי' ושיהיה נעשה מאדי הארץ דוק') והנה לכאור' מה שיש כח התחדשו' זו בארץ משא\"כ בשמי' וכל צבאם לפלא יחשב אם זהו מצד יסוד העפר שבארץ כמ\"ש הכל הי' מן העפר דוקא או מצד יסוד המי' שבה דוקא לפי שבטבע יסוד המים לעשות ההתפשטות ורבוי ולכאורה דוקא מצד יסוד הלחלוחי' שבה שהרי ארץ יבשה כמדבר לא"],[1700400130,"תצמיח כלום וכידוע דארעא חלחולי מחלחלא כו' דהיינו שהמי' הנקווי' למטה מן הארץ מששת ימי בראשית במאמר יקוו כו' וכמ\"ש לרוקע הארץ על המי' כו' וכידוע שגער בהן בנזיפה וירדו למט' כו' חוזרי' ועולי' ובוקעי' מתחת לארץ ונכנסי' בעובי כדור הארץ וארעא חלחולי מחלחלא כו' ונבקעת הארץ בגידי' שבה ממי התהום (וע\"ד שאמר נבקעו כל מעינו' תהו' רבה יתר מכפי המדה כו') ואם לזה יקראו בשם מי' חיים הדרא קושי' לדוכתה שהרי המי' הללו מ\"ע היו תחלה רק עפ\"י מאמר יקוו המים ירדו למטה ואיך יש בכח' לחדש המציאות דצ\"ח בארץ אלא מוכרח לומר שלט מצד המי' שבארץ הבאי' מלמטה יתחדש שם המציאו' אלא דוקא מיסוד העפר שבה וכמ\"ש הכל הי' מן העפר דווקא וכאשר מורכב בעפר מי' ורוח ואש יבא גם בהן חידוש ולזאת גם מים עליוני' הללו בעברם בארץ מלמטה למעלה נמתקו ממרירות שלהם ונתהוו כחדשות מעיקרם ונק' מים חיים ואז הם מתהווי' ונובעי' עד אין שיעור למעלה באין שיעור והפסק ואין זה מצד התהום שאין לא הפסק אלא מצד העפר שבארץ שיש בו כח המחדש התהוות מציאות מים חדשי' שלא הי' בתהום כלל וכמ\"ש במ\"א אך הנה עדיין י\"ל דאם הי' רק סיבת הצמיחה מן הארץ רק מיסוד העפר שבו (ומה שבמדבר לא יצמיח זהו האש השורף הלחלוחי' ואש מכווץ ועושה העדר לצמיחה שבעפר כי גם העפר מורכב בו בלחלוחי' ולא לחלוחי' לבד אלא שמנונית וכמ\"ש משמני הארץ ורמו ושמן מחלמיש צור וכמ\"ש במ\"א ואעפ\"י שהחום מוליד כשמי\"ת אבל לא אש השורף ומכלה כמו במדבר) א\"כ יש פליאה גדולה ממה שאנו רואי' בגדרי הטבע דודאי הארץ תוציא צמחה מכח הצומח שבה דוקא ומ\"ש בגשם והרוה את הארץ והולידה אינו אלא סיבה שתוציא צמחה כו' אבל הרי אמרו דאין לך עשב מלמטה שאין לו מזל כו' והמזלו' קבועי' ברקיע כידוע דהארץ אינו רק כמו גרגיר חרדל לגבי כדור השמי' הסובב עליו וכל המזלות הקבועי' בה משפיעי' המה לכל חלקי אקלימי הארץ בכל פרט שבה וכמ\"ש אני אענה את השמי' תחלה ואח\"כ הם יענו את הארץ כו' וכמ\"ש ביאור זה במ\"א ואיך יתכן שיהיה בארץ שני כחות משפיעי' גשמי' שהמה מרווים את הארץ והולידה והצמיחה וגם המזלות כמו וממגד תבואות שמש וממגד כו' שהשמש זורח על הארץ ומגדלת תבואות ונק' תבואות שמש דוקא ומזלות פרטיי' שמגדלי' כל צמח בפרט כמו שא' אין לך עשב בפרט שאין לו מזל מיוחד אליו כו' ועוד שהב' כוחות הללו הן בו הפכי' מן הקצה לקצה שהרי הגשמי' הן מבחי' מי חסדי' היורדי' מגבוה כו' שהמים הן בבחי' קרירות ולחלוחית שבמי' הם בבחי' התפשטות כטבע המים כו' והשמש והמזלות שמאירי' הן מתפשטים בחום דוקא וראי' לדבר שבמקו' שהחום של השמש לא יגיע שם לא יצמיח שם בכי טוב לפי שכל חום מוליד יש מאין (וכמו ??? המ\"ד שבחום מוליד חדשות ובלא חום אינו מוליד וכתולעת המשי שמתהווה ע\"י החום דווקא) וכמ\"ש עוד כל ימי הארץ קיץ כו' קור וחום כו' ואם החום דוקא מוליד הקור לא יוליד וכמו שאנו רואים שכל גידול תבואות בחלק שבדרום שהחום של השמש שם ולא בצפון בריחוק ששם הקור כו' (רק בקרוב לקו השוה החום שורף ומכלה וכמו המדבר וכה\"ג) ועוד שהרי הארץ מצד עצמה א\"צ כלל לשום קבלת שפע להיות שיש בכח עצמה להוליד ולהצמיח הכל כמ\"ש כי כארץ תוציא צמחה כו' והגשמיי' אינו אלא לרוות חלקי הארץ אבל גוף הצמיחה מיסוד העפר שבה דווקא מורכב מיסוד המי' ולחלוחי' עצמה וכמו\"כ הגשמי' נעשי' מאדים העולין"],[1700400131,"מן הארץ דווקא ואיך יתלה הצמיחה שבה בחום השמש או במזל המכה ואומר לו גדל כו' או בגשמי' וכה\"ג שכל זה סותר למ\"ש הכל הי' מן העפר בעצמו וראי' לזה מוי\"ב שא' תדשא הארץ כו' תוצא הארץ כו' והרי אז לא הי' אדם עדיין לעבוד את האדמה בחרישה וזריעה והשקאת מי גשמי' וגם עדיין לא הי' שמש ברקיע השמי' עד יום ד' שא' יהי מארת ברקיע כו' ומאמר תדשא הארץ כו' ביום ג' הי' כידוע וכתיב ותוצא הארץ דשא עשב מזריע זרע כו' ועץ עושה פרי כו' ולא הי' מזל המגדל ולא גשמי' רק מכח הארץ עצמה דווקא וכמ\"ש בזהר דארץ אפיקת ועבידת כו' אלא מוכרח לומר שהכל הי' מן העפ' מצד עצמה ואעפי\"כ המזל מגדל וע\"י גשמי' כו' ושניה' אמת וד\"ל:\n(כג) <b>ולהבין</b> זה הנה שרש הדברי' יובן עפ\"י המבואר במ\"א בפי' דור לדו' ישב' כו' בענין הפסוק דור הולך כו' והארץ לעולם עומדת דמה שיש בארץ כח המהווה מציאות חדשו' מאין ליש אשר אין ביסודו' העליוני' דאמ\"ר שלמעל' ממנה הוא לפי שנעוץ תחלתן בסופן דוקא וזה הכח המהוו' מאין ליש בלי הפסק (כמו כח המוליד באדם שאין זה רק מכח אלקי כמשי\"ת) הוא מבחי' כחו של אא\"ס שבתחלה כי הארץ סוף הכל שאין עוד למטה הימנה לכך נמצא בה כח התחלה ועד\"מ מהילוך המי' ממחצב המעיין מגובה ההר שבסוף דוקא כאשר אין עוד מקום להתפשטותם יחזרו בכח לעלות למעלה וכח זה שעולה למעל' אינו רק עד מקור הראשון והוא מכח הסוף שבא בהיפך מטבע המים שיורדי' מגבוה לנמוך וה\"ז כמכה באבן בכח בכותל שאותו הכח עצמו חוזר אליו ואמנ' אין זה יתרון לכאורה אבל באמת נמצא יתרון כח בכח זה החוזר למעלה יותר מכח הנמשך וכנראה בחוש בכמ' דברים וכ\"ז אינו רק דוגמא לד\"ז למה שנמצא כח הצמיח' בארץ ברבוי והתפשטות הרבה יותר מכפי הקצוב במדה בהוספת כח העולה וחוזר הנ\"ל כי הצמיחה וריבוי בלי שיעו' מוגבל כלל וכלל כידוע וא\"כ אין למצוא דוגמ' לזה רק מענין כח התולד' שבנקבה דכתיב אשה כי תזריע וילדה כו' ודאי שכח המוליד ממ\"ן שלה דוקא וראי' לזה מסוף דבר דגם אחר שקבל' טפת המ\"ד לא היה נמצא ולד שלם ברמ\"ח אברים כו' וצפרני' ושערו' שכ\"ז אינו רק מכח הנוק' שבבטן האם דוקא נגדל ונצמח מעצמו בריבוי והתפשטות זאת בכל פרטי חלקיו בלי סיוע לזה ממ\"ד כלל ואדרבה המ\"ד נסרח והיה כלא היה כמו חטה הזרועה בארץ שננרקבת והיה לאין ממש בקליטתו בארץ ואם לאו אין צמיחה כלל כך הטפ' הנקלטת תקלט ותבטל ואז דווק' מ\"ן שלה תצמיח הולד ברבוי התפשטות בציור רמ\"ח אברי' כו' וכמו אילן עושה פירות שהגידול מלחלוחי' השרשי' שע\"פ המי' (ובל' קבלה נק' ה\"ח המגדילי' הולד בבטן אמו כ\"ז שהייתו והיינו ממה שאוכלת כו') ואמנם בלא טיפת המ\"ד לא הי' כח התולדה שבה עושה מאומה ומובן מזה שזריעות המ\"ד שנק' מי החסדי' אינו כמו המים שמגדלי' מכח הארץ שזהו בחי' מ\"ן דווקא כענין אשה כי תזריע כו' אלא הוא כמי הגשמי' ובתנאי שהאשה תעלה מ\"ן לקבל כענין אין טיפה יורדת מלמעלה שאין טיפי' עולין כנגדה שזה רמז להעלא' מ\"ן בכפליי' דמ\"ד שאז הטפה תקלט וכמ\"ש נקבה תסובב כו' (וכמ\"ש במ\"א בביאור המא' דוהתקדשתם אלו מ\"ר בחי' מ\"ד והייתם קדושי' בחי' מ\"ן כו' כי קדוש אני באמצעיתא דאיש ואשה שכינה ביניהם כו' שהוא כח התולדה לאין שיעור שנמצא באמצעות חיבור ויחוד זה דמ\"ד ומ\"ן היינו כי קדוש אני שיש בזה כח האלקי ולכך נמשך לאין שיעור ונק' ברכת פרי הבטן שהוא בא ע\"י כח האלקי כמו שאנו רואי' שלא יועיל כל"],[1700400132,"יחוד דכר ונוקבא להוליד בלתי סיוע כח אלקי שיברך אותם כמ\"ש ויברך אותם כו' ויאמר פרו ורבו כו' ובל' רז\"ל היינו ענין ג' שותפין אב ואם כו' והנה הלובן שמן האב עצמו' ואודם שמן האם בשר כו' ע\"ז אמר עור ובש' תלבישני מאוד' של אם וכגבינה תקפיאני מן הלובן כו' וכמ\"ש במ\"א ביאו' זה ואין זה סתיר' לענין הנ\"ל דעיקר התולדה מהנוק' כי גם מה שלובן דאב נעש' עצמות זהו ממ\"ן דנו\"ק כידוע במשל המחבץ או כמו הקיבה בחלב שז\"ש כגבינה כו' ולכך א' מי' אמצעים בין גבינה לבשר כו' וד\"ל (ואין מכ\"ז דמיון לגשמי' בארץ רק למזל המכה ואומ' לו גדל יש לו דמיון מעט כמשי\"ת) ונמצא דדוגמא דדכר ונוק' הוא ענין גשמי' בארץ כי ע\"י השקא' מי' נק' בית הבעל כמו כי יבעל בחור כו' כמ\"ש ברי' מס' מ\"ק ואמנם הגשמי' באין מן העבי' מאדי הארץ ועכ\"ז הן מועילין להוציא כח התולדה שבארץ ודוקא בצירוף הרוחנית דכח המזלות שברקיע כמ\"ש אני אענה את השמים כו' וכמ\"ש גשם נדבות תניף ונק' גשמי ברכה להוליד ולהצמיח כו' וכמ\"ש מוריד הגשם ודוקא משום דאני אענה את השמים תחלה והם כו' והענין הוא כידוע דמזל המכה ואומ' לו גדל אין עצם הגידול מן המזל רק שאומר לו גדל והוא כח רוחני המסייע לכח הצומח שבארץ להיו' בו חום המוליד [כדמיון מ\"ד דכלול מיסוד הרוח דוקא כי רוח יזרעו ולכך יוליד בדומה לו ונמצא עיקר כח המוליד בדכר דוקא שהרי אם אינו יורה כחץ אינו מוליד לפי שכל חום מוליד רק שהתולדה עצמה ממ\"ן דנוק' וכמ\"ש אשה כי תזריע וילדה שהוא עצם התולדה כמו בארץ דכתיב בה והולידה והצמיחה מטעם שעצם התוס' ורבוי המחודש מכח הנוק' בא רק שהוא בא מצד כח הדכר שיש בו כח המוליד דוקא וסריס אינו מוליד הגם שיזרע זרעו כי רוח המוליד חסר לו ונמצא יובן מזה במ\"ש אני אענ' את השמים כו' שזהו ג\"כ ע\"ד דמיון זה ושניהם אמת ולכך נק' תבואת שמש דוקא וכה\"ג ועכ\"ז העיקר בגשמי' תלוי והוא בזיקא דמקמי מיטרא וזיקא דבתר מיטרא (כמ\"ש במ\"א בביאור דעולת תמיד כו') ודרך כלל ג' אלה בני חיי ומזוני במזל תלי' דמזל מעשיר כו' וכמ\"ש בר\"א בן פדת ואי בעית דאיהפכת לעולם המזלות ואז איפשר איברת בשעתא דמזוני לפי אופן קביעת המזלות נגד הארץ כענין ז' שני הרעב כו' כמ\"ש אני אענה כו' כי מסד' הכוכבי' במשמרותיה' כרצונו דווקא) ובכ\"ז מובן ענין הנ\"ל בארץ דגם שהעיקר של התוס' ורבוי בא מכח עצמה לפי שבסוף הכל נמצ' כח התחלה ויותר מזה והוא מה שמחדש מאין בלי הפסק מ\"מ צריכה לקבלת שפע לעתות בה התולדה (ולפ\"ז מ\"ש תדשא הארץ ועדיין לא הוו גשמי' אעפ\"י שרקיע כבר הי' מיום ב' רק שע\"פ מאמ' נעשה בהכח זה דווק' והוא ע\"פ מאמר זה דתדשא הארץ ותוצא הארץ כו' כמ\"ש במ\"א וד\"ל] אך אם כן לכאורה אינו מובן מה שהארץ תצמיח על ידי מי התהום שבוקעין בה כנ\"ל ואמנם אין עיקר התולדה ורבוי מהם רק מיסוד העפר שבה והמי' הללו המה רק כמו בחי' מ\"נ דאשה כו' שעושין ההתפשטות כנראה בחוש שכל דבר יצמח וירבה התפשטותו ע\"י לחלוחי' המים אבל לא שיחדשו עצם המציאות מתחילת הווייתו רק ע\"ע כח שבעפר דווקא וכמ\"ש הכל הי' מן העפר כנ\"ל וד\"ל (ולפ\"ז יובן ההפרש בין מ\"ע או באור הזרוע למעל' שאין בהם החידוש לחדש דבר מעיקרו למ\"ת שעוברי' בארץ שעושין החידוש מאין כו' שאין כ\"ז רק ענין ההפרש בין ב' מיני שפע בין עו\"ע שנק' יש מיש ליש מאין כידוע שבחי' עו\"ע ה\"ז כעשיר שמשפיע לעני וכרב לתלמיד שאין זה מאין ליש אלא יש מיש דמה שהי' כבר במציאות יש במשפיע נתקבל כיין בכוס ולעני לית לי' מגרמי' כלום רק מה שקיבל ככוס שקיבל היין וכן"],[1700400133,"התלמיד שקיבל השכל ולזאת לא ימצא בזה חידוש שפע מאין זולת דבר כהויתו לא יוסיף ולא יגרע לעולם והיינו דמיון לאור ושפע דמ\"ע ואור עליון דיחו\"ע כו' אבל המשכה מאין ליש אין זה רק כמו זיווג זכר ונקבה שהן ב' מהותי' ואין מהות המקבל נצרך למהות המשפיע והקבלה דמקבל אינו גוף השפע שהרי גוף המחודש מכח המקבל עצמו בא כנ\"ל בענין אשה כי תזריע כו' רק שניתן לה כח המוליד שבמ\"ד ובאמצעות כח שניהם במ\"ד ומ\"ן יבא דבר המחודש הזה מאין ליש ממש שהוא בסיוע כח האלקי שמכחו יולידו באמצעות שניהם לאין שיעור כו' וכן כח הצמיחה שבארץ כשמקבלת מגשמי' ומזלות שברקיע וכה\"ג יש בשמש ולבנה למאן דמפרש בזוהר סיהרא לית ליה מגרמה כלום היינו כח התולדה שיש בה כי ההשפעה עצמה מן הלבנה ולא שליח לה מג\"כ כעני לגבי עשיר וכתלמיד מרבו ואם אמרו פני משה כפני חמה כו' הרי יהושע הי' איש אשר רוח בו להוליד רוח חדש לגמרי וכידוע בענין תושבע\"פ ותושב\"כ דבינה יתיר' נתנה באשה כו' שהרי ימצאו דינין מחודשי' בתושבע\"פ שלא יש להם רמז בתושב\"כ כלל וכענין לאו דלא תסו' וראי' מאתם אפי' מוטעין וכמ\"ש במ\"א שהרי זה כולד בבטן אמו שנגדל ממ\"ן שלה דוקא כנ\"ל וזהו יהי רקיע בתוך המים להבדיל בין מ\"ע דאורייתא מח\"ע נפקת היינו תושב\"כ שנק' מה\"ח שלמעלה מעה\"ד כו' ובין מ\"ת שבחכמ' דתושבע\"פ ת\"ת אתברירו רפ\"ח כו' בעה\"ד טו\"ר וידוע בפי' ואהי' אצלו אמון כו' דדוקא באוריית' בראעלמא וכמארז\"ל א\"ת בניך אלא בוניך כו' וכמ\"ש ואשי' דברי בפיך כו' וידוע בענין י' מאמרות שהן לנגד יו\"ד הדברות ממש כחומר וצורה בכל פרט כו' והנה לכאור' זה סותר לענין הפסוק דיהי רקיע להבדיל בין מ\"ע דתושב\"כ כו' ובהכרח נאמ' דתושבע\"פ מקבל מתושב\"כ מאחר שא' ואהי' אצלו אמון כו' באוריית' כו' כאומן הרואה בלוח כידוע וכמו אשמר בזהר ע\"פ חכמות בחוץ כו' ח\"ע דאתמשך בח\"ת כו' והענין הוא דשניהם אמת והיינו ע\"ד הנ\"ל במשל דזווג דכר ונוק' ובמשל הארץ שמקבלת מגשמי' ומזלות שברקיע כו' דהנה י\"ל לכאורה מ\"ש בל' המקובלים בכל היחודים עליונים דאו\"א וזו\"נ כו' הכל במשל דזווג דו\"נ דוקא ולא מצאו דמיון לזה משפע דעשיר ועני ורב לתלמי' וכה\"ג אלא הענין הוא משום דבחי' יחודי' עליוני' דאו\"א וזו\"נ לתולדות הנשמות כו' הוא בא מכחו של א\"ס עצמו והיינו כדמיון דכר ונוק' ולא כדמיון שפע העיל' לעלו' רק עצם האצילו' הע\"ס הוא בא בבחי' העל' וגילוי כידוע שזהו כמו מאמר יהי אור וכה\"ג יובן בהפרש שבין תושב\"כ לתושבע\"פ כו' בהיות דאורייתא תושב\"כ מח\"ע נפקת היינו כמאמר יהי אור אור קדמא' דחכמה שנא' ותורה אור וכמ\"ש ואהי' אצלו אמון כו' אלפים שנה קודם כו' והוא מארז\"ל בראשית בשביל התורה שנק' ראשית שנא' ה' קנני ראשית דרכו והאור הזה בא בגבול ומדה במאמ' קו המדה והן ע\"פ כ\"ב אתוון דאורייתא ובפרט ס\"ר אותיות דתושב\"כ בטנת\"א מדוקדק בחסר ויתיר כו' ונק' פני' מאירות ובתושבע\"פ מאיר האור במדה והן כל דרשות שתושבע\"פ מקבל מתושב\"כ וז\"ש חכמות בחוץ תרונה כו' ומה שבתושבע\"פ שנק' פנים מסבירות מחדש דינין הרבה בתוס' וריבוי לאין שיעור היינו מארז\"ל בינה יתירה ניתנת באשה כו' וכמו דמיון בחי' מ\"ן דנוק' שמגדל הולד בתוס' ורבוי וז\"ש א\"ח עטרת בעלה וכו' וכידוע בענין ויתן לך כו' מטל השמי' דהיינו תושב\"כ משמני הארץ תושב\"פ כו') ונק' לחם מן השמי' ולחם מן הארץ וכמ\"ש לכו לחמו בלחמי כו' וכמ\"ש במ\"א בענין ונתן לי לחם לאכול כו' כמו דגנך זה תלמוד כו' ולע\"ל או' שעתיד' הארץ שתוציא גלוסקאו' וכלי מילת לחם לאכול ובגד ללבוש"],[1700400134,"דתו\"מ שעכשיו בא בבחי' הברורי' דרפ\"ח כו' שמלובש בעה\"ד טו\"ר ולע\"ל אילנא דטו\"ר יתעבר כו' ויהי' א\"ח עט\"ב שלא תצטרך הארץ למשפיע דגשמי' ומזלות) וכעין שהי' בוי\"ב דכתיב תוצא הארץ כו' רק שלע\"ל יהיה הלחם והלבוש בתכלית הבירור כו') ולכך הלכות דוקא לא יבטלו לע\"ל כמ\"ש במ\"א בפי' מזמור לתודה הריעו לה' כו' ר\"ת הלכ' כו' וד\"ל (ונמצ' ג' מדרגות יש בענין יהי רקיע בתוך המים א' להבדיל בין מ\"ע ומ\"ת בחכמ' שבמע\"ב עצמי כנ\"ל במח' העצמית שצריך לבא בגילוי כנ\"ל והב' בענין מי' דאורייתא דתושב\"כ ושבע\"פ כנ\"ל והג' בענין תולדות הנשמות מיחודי' עליונים דאו\"א וזו\"נ כו' דמ\"ע היינו בחי' מ\"ד דשרשו ממוח אבא כי אתה אבינו (וכתיב המקרה במי' כו' דגרמין בניין על מוחא כו' דלובן מן האב כו') והזריעה דמ\"ד דז\"א נק' אור זרוע לצדיק עליון בחי' יסוד ז\"א ובהגיע המ\"ד במ\"ל נשתהא ונקלט בבטן המל' ט\"ח כמ\"ש אליהו חי ה' אשר עמדתי כו' ונק' אוצר ששמו גוף כו' ומשם נמשכו נשמות דבי\"ע שא\"ז אמר אתה בראת כו' יצרת כו' כמ\"ש יצרתיו אף עשיתיו כו' עד בחי' נפש דעשי' שמלובש בחומ' גופני שזהו כזריעה בעפר הארץ ממש שיש בזה יתרון ותוס' רב הרבה יותר מאור הזרוע לצדיק כו' טרם שנמשך במל' מטעם הנ\"ל ביתרון מעלת הארץ במ\"ת שבה וכמשי\"ת בסי' שאח\"ז באריכות וד\"ל:\n(כד) <b>ואחכ\"ז</b> יובן ענין מעלה יתירה שיש ביח\"ת דבשכמל\"ו על יח\"ע דפסוק ראשון (הנז' בסי' י\"ז) מכמה ראיות וכללותם הן שלשה ענינים שאנו רואים בהם מעלה יתירה זו כנ\"ל הא' במע\"ב שיש בארץ כח המחדש חדשות מעיקרן מאין לאין שיעור כמו התולדה דנוק' כו' ולמעלה ברוחניות היינו שם ה' ואלקים שנק' שמים וארץ עילאין שיש באלקים כח זה דא\"ס שבתחלה ברבוי יותר והוא שם אד' דגדול אדונינו ורב כח כו' ומ\"ש אימתי גדול בעיר אלקינו וכמ\"ש בס\"י מכאן ואילך צא וחשוב לאין שיעור כו' מפני שאא\"ס למעלה עד אין קץ כו' בהיפך מדלעיל שם שלמטה עד אין כו' הוא ביח\"ת אלא אדרבה זהו ביח\"ע בבחי' או\"י נק' למטה עד כו' וביח\"ת דמל' שנק' ארץ ה\"ז בא בבחי' א\"ח שזהו למעלה עד אין כו') וזהו מ\"ש בזוהר למנדע ליה לקודב\"ה משבח פעולותיו יש מאין לאין שיעור שזהו דוק' מגיע בעצם מהותו יותר מטע' כל הנ\"ל וזהו שא' אתה הראת לדעת בגוף דוק' וכמשי\"ת) והב' בענין תושב\"כ ותשבע\"פ כנ\"ל והג' בענין הנשמות שמקור חוצבן למעלה באור זרוע לצדיק כו' ושרשן בחי' תוס' חידוש המוחין דאו\"א [ונשמות הסבות נבדל בערך במה שהן כלולין למעלה בימא רבא דח\"ע כדגים בים כנ\"ל) בזו\"נ לצורך תולדה שהוא מבחי' ג\"ר דוקא שלזה או' שמע ישראל דוקא שעלה במח' כו' (וכמ\"ש במ\"א בענין אל עליון גומל כו' ומביא גואל לב\"ב כו' וכמשי\"ת) ונשמות שבגופי' הן כדמיון הזריעה שבארץ וכמ\"ש אור זרוע לצדיק וכתיב וזרעתי' לי בארץ וכלום אדם זורע קב כו' שעי\"ז שוקא נתוסף רבוי גדול לאין שיעור כו' ולכך בחי' אה\"ר דבכל מאודך אינו רק בנשמה שבגוף דווקא אשר לא הי' לה מדריגה זו בעודנה למעל' בבחי' מ\"ע מ\"ע דח\"ע כו' וביאור טעם הדברי' מובן מכל הנ\"ל ויש להקדי' תחל' ביאור הפסוק דאז ישיר כו' עלי באר ענו לה באר חפרוה שרי' כו' המבואר במ\"א שהן הנשמות שבאו בגופי' שנק' באר מ\"ת ונוזלי' מן לבנון כו' פי' עלי באר שעולין מלמטה למעלה בבחי' א\"ח דוקא והיינו אבר ר\"ת בידך אפקיד רוחי שזהו עליות הנשמו' שבגופי' כו' ונק' ג\"כ מ\"ת בוכי' אנן בעינן למהוי קדם מלכא כו' לע\"ל כתיב בבכי יבאו כו'"],[1700400135,"ולכאורה זה הפסוק סות' למ\"ש הלוך ילך ובכה נושא משך הזר' דמשמ' בשעת זריע' דוקא הוא בוכה שאינו יודע אם יצמח או ירקב אבל בשעת קצירה ישמח וכמ\"ש בא יבא ברנה דווקא נושא אלומותיו בקציר' וכמו\"כ זרעו לכם לצדקה וקצרו כו' שנשמו' ישראל בתו\"מ שעושין בעה\"ז נק' זריעה והקצירה הוא שפרי מעשיהם לע\"ל וא\"כ למה אמר בבכי יבואו כו' אך הנה כתיב ויבך יוסף על צווארי בנימין אחיו ובנימין בכה כו' וידוע בענין יוסף ובנימין שהן צ\"ע וצ\"ת וכמ\"ש במ\"א בענין שהם וישפה כו' וזהו שכל הנשמות שמבחי' צ\"ע נק' אור זרוע כו' ובהגיע האור במקבל היינו בחי' צד\"ת ומפני שהתקשרות המשפיע אל המקבל נק' רוחא דשבי' בגווה מזה עצמו נעשה התקשרות המקבל אל המשפיע דהיינו מה שאין האשה כורתת ברית אלא למי שעשאה כלי כמה שכתוב כי בועליך עושיך כו' וכמה שכתוב ואל אישך תשוקתך כו' וזהו ענין הבכי' דיוסף צדיק עליון על הנשמו' שבגופים שלא ידח ממנו נדח כו' וזהו ויבך יוסף והוא המשכת י\"ג מדות הרחמי' מן המשפיע לכללו' נשמו' ישראל שלמט' לעורר' בתשו\"ע ותשו\"ת לבלתי ידח כל זמן הגלו' כמו בכל ר\"ה ויוה\"כ כו' ובנימין בכה כו' היינו התעוררו' המקבל צד\"ת מצד רוחא דשביק בה מעלה מ\"ן וראי' לזה מן הידוע דכל מי שאינו בוכ' בעי\"ת אין נשמתו שלימה בשרש מקור חוצבה מאור הזרוע לצדיק עליון דאם היתה שלימה למעלה הי' נתעורר מי\"ג מדה\"ר דצד\"ע כו' וכמ\"ש ויבך יוסף וממילא ובנימין בכה כו' ומזה יובן ענין מ\"ת בוכין אנן בעינן כו' שזהו בחי' עליות הנשמות שירדו למטה ומצד נקודת התקשרותם מרוחא כו' לכך הן בוכין במר נפשם כו' לפי שרוצים לעלות למקור חוצבם מאור הזרוע למעלה כו' וזהו קדם מלכא דוקא וכדוגמ' שא' אשר עמדתי לפניו כו' וכידוע דכל נר ה' נשמת אדם הי' בבחי' אור העליון דאצי' שנמשך מצד\"ע ונק' נהורא חוורא ובירידת' למט' נק' נהור' אוכמ' כו' וז\"ש בהלו נרו עלי ראשי וכן כי את' תאיר נרי וכה\"ג דהיינו מ\"ש אך בצלם כו' דמזלי' דבוק למעלה ומאיר מלמעלה למטה ומזה בא כח המעלה מ\"ן בתש\"ת ולכך כל שאינו בוכה בעי\"ת מסתמא מזלי' אינו פועל בו כלום לפי שנפסק חבל התקשרותו או מחיצת עונו מבדיל כו' אך הנה עדיין י\"ל למה נק' בשם מים דוק' ונק' באר מ\"ח כו' דמשמ' שיש בהן יתרון מעל' משרש הנשמו' כמו שהיו תחלה באור עליון דצ\"ע כו' וכידוע דרך כלל שיריד' זו של הנשמה בגוף לצורך עליי' היא וכמשל הזריעה שעושה תוס' וריבוי דכלום אדם זורע קב כו' כנ\"ל וכך גם באור הזרוע לצדיק עליון יש בזריעה זו למטה במה שא' בראתיו יצרתיו אף עשיתיו כנ\"ל תוס' מעל' יתירה (וכן לפי מארז\"ל ע\"פ אחור וקדם צרתני קדם למע\"ב בגוף וחומר) והענין יובן עפ\"י הנ\"ל מ\"ע ומ\"ת שיש יתרון מעלה במ\"ת לאחר שגער עליהן שירדו למטה במאמר דיקוו המים כו' שנעשי' מחודשי' ממש בעברם בחללי הארץ מלמטה למעל' דוקא והן הנק' מ\"ת משא\"כ בעודנם למעלה לא נק' מ\"ת כלל והטעם הוא מצד כח החידוש מאין ממש אשר בעפר הארץ דוקא כנ\"ל באורך ולכך טבע המ\"ת הללו לעלות מלמטה למעלה בתגבורת גדולה כמו מרוצת המי' מלמעל' מגבוה לנמוך כידוע בנביעת הבאר מ\"ת כו' והיינו ג\"כ בנשמות שנזרעי' בחומר גופני שנק' עפר וכמ\"ש וייצר ה' אלהי' את האדם עפר כו' שיסודו מעפר דווקא ובעפר יש כח הראשון ממש ביתר שאת כנ\"ל (בר\"ס כ\"ג) ולא ככח החוזר אליו בלבד כו' (וזהו הטעם שהתולדה והצמיחה ברבוי לאין שיעור אינו אלא בנשמות הזרועי' בגופי' ושיולידו ויצמיחו נשמות לדורי דורות וכמו ע' נפש דיעקב כשבאו נעשו ס' רבוא"],[1700400136,"משא\"כ בזיווג נשמות למעלה לא יהי' בהו תולדה כזאת רק כמו מ\"ש ואת הנפש אשר עשו כו' למעלה ביחודים שזה הי' מצד התלבשות נשמותיהם בגופי' דוקא וגם למעלה באצילות עצמי יש הפרש זה בין זווג גופני דזו\"נ להוליד נשמות לזווג רוחני דאו\"א כידוע) וזהו פי' הפסוק דעלי באר ענו לה כו' שהן עליות הנשמות שבאו בבחי' ירידה למטה שהן נק' מ\"ת שירדו ממ\"ע כמו מאיגרא רמא לבירא עמיקתא מעומק רום לעומק תחת ממש וירידה עצומה כזאת עלייה גדולה להן כמ\"ש עלי באר והוא בארה של מרים שעולין הנשמות מצד התקשרות רוחני דשביק כו' בחי' צד\"ת להיות שיש בהן יתרון מעלה הרבה במה שהיו בעפר הארץ ונק' מים חיי' כנ\"ל ואמנם עדיין אינו מובן למה נק' מי בוכין אשר שעולין למעלה מעלה בבחי' או\"ח דווקא שהוא בתגבורת גדולה יותר משהן במקור חוצבם ועוד מ\"ש אנן בעינן למהוי קדם מלכא לבד אין זה רק שיעלו למקור חוצבם הראשון בלבד כמו שהיו טרם ירידתן למטה (וכמו הביטו אל צור חוצבתם ואין צור כאלהינו כו' שהיא שרש הציור של הנשמות טרם בואן לאוצר ששמו גוף כו' (ולא למעלה יותר מזה כו' אך הנה יש להקדי' בשרש ענין הזריע' שאנו רואי' שא\"א בשום אופן שיהי' צמיח' בתוס' רבוי כ\"א שיורקב החטה הזריעה לגמרי והיה כלא וכאין דהיינו ביטול כל גסותה וישותה וגם חיות רוחניות הצמיחה שבה יוכלל בכח הצומח שבארץ ומחמת זה דוקא שיהיה זה כמו בחי' העלאת מ\"ן בכח הצומח הרוחני אז יומשך ממנו כח להצמיח ריבוי חטי' וראיה לזה ממה שלא יצמח רק כעין מה שזורעין דוקא שלפי אופן ההעלאה כך ההמשכה (כמו המוליד שיוליד בדומ' להעלא' מ\"ן דנוק' כו' ובתנאי שיוקלט הטפה ויוכלל גם רוחניות שבה ברחם הנוק' כנ\"ל) וכמו\"כ יובן בנשמות עליונות דצד\"ע הנזרעים בחומר עפר הגוף כשאב ואם ממשיכי' נפש הטבעיו' בדם ובשר כו' ג\"כ יוקלט אור נשמ' זו בחומר הגוף ויכלה בה והיה כלא וכאין כמו קליט' חטה כו' והענין הוא מה שתחי' הנשמה חיי צער מפני חומר הגוף המחשיך וגורע אורה בתכלית בכל תאות עוה\"ז עד שנק' רקבון והי' כלא כו' וכענין נבלע ישראל בגוים כו' וכמו וכל חכמתם תתבלע כו' שהטוב נכלל לגמרי ברע דנוגה ולא נודע כו' ואמנם ה\"ז כמו הקליטה דחטה בארץ שתצמיח כך קליטת אור הזרוע זה יצמיח והוא במה שיתמרמר הנצוץ הזה ויבכה מצד ההיפוך ובכי' זו מגעת לעומק הענג האלקי יותר ממה שהי' עונג אלקי בתחלה באור זרוע זה וכנראה בחוש שכל העומק של אהבת עצמיות דאב לבנו לא תמצא רק בהפוך כמו בצרות נפשו דוקא כמו המו מעי לו כו' וכן מבן לאב והיינו אהבת בכל מאודך שבלתי מוגבלת שלמעלה מאהבת בכל נפשך דבכל נפשך היינו מצד אור הזרוע לצד\"ע הגם שהוא ודאי עצמיות וטבעיות כי משם לוקחה עכ\"ז אין ערוך כלל לגבי בכל מאדך כאשר תבכה במר נפשה בקליטתה בחומר גופני כנ\"ל לפי שיש כח בעפר הגוף שתחדש לכח הנשמה האלקית ביתר הרבה מכפי מדתה במקור חוצבה ע\"י מרירות זו ולכאורה הצער היפך הענג בא במשקל מכוון ממש כידוע בצער דנהר דינור שלפום צערא אגרא להנות מזיו ולא יותר ואנו רואי' בצער הגוף יגיע לעונג הבלתי מוגבל והיינו רק מטעם הנ\"ל שיש יתרון מעלה בחומר מבצורה כו' (והיינו דגחין ר\"ש ונשיק לעפרא על המאמר דגופא דלא סליק בי' נהורא דנשמתא מבטשין לי' וסליק כו' שע\"י ביטוש החומר דווקא יגיע תוס' עילוי לצורה דסוד עמוק הוא מי ימצאנו וכמ\"ש במ\"א בענין נוח לו כו') (ומ\"ש מי יודע עוז אפך כו' למנות ימינו כו' שמחנו כימות עניתנו שנות ראינו רעה כו' כצל ימינו עלי ארץ במרת נפש בגוף וישמחנו כימות כו' כי לפום צערא אגרא ומה שיש ברבוי גדול יותר מטעם"],[1700400137,"הנ\"ל ע\"ז א' יראה אל עבדיך כו' והדרך כו') וזהו הטעם שנק' מי בוכין דווקא כי בבכי' זאת יש עומק העונג מבקירובם בשרשם למעלה ומ\"ש קדם מלכא היינו למעלה משרשה הראשון במ\"ע כו' וזהו שא' בבכי יבואו דוקא כי בכי' זו למעלה מעונג העצמי שהי' ביום חתונתו ושמחת לבו ביחוד פב\"פ במ\"ת ובזמן בהמ\"ק זהו שא' יצאו מ\"ח כו' אל הים הקדמוני כו' (ובשנת ת\"ר לחיי נח גברו מעיינות תהום וגם ארובו' השמים כו' דמ\"ע ומ\"ת שוין וגם לע\"ל כתי' והי' אור הלבנה כאור החמה אבל מ\"ש א\"ח ע\"ב כו' היינו כמ\"ש ביוסף ברכות אביך כו') ומעתה יובן הכל דמ\"ש הלך ילך ובכה נושא משך הזרע היינו אור הזרוע לצד\"ע שבוכה על הספק פן ידח ממנו נדח ובכי' זו המשכת י\"ג מדה\"ר דויבך יוסף הנ\"ל ובא יבא ברכה לע\"ל שישא אלומותיו [כמ\"ש והנה קמה אלומתי כו' שהקציר' ברבוי גדול ורננה ברמשא דוקא לעת הערב לעת צאת השואבות כו' ומ\"ש בבכי יבואו היינו עליו' הנשמות שהיו בגלות זמן רב ועולין למעלה מעלה כנ\"ל וכמנם בכי' זאת באה מצד הקירוב מן הריחוק העצום שבזה יש עיקר עומק העונג וכמ\"ש רשפי' רשפי אש בשלהובא דרחימותא כמ\"ש הסבי עיניך מנגדי כו' והו' בזמן הגלו' דוקא שנק' באר מים חיים שחצי' אל כו' וזהו שבשכמל\"ו בזמן הגלו' יותר נעל' מבזמן בהמ\"ק כנ\"ל (בסי' י\"ז) ומ\"ש השבטים כשם כו' ולא יותר היינו דוקא בזמן בהמ\"ק שנא' ששם עלו שבטים ביחוד פב\"פ כו' וד\"ל:\n(כה) <b>והנה</b> ידוע שבאמרו בשכמל\"ו אז זמן קבלת מ\"ש דוקא כמו שום תשים עליך מלך בקבלת עול דוקא ולכאורה אין זה מובן דהלא מבואר למעלה דבשכמל\"ו שרשו יותר עליון מיח\"ע עד שיגיע באהבה דבכל מאדך אשר לא הי' זה ביכולת הנשמה גם בעודנה קשורה וכלולה בשרשה כמו למס\"נ באחד וא\"כ איך יתכן שבבשכמל\"ו אינו רק קבלת עול בלבד כו' אך הנה ידוע בענין דחילו ורחימו רחימו ודחילו שנעוץ תחלתן בסופן דהיינו בחי' דחילו עילאה בטול במציאות ממש תלוי בדחילו תתאה שהוא רק קבלת עול מ\"ש בלבד וזהו אם אין יראה אין חכמה כו' וכתיב הן יראת ה' היא חכמה וראשית חכמה יראת ה' כידוע ויש להבין הטעם למה יתלה תכלית היראה ובטול פנימי' ביראה וביטול חצוניות דקבלת עול לבד כו' והנה מבואר למעלה (בסי' י\"ז) במ\"ש אתה הראת לדעת וכו' הראת בחומר וגוף שירידה זו עליי' הוא כנ\"ל ומה יהי' הידיע' הרי אינו רק בפעולותיו שנפעל מכח שם אד' ואלקי' בלבד וכמ\"ש בזוהר כל ב\"נ דלא אשתדל למינדע לי' כו' וכן מ\"ש לכבודי בראתיו בגין דישתמודעין לי' הכל בבחי' כח האלקי הפועל בנבראי' כו' וז\"ש לדעת כי ה' הוא האלקי' דווקא ולא יותר (וכנ\"ל בסי' י\"ז) ואיך יכירו במהות ועצמו' יותר מענין פעולותיו שאינו רק בחי' התפשטות שלו ולא עצמותו כלל כמ\"ש הודו על ארץ כו' הוד וזיו שם מלכותו לבד כידוע אך הענין הוא כידוע דעיק' התהוו' כל עול' לפי ערכו אינו רק מבחי' מדת מל' דוקא כמ\"ש מלכותך מל' כ\"ע והוא מדות ההתנשאות כמ\"ש וישב ה' מלך כו' ה' מלך גאות לבש כו' וכידוע דמל' דאצילות נעשה ע\"י דבריאה ומל' דבריאה כו' עד מל' דעשי' שהוא כח שם א\"ד דעשי' להוות כל עולם העשי' מראשו לסופו עד ד\"י ודצ\"ח גשמיי' כידוע (בע\"ח בסופו) דט' גלגלים הגשמיים שרשם מקבלים מחיצוניות הכלי' דט\"ס דמל' דמל' דעשי' (מבחי' העיגולי' דעשי' ועיגולי א\"א מקיף רגלי היושר שהוא ג\"ע דעשי' בקו השוה כו' דבעיגולים העליון משובח מכולם כו') והיינו ענין קבלת מ\"ש בבשכמל\"ו דוקא לפי שעיקר בשכמל\"ו אינו רק בחי'"],[1700400138,"מדת המל' עד רום המעלות דהיינו עד בחי' מל' דא\"ס שלפני הקו כו' שעלה ברצונו הפשוט אנא אמלוך כו' ובכל עולם לפ\"ע עד רום המעלות בחי' קבלת עול מלכות של הנבראין שבאותו עולם ממשיכי' לבחי' מל' ע\"י ביטול והשתחוואה שלהם להיות מלך על עם כו' עד שגם בחי' מל' דמל' דעשי' נמשך ע\"י בחי' ביטול והשתחוואה גשמי' דט' גלגלים הגשמיי' בסיבובם ובלכתם התמידית שזהו ענין השתחוואה שלהם כמ\"ש וצבא השמים לך משתחווים (וכמ\"ש במ\"א בענין שמש בגבעון דום כו' שגלגל השמש בסיבובו אומר שירה וגז' עליו שיפסוק וידום מלומר שירה וממילא עמד וגם שנפש הגלגל פסק מלומר שיר שלו שזהו השתחוואה רוחניות אך ממילא עמד חומר הגלגל (כמו אדם המוד' בשכלו שבמוחו שכורע ראשו כו' וכידוע) ודוקא בשעת סיבובו כשמשתחוה כלפי שכינה שבמערב שזהו כח אלקי המהווה אותו אז יוכל להשפיע למטה דוקא וכמ\"ש אני אענה את השמי' והם יענו את הארץ ומבואר במ\"א באריכות דגם שהארץ כגרגיר חרדל לגבי כדור השמי' עכ\"ז המזלות הקבועי' ברקיע ומתגלגלי' סביב הארץ משפיעי' בבחי' קוין לכל חלקי כדור הארץ וכמאמר אין לך עשב שאין לו מזל המיוחד אליו המשפיע עליו ברוחניות ואומר לו גדל וכך ענין ממגד תבואות שמש וממגד גרש ירחי' כו' בכל חלקי דצח\"ם (וכמו מזל מחכים כו') וד\"י גשמי' וז\"ש והם יענו לשלוח אור שפעם בארץ בכל חלקי דצח\"ם בהשגח' פרטי' מאקלים לאקלי' בשינויי' רבי' מאוד וגם במקו' א' כמו חלקה א' תמטר כו' וכמ\"ש ומסדר את הכוכבי' במשמרותיה' כו' כרצונו ממש וסידור זה היינו סדר סיבוב הילוך הגלגלי' וכל צבא השמי' שבשעת סיבובם ובלכתם יאמרו שירה ולפי אופן סיבובם כן יהי' אופני שינויי השפע שלהם בארץ וז\"ש אני אענה את השמי' כו' שמזלות מקבלי' מבחי' אור האלקי ששורה באופנים ולא יסבו בלכתן עפ\"י מאמר האלקי כרצונו והם יענו את הארץ רק לפי אופן שמקבלי' אור שפע האלקי עליהם מלמעל' בשעת בחי' ביטול והשתחוא' שלהם דוק' וד\"ל) וכמו הזורק דבר בכח שבהכרח ילך מכח הזריק' בלתי נטי' ימין ושמאל רק כפי כח הזורק שמלובש בדבר הנזרק כך נק' כוכבי לכת כו') והנה בחי' השתחוואה דצבא השמים אינו רק קבלת עול בלבד באמרם שיר כמו הללוהו שמש וירח הללוהו כל כוכבי אור וכה\"ג הילול זה רק שמקבל מל' שמים באימ' ויראה גדול מאוד וכמ\"ש והחיות זעות מחיל כו' שכולם מקבלים עליהם עול מל' באימה (ולכך המלאכים חיים וקיימי' יותר מפני שנא' יראת ה' לחיים וכמ\"ש במ\"א) וקבלת עול הגם שאינו רק בטול חצוני לבד שהוא הכנעה חיצוניי' בחומ' שלו הרי מגיע בפנימי' הנפש והצורה יותר מבטול הפנימי שבצורה מצד עצמה שהרי מה שהנפש של הגלגל מתבטל הוא רק מצד השג' אלקי' המצומצמת עליו לבד שהוא בבחי' ראי' מקרוב לפי שעור כח אלקי המצומצם בו בערך שפע התהוותו יש מאין שמזה מתפעל בבטול ואוי\"ר דהיינו ממה שרואה ומשיג התהוות מציאותו מאלקי' חיים (וכמ\"ש במ\"א בענין קדוש וברוך דוי\"ו דקדוש היינו מה שנמשך כח התהוות חיותו מאין ליש ואין זה רק התפעלות מעצמו ממה שהוא חי מחיות אלקי ולא מעצמו' אלקו' שלמעלה מצמצום התהוות שלו כו') אבל מה שחומר הגלגל משתחווה השתחויות גשמי' אין זה רק קבלת עול הגם שהוא בהכנע' חצוניו' הרי הוא בטול כל מהותו ממש שמגיע לעצמו' אלקו' שלמעלה מצמצום האלקי שמהוה אותו מאין כו' ויובן שרש דבר זה בשרש בחי' המל' שהעיקר הוא הרצון ותענוג למלוכ' שנק' כתר מל' ועד\"מ כשמכתירין למלך יבאו השרים"],[1700400139,"והעם לקבלו למלך להשים כתר מל' בראשו ודאי אין זה רק לעשו' לו רצון למלוכ' שיקח כתר מל' כי אם לא ירצה ויתענג בזה לא יקח הכתר מל' כלל ובמה עושין לו רצון ותענוג שירצה ליקח המלוכה הנה יעשו לפניו ביטול וכבוד עצום וישתחוו לו ויאמרו לו קצין וראש תהי' עלינו ובראותו עוצם תשוקתם לזה עדיין לא יתפעל רק שיהי' לו רצון במלוכה אבל לאחר שישים הכתר מל' בראשו ברצון לפי אופן הרצון שיקבלוהו עליהם אז יתנשא בכתר מל' עליהם בהתנשאות שלמעל' מרצונם והוא שכל איש אשר לא יבוטל מכל עצמותו בנפשו ורכושו יומת וכך קבלוה עליה' בתחל' רק שבתחלה הי' זה ברצון ואח\"כ נעשה בטול הרצון בקבלת עול מלכות וכמשמעות פשט הכתוב שום תשים עליך מלך שישומו ברצון ואח\"כ קבלת עול שלא ברצון ואמנם קבלת עול זה שום תשים עליך ברצון בתחלה כו' והנה מבחי' ביטול הרצון לגמרי מנפש עד בשר יתפעל המלך יותר מתשוק' הרצון בקבלתם אותו בתחלה שהרי מזה נעשה מקור לרצון ועונג למלוכה וזהו כמי שמתענג המלך ממה שאמר ועושין רצונו בכל גזרותיו גזירת מלך שלא קיום הרצון בפרט עשה לו זה התענוג אלא רק מביטול העצמי שכל מה שיגזור אומר ונעשה רצונו ומזה יהי' מקור לרצון ועונג למלכותו בכללות וידוע דמקור כללי לכל מיני התפעלות רצון נק' כתר שבכתר והוא כתר עטרת המלך שבראשו בהתנשאות יתירה כו' וד\"ל והדוגמא יובן במלכותא דרקיע בכל בחי' מל' שבכל עולם בפרט עד מל' דמל' דעשיה על עולם העשי' שביטול עצמי בבחי' קבלת עול לבד כסיבוב הגלגלים וצבא השמים כנ\"ל מעוררים בחי' מקור הרצון והעונג למדת מלוכה זו שבבחי' מל' דמל' דעשיה להיות מלך על עם כו' מפני שמקבלים עול מל' באימה והכנעה חצוניות שהוא בטול כל המהות כו' והוא יותר גבוה מקבלת הרצון למלכותו ית' שמקבלי' בהשגה ותפיס' בכח אלקי שבנפש וצורה שלהם שרצון זה מצומצם לפ\"ע צמצום כח האלקי שבהם בלבד ואין זה מגיע לעורר בחי' מקור הרצון והענג שבמדה זו רק להיות לו רצון וכמו כתר יתנו לך מלאכי' שהוא כתר מל' וכמ\"ש בזהר ע\"פ גבורי כח עושי דברו כו' שעושין לכתר מל' והיינו כמשל רצון השרי' והעם לקבלו למלך אבל השתחוואה דצבא השמים מעוררי' לבחי' כתר שבכת' והוא במה שמתפעל מביטול העצמי במה שא' ונעשה רצונו בקבלת עול מלכותו דוקא וד\"ל ומזה יובן ענין הנ\"ל בד' מדרגות דחילו ורחימו כו' דיראה תתאה בקבלת עול שרש ומקור ליראה עילאה בטול הפנימי דחכמ' ורצון והוא במעש' המצות בקבלת עמ\"ש שמעוררי' נח\"ר לפני עצמותו שא' ונעשה רצונו והיינו נעוץ תחלתן בסופן דוק' וכמ\"ש סוף דבר כו' את האלקי' ירא כו' ביראה תתאה דקבלת עמ\"ש ותחלתן הוא מה שאמ' ונעש' רצונו שנח\"ר זה מקור הענג ורצון למלוכה ומזה נעשה ונברא העוה\"ב שכ\"י יש להם חלק שנאמ' ועמך כולם צדיקים ע\"י המצות דוקא דאפי' פושעי ישראל מלאים מצות כרימון והעה\"ב הוא עולם התענוג מעצמות התענוג הפשוט לנשמות הצדיקי' כמ\"ש ואמר ביום ההוא הנה אלקינו זה לנוכח כי' והג\"ע דעכשיו אינו רק בחי' ממוצע בין הענג שברצון וחכמ' שבמע\"ב באבי\"ע לענג העצמי שבעה\"ב כמו זיו השכינ' בג\"ע דעשי' ברצון וחו\"ב דמל' דעשי' מקור לענג שברצון וחו\"ב דמל' המהווה עולם העשי' מאין ליש וזיו זה מקבל מבחי' האחרונה שבעצם התענוג הפשוט שבמעש' המצות בעוה\"ז בגשמיות שע\"ז א' לעבדהולשמרה לאה\"ר בג\"ע הארץ כידוע ולזה הג\"ע בריאה יש מאין וכמ\"ש ויברא ה' גן בעדן כו' ועכ\"ז שרשו נמשך מעצמו' התענוג שבמצות בפ\"מ והוא העוה\"ב ממש רק"],[1700400140,"שיש חלוקי מדרגות בג' עולמות ג\"ע דעשי' וג\"ע דיצי' כו' ובכל עולם בחי' קבלת עול מ\"ש דוקא הוא הנק' מצות המלך בפ\"מ שרשו מגיע בכתר שבכתר שבמל' שהוא בחי' תענוג העצמי מקור כל עונג ורצון כו' ולכך בבשכמל\"ו דוקא שהוא בבחי' מל' דבי\"ע ועד רום המעלות אז קבלת עול מ\"ש דוקא שנעוץ בו תחלתן בחי' כתר שבכתר שנחשב מעצמו' המאציל כו' שהוא למעל' מבחי' כתר שרש הנאצלי' וכמ\"ש במ\"א בענין ארוממך אלהי המלך דוקא כו' ובזה יתרון מעלת יח\"ת דבשכמל\"ו על יח\"ע דשמע כו' (וגם בכל מאודך שהוא למעלה מהתפעלות רצון אינו רק בחי' מקיף בפרט ולא בכלל שלזה א' מאודך לשון יחיד אבל קבלת עול מ\"ש מגיע למעלה יותר והוא בעצמו' ממש שלא נק' מקיף כלל וכלל וכמ\"ש במ\"א בענין ואלה דברי דוד האחרונים מכלל דאיכא ראשונים דכתר מל' הן ע' שנין דאה\"ר נק' ראשונים אבל כתר שבכתר הוא כתר ש\"ט דמשיח נק' אחרוני' שנא' ע\"ז עד דוד הגדיל כמו עצמו' אא\"ס וכן חי וקיים לעד וכמ\"ש ה' ימלוך לעולם ועד כו' והוא בשכמל\"ו בקול רם קול גדול כו' (ובזה יתורץ דבשכמל\"ו ולמעלה מבכל מאודך שא' משה בלא בשכמל\"ו ומ\"ש במשיח וגבה מאד למעלה מבחי' כתר תורה וכתר מלכות שהרי הוא למעלה מבחי' אדם כמ\"ש במ\"א וד\"ל):\n(כו) <b>ומעתה</b> יובן ענין הנ\"ל בפי' אתה הראת לדעת כו' שזהו דוקא בפעולות ה' במדת מל' להוות עולם הנפרד יש מאין דוקא שמזה דוקא יכירו וידעו בבחי' מהות ועצמו' אא\"ס ממש מאחר שעיקר בחי' התהוות יש מאין הוא מבחי' המל' ובמדה זו נעוץ תחלת הרצון הפשוט עד רום המעלות א\"כ דוקא בבחי' מל' דמל' דעשי' שמהווה הגלגלי' יש בזה הארת עצמו' אא\"ס שבמל' דא\"ס שנעשה כתר דאצי' כו' כמ\"ש ראו כי אני אני כו' אני ראשון כו' דנעוץ תחלת הכל בסוף הכל דוקא ואמנם בבחי' מל' דוקא והוא בקבלת עול מ\"ש דצבא השמי' ופנימי' המקור לזה הוא קבלת עול מ\"ש דמצות כנ\"ל בפי' ואלה דברי דוד האחרונים כו' וכמארז\"ל בענין הקים על הקים עולה של תורה כו'). לזה הטעם יש לאדם להרגיל א\"ע להעמיק דעתו בתחלה רק בהתבוננות פשוטה בבריאת שמי' וארץ וכל צבאם מן הרוחניות אל הגשמיות מאין ליש בפ\"מ כמו שא' שאו מרום כו' וראו מי ברא אלה אלה דוק' וזהו עיקר שבחו של מקו' בכל פסוקי' דס' תהלים ובפסד\"ז שמזה ידע ויכיר בעצמו' אא\"ס ממש כי כל ההשתלשלות דקו באבי\"ע הנק'' התלבשות הפרצופי' בפרט אינו רק לאחזאה כו' דמצד עצמו לאו מכל אינון מדות כלל ואין שינוי כלל כי' וא\"כ מל' דעשי' מאחר שהוא בחי' אלקית ממש שנק' בורא שהוא קדמון לכל כו' אין לו תחלה כו' ה\"ז כמו בחי' מל' דא\"ס עצמו כי טרם שעלה ברצונו להאציל ולברוא ולעשות הי' הוא לבדו וגם כשהאציל וברא ועשה הכל א' לגבי עצמותו ממש ואותו הרצון במלוכה בעצמותו הוא שנשתלשל וירד מעצמותו באבי\"ע עד מל' דעשי' הכל רק מח' א' שעלה ברצונו בלי שינוי כלל לגבי' בין אצי' ועשי' כו' וא\"כ המתבונן בבחי' כח אלקי דמל' דעשיה שמהוה השמים וכל צבאם והארץ מבחי' חיצונות הכלי' דע\"ס דמל' כו' (וכן בג\"ע הארץ בבחי' הפנימית כמשי\"ת) ה\"ז כמו שמתבונן ממש בעצמות אא\"ס שלפני האצילות בלי שינוי כלל והיינו מ\"ש בזהר למינדע ליה לקוב\"ה ממש גם שהוא מצד פעולת שם אד' דמל' דעשי' הרי ע\"ז אמ' כי ה' הוא האלקי' עד רום המעלות ואדרבה ע\"י קבלת עמ\"ש מעורר לתחלת הכל שבעצמות ממש וכמ\"ש בזהר ע\"פ בזאת יבא אהרן כו' וכן זה השער לה' דא תרא לאעלא' כו' דהמל' נק' פתח ושער להדבק בעצמו' ממש וד\"ל וכל שאינו מרגיל א\"ע בהתבוננו' זאת בקביעות"],[1700400141,"בנפשו ביסוד ושרש חזק כל יגיעו בהתבוננו' בפרטית ההשתלשלו' דע\"ס דאצילות באו\"כ ולמעלה מעלה לא יוקבע בנפשו כלום כידוע) וסדר התבוננות זאת ידוע למתחילי' שהוא מענין התהוות צורת הד\"י מן המזלות והמזלות נחשבי' בערך גשמיות לגבי הגבוהי' עליהם שהוא חיצוניות השפע מהאופנים וכך למעלה מעלה מקבלין דין מן דין עד בחי' מל' דעשי' שנק' עילת העילות ובחי' מל' דמל' דעשיה מקור המשפיע לכל עולם העשי' כמ\"ש בע\"ח והנה פרטי ענין י\"ס דעשי' וי\"ס דיצי' ובריאה יובן בקיצור עד\"מ באדם התחתון כשאדם רוצה לעסוק באיזה עסק בפ\"מ כמו לבנות בנין או להנהיג דבר בפ\"מ שבודאי יש בעסק ומעשה זאת שכל ומדות ומחשבה ודבור והכל מלובש בעשי' זאת והשכל הוא הראשון שבלתי שכל והתחכמות לא ידע איך יהי' סדר ואופן המעשה והעסק כלל והשכל הזה אינו נק' שכל וחכמ' בעצם רק שכל וחכמ' השייך רק למעשה זו בלבד ונק' שכל שבעשי' לבד כמו חכמת מעשה רוקם ואורג ושכל וחכמ' מעשה הבנין וכל מלאכה שנק' המתחכ' בה בהם חכם לאותו הדבר וכמו במלאכת המשכן שנא' ובלב כל חכם לב כו' והחכמ' הזאת הגם שאינה רק בעשי' מ\"מ חכמ' ושכל יחשב ויש לו שרש מעצם כח החכמ' שבנפש כשאר חכמו' שבמוחו שבאין במדו' ומחו\"ד וכה\"ג רק שבעשי' זו הושפלה יותר (כי שרשה מעשי' שבשכל דהיינו מה שיש בכח השכל להשכיל בענין עשי' אח\"כ נמשך מזה שכל וחכמ' ממש בשעה שבא לידי מעשה כו' וכן מדבור ומח' ומדו' שבשכל נמשך חכמ' שבדבור ומחשבה ומדות כו') והנה מן השכל הזה שנק' התחכמות בא לידי השגה באורך ורוחב שנק' בינה דעשי' והוא בחי' ההתרחבו' בכל פרטי עניני טעמי' מסבירי' לזה השכל והכל אינו רק הנוגע למעשה בלבד כמו שהמדות אוי\"ר כו' נולדי' בלב מן השכל שבמוח כך המדות השייכי' לעשי' כמו לעשות באופן של חסד בהתפשטות או לעשות באופן של דין וצמצום או הממוצע מבין שניהם כו' הכל נמשך מגזירת השכל והחכמ' שבעשי' זו כחכמ' מעשה רוקם שיאריך או יקצר לפי גזירת השכל וכן במעשה הבנין וכן במעשה כל עסק יש בזה בחי' המדות חו\"ג והממוצע כידוע ולפי אופן המדות יגזור הדבור ומח' שבעשי' זו שיחשוב וידבר ויצוה במעשה זו בכל פרטיה ונמצא שעיקר הראשון הוא הרצון לעשי' זו והשכל יבא לגלות אותו עפ\"י טעם וחכמ' ויומשך למדות ומח' ודבור עד שנעשה בפ\"מ כרצונו בעשי' זו והדוגמא מזה יובן למעלה בבחי' י\"ס דמל' דעשי' שהן כח\"ב וחג\"ת כו' הנה עיקר ומקור הראשון הוא מה שעלה ברצונו לעשות העולם דעשי' בבחי' יש נפרד ממש כהשמי' וארץ וכל צבאם ובחי' רצון זה נק' כתר דמל' דעשי' ובחי' חו\"ב היינו מה שרצון זה בא לידי גלוי בחו\"ב והכל אינו רק שכל וחכמה השייך לבחי' עשי' בלבד כנ\"ל וכמו כל אשר חפץ ה' עשה כו' והכל בחכמה דוקא וכמ\"ש ה' בחכמה יסד כו' כמאמר בחכמה פותח שערים כו' ומחליף את הזמנים ומסדר כו' כמ\"ש מלך במשפט יעמיד ארץ במשפט דחכמה שב תורה וקאי על בחי' מל' דעשי' שיעמיד ארץ כמ\"ש השופט כל הארץ כו' על ע' שרים דעשיה ובשאר הברואי' בהשגחה פרטי' על כל א' כידוע בענין דע מה למעלה ממך עין רואה כו' דעיני ה' משוטטות בכל הארץ כו' והוא מבחי' חכמה שבמל' דעשי' שע\"ז אמר משמים הביט ה' כו' דהיינו שם ע\"ב דחכמה דעשי' שבבחי' מל' דווקא ע\"כ אמר משוטטות לשון נוק' וכשאמר משוטטי' לשון דכר קאי בחי' ז\"א דעשי' כמ\"ש במ\"א וכמארז\"ל י\"ב שעות הוי יום ג\"ש כו' שהן בחינת חב\"ד חג\"ת נה\"י דנוק' דז\"א דעשי' עד שזן את העולם מקרני כו' בפ\"מ וכמ\"ש הזן את העולם כולו כו' ומשפט השפע ע\"פ"],[1700400142,"חכמה שבמדות שבתורה דוקא וכמ\"ש בראשית בחוכמת' כו' (ובחי' חו\"ב די\"ס דעשי' בכללות נק' א\"א דעשי' ובחי' המדות דעשי' נק' ז\"א דעשי' ובחינת הדבור לצוות לעשות כמו ויאמר יהי רקיע כו' שנק' דבר מלך לבא בפ\"מ זה בחי' מל' שנק' נוק' דז\"א דעשי' ובפרט יש במל' דעשי' חו\"ב ומדות כו' כידוע וד\"ל) והנה ענין ג\"ע דעשי' שרש בבחי' ע\"ס דיושר דעשי' והוא בחי' עונג שבחו\"ב דמל' דעשי' (כידוע דקרקע הגן דעשי' שבקו השוה הוא נבדל בערך גם מרוחניות הד\"י שבמזלות ולכך לא נמצא שטח הג\"ע דעשי' בכדור הארץ ומ\"ש ונהר יוצא מעדן הוא ע\"ד פשוט אבל מקום זה נבדל במעלת הרוחניות למעלה הרבה גם מרוחניות שבגשם ד\"י ודצח\"ם שבכל הארץ) והענין הוא כידוע בע\"ח דמבחי' מל' דיצי' נעשה ע\"י דעשי' וביאור ענין ע\"י דעשי' הוא בחי' הענג שברצון הנבדל בערך גם משכל וחכמ' שהוא טעם לרצון לעשי' כנ\"ל ואמנם הנה בענג זה יש ב' מדריגות פנימי' וחיצוניו' בחי' חיצוניו' הענג הוא אשר חפץ לעשות יש מאין בפ\"מ והנסת' ונעלם בענג זה הוא בחי' הפנימי' שבו שהוא מקור חוצב הענג הזה הנגלה והיינו ענין זיו השכינה בג\"ע הארץ דזיו זה בא בבחי' גלוי אור לנשמות דעשי' בחי' בינה שבמל' דעשי' כידוע ושרשו מבחי' הענג העצמי שברצון שנק' כתר דעשי' בכללות והוא שרש ומקור לענג שברצון להוות העשי' בפ\"מ כו' ובחי' זיו זה מקבל מבחי' האחרונה שבעצמות התענוג הפשוט שמלובש ברצון מעשה המצות בפ\"מ בעוה\"ז דוקא שמזה נעשה תוס' אור בזיו זה תמיד כמ\"ש לעבדה שהוא ע\"י רמ\"ח מ\"ע ולשמר' לסקל האבני' וביעור הקוצים מג\"ע ולשמור מיניקות החיצונים והוא ע\"י שס\"ה ל\"ת כידוע ומפנימי' מעשה המצות בעוה\"ז נעשה העוה\"ב שלזה אמ' יפה שעה א' בתשובה ומע\"ט בעוה\"ז דווקא מכל חיי העוה\"ב לפי שזהו המקור דעוה\"ב והיינו שכר מצוה מצוה שבפ\"מ עצמה כמ\"ש במ\"א וכנ\"ל וש\"ל והדוגמא מכל זה שבבחי' ע\"ס דעשי' בכלל בפנימית וחיצונות יובן ג\"כ בבחי' ע\"ס דיצי' שנק' עולם הדבור בכלל והוא עד\"מ באדם התחתון כשמגלה רצונו בדבור לבד שאינו נוגע למעשה עדיין רק שמחשבתו באה לידי גלוי בדבורו שבוודאי יש בזה כל פרטי הי' מדרגות כח\"ב וחג\"ת כו' ועיקר ומקור הראשון הוא הרצון ואח\"כ יבא הרצון בגלוי שכל וטעם שהן בחי' חו\"ב שבדבור ומחו\"ב שבדבור יבא לידי התחלקות המדות חג\"ת וענפיהן בפרטות והכל רק בבחי' גלוי אותיו' הדבור לבד ובחי' האחרונה שבו נק' דבור שבדבור והן אותיות הדבור (ובחי' עשי' שבדבור שהוא הדבור שיבא לידי מעשה טרם שיצוה בגלוי הוא בחי' מל' דיצי' והמדות הנגלי' בדבור נק' ז\"א דיצי' וחו\"ב שבדבור נק' או\"א דיצי' ובחי' הרצון והענג שלמעלה מן השכל הבא בדבור נק' ע\"י וא\"א דיצי') ומבחי' מל' דבריא' נעשה ע\"י דיצי' והיינו מסוף מדרגה דעולם המח' נעשה תחלת גלוי הענג ורצון בדבור והוא מבחי' אותיות המח' שנכנסי' להאיר באותיות הדבור (שנק' עקבי לאה שנכנסי' תוך ראש רחל וכנ\"ל בענין מה שעשתה יראה עטרה לראשה עשתה ענוה עקב כו' וד\"ל) ובודאי מובן ממילא שכמו שע\"ס דדבור דיצי' מובדל בערך מע\"ס דעשי' שבודאי אין ערל כלל לשכל שבעשי' בפ\"מ לגבי שכל וחכמה שבדבור כשמדבר לעצמו דברי חכמ' וכן נבדלו ערך המדות שבדבור מן המדות שבעשי' ומכ\"ש ברצון וענג שנבדל ערך רצון וענג שבדבור מן ענג רצון שבפ\"מ כידוע כך אין ערך לכח\"ב וחג\"ת כו' שבדבו' לגבי כח\"ב וחג\"ת כו' שבמח' שהמח' נבדלת מצד עצם מהותה מן הדבור בכמה אופנים הא' שהמח' שבמוח מתאחד' עם עצם המוח והלב בלתי נפרד למהות בפ\"ע"],[1700400143,"כדבור והב' מצד שהמח' נחשבת בחי' העלם העצמו' וכל הכוחות דכח\"ב כלולים בה בהעלם ויכולי' להשתנות שינוי גמור גם מרצון לרצון כנראה בחוש שהרצון דמח' משתנה ובדרך כלל נק' הרצון בשם מח' ועכ\"פ נבדל הרבה ערך הרצון וענג ושכל ומדות עד דבור שבמח' הגם שהוא הבא לגלוי בדבור אבל לא נגלה עדיין מערך רצון ושכל ומדות דדבור (ולכך רק מבחי' מל' דבריאה נעשה תחלת ענג ורצון שבדבור כנ\"ל) ובחי' המדות שבמח' נק' ז\"א דבריאה וחו\"ב שבה נק' או\"א דבריאה (וכתר שבה הוא העונג ורצון שנק' ע\"י וא\"א דבריאה כו') ועד\"ז יובן ג\"כ ענין ג\"ע דיצי' שהוא פנימית הענג ורצון שבחו\"ב שבדבור וג\"ע דבריאה הוא בחי' פנימית הענג ורצון שבחו\"ב דבריאה כו' (ובחי' כלי' פנימים ואמצעי' וחיצוני' דחב\"ד חג\"ת כו' דבי\"ע הוא בחי' מט\"ט דבריאה ומט\"ט דיצי' כו' כמ\"ש בפי' יהי כבוד) ונמצא כאשר צדיק מושל ביראת אלקי' כו' שמשנה צירוף לצירוף כמו רחב\"ד שא' מי שא' לשמן כו' הרי שינוי זה הו' מגיע בשינוי רצון שבמח' דבריא' עד שבא השינוי בצירופי אותיו' דמל' דעשי' בשינוי הטבע דחומץ שנעשה כטבע שמן וכה\"ג מצינו בר\"י כה\"ג שא' יהי רצון מלפניך שיכבשו כו' שהוא שינוי רצון בכתר דבריאה מחל' דאצילות והיינו מ\"ש ישמעאל בני ברכני וכמ\"ש במ\"א וד\"ל:\n(כז) <b>ולהבין</b> ההפרש בין ג\"ע התחתון לג\"ע העליון שג\"ע התחתון בעשי' וג\"ע העליון בבריא' וידוע בפע\"ח דממעשה המצות בלא כונה בא לג\"ע התחתון ובכונה לג\"ע העליון ולכאורה עפ\"י הנ\"ל בענין קבלת עומ\"ש שבמצות יש יתרון מעלה שמגיע לבחי' כתר שבכתר שזהו למעלה גם מבחי' ענג שבחו\"ב דבריאה כו' הנה הענין יובן בהקדי' תחלה בכללו' ענין ג' עולמות בי\"ע שכללותם נרמז בבשכמל\"ו דפי' ברוך הוא מעצמות אא\"ס שבמל' דא\"ס שנמשך עד מל' דאצילות שנק' שם כמו ויעש דוד שם רק שמל' דא\"ס נק' שמו הגדול כו' כידוע וזהו ברוך שם וממל' דאצי' נעש' ע\"י דבריא' היינו פי' כבוד ופי' מלכותו הוא במל' דיצי' שבא לגלוי הדבור במהות בפ\"ע כמ\"ש דברי אשר יצא מפי כו' ולעולם ועד הוא במל' דעשי' כו' ולכאורה זהו פלא גדול דהלא ידוע המאמר דאימא מקננא בכורסייא שהוא עולם הבריאה וז\"א מקנן ביצי' ואופן שהוא המל' בעשי' (ואור אבא באצי' והיינו ד' אותיות הויה י' באצילות כו') ואיך יאמר במל' דעשי' שהוא היותר אחרון במדריגה לשון לעולם ועד שזהו מדבר לעתיד דוקא דכתיב וע\"י יתיב אזי מלכותי' מל' עלם כו' וכמשמעו' פשט הכתוב דה' ימלוך לעולם ועד כו' שהוא מדבר לע\"ל דווקא וכנ\"ל בענין ואלה דברי דוד האחרונים דהיינו כשיהי' עליי' למל' ברום המעלות בעצמו' אא\"ס ממש וכמ\"ש כי תהיו אתם ארץ חפץ וכן חפצי בה שכל חפץ עצמותו ממש בה כו' ובכאן א' בהיות בחי' המל' דאצי' בהסתר בג' עולמות בי\"ע דהיינו פי' דבשכמל\"ו כנ\"ל וגם לפי המאמר דבחי' בינה דאצילות שנק' אימא עילאה מקננא בבריאה וז\"א דאצי' ביצי' ומל' דאצילות בעשי' הרי בעשי' הוא סוף כל הצמצומים ואיך יאמר בו לשון לעולם ועד וידוע דועד בחילופי אתוון דאחד ממש (וכמשי\"ת באורך) ואם מפני שנעוץ תחלתן בסופן דוקא כנ\"ל א\"כ למה א' דאימא בכורסייא כו' אך הנה תחלה יש להבין גופו של המאמר הנ\"ל דאימא מקננא בכורסייא כו' בהיות ידוע דג' עולמו' בי\"ע כל א' כלול מבי\"ע ונק' חב\"ד חג\"ת נה\"י דעשי' בי\"ע דעשי' ונמצא בריאה שבעשי' חב\"ד דעשי' ויצי' שבעשי' חג\"ת דעשי' ועשי' דעשי' נה\"י דעשי' וכן ביצי' כלול מבי\"ע שהן חב\"ד כו' בריאה שביצי' חב\"ד דיצי' ויצי'"],[1700400144,"דיצי' חג\"ת דיצי' ועשי' דיצי' נה\"י דיצי' וכן בבריאה בריאה דבריאה חב\"ד דבריאה ויצי' דבריאה חג\"ת דבריאה ועשי' דבריאה נה\"י דבריאה ודרך כללות חב\"ד בבריאה וחג\"ת ביצי' ונה\"י בעשי' והיינו פי המאמר בכללות דאימא בכורסייא שהוא חב\"ד דבריאה וז\"א בחי' חג\"ת ביצי' ואופן בחי' נה\"י בעשי' ואמנם הנה זאת המדריגה הנק' עשי' דעשי' שהוא נה\"י שבנה\"י בכלל הוא בחי' נה\"י דעולם העשי' ובפרט הוא בחי' עשי' דעשי' שבכל עולם והוא היותר אחרון ואין בו מבחי' חב\"ד וחג\"ת כלל הגם שחב\"ד וחג\"ת שבנה\"י נק' בריאה ויצי' שבעשי' אבל בעשי' דעשי' שהוא נה\"י שבנה\"י אין בו מבחי' בריאה ויצי' שהן חב\"ד וחג\"ת כלל וכמו\"כ יובן גם למעלה באצילות עצמו שכלול מג' אלה בי\"ע דהיינו חב\"ד בריאה דאצילות וחג\"ת יצי' שבאצילות ונה\"י עשיה דאצילות ונה\"י שבנה\"י עשי' דעשי' דאצילות (שנק' מל' שבמל' ויש בחי' זו בכל מציאת בפרט כמו גם בשכל ומדות וגם ברצון ותענוג שהרי בח' השפע דמדות נק' נה\"י ואמנם שפע זו הבא בירכין שהן נבדלין מגופן של מדות שבלב נק' נה\"י שבנה\"י לגבי כליות יועצות כו' ואין בהן מבחי' המוחין וחג\"ת שבכליות יועצות כלל וז\"ש ויגע בכף יריכו כידוע וכן ענין בדי ערבות שאין בהם טעם כו' רק חיצוניות דחיצוניות מאיר ממוחי' וחג\"ת בנו\"ה דירכין כמו בריקוד ע\"י שמחה שבלב כמ\"ש במ\"א וכך בשכל הסכם הדבר להן ולאו שמסתלק גוף אור השכל והמדו' שבו רק ההסכם החזק שבמוחו לבד ואין זה דומה להסכם מדת הנצוח שיש בה טעם אור האהבה והשכל בהעלם עכ\"פ כו' והיינו נצח ענף החסד שנק' נו\"ה משא\"כ נו\"ה שבשכל הנק' הסכם שדעתו חזק כיקום שברגליו נק' נה\"י שבנה\"י וכן בהסכם חזק שברצון בפ\"מ נק' עשי' דעשי' אעפ\"י שאין בו מדו' ושכל גם לא ממדות ושכל השייך למעשה זו שרוצה בו רק רצון למעשה בלבד וכן בענג המוטבע בהרגל שלא יוכל לשנותו כו') ומובן ממילא דבחי' בי\"ע שבאצילות הוא מקור לג' עולמות בי\"י בכלל דהיינו בריא' שהו' חב\"ד דזו\"נ דאצילות נעשה מקור לבריאה שהן ע\"ס דבריא' כו' ויצי' שבאצילות מקור לע\"ס דיצי' ועשי' שבאצילות שהוא נה\"י דזו\"נ נעשה מקור לע\"ס דעשי' ודרך פרט הרי בעשי' דאצילות כלול מבי\"ע והיינו בחי' למ\"ד כלים דז\"א פנימי ואמצעי וחיצון שמקבל' המלכות והן שלשי' מעלות שהמל' כו' ונק' שלשים הגבורים העוזרי' לדוד ונעשין מזה נר\"ן בבי\"ע ע\"י בחי' המל' דוקא דהיינו מבחי' עשי' דעשי' דאצילות שבחי' מל' דכל ספי' דז\"א נק' עשיי' שבו וידוע דספי' חכמ' שבמל' נעשה ממל' שבחכמ' דז\"א וכן ספי' חסד דמל' נעשה ממל' שבחסד דז\"א הרי ע\"ס דמל' נק' עשי' דעשי' וכלול' מי\"ס חב\"ד כו' שהן בי\"ע והן הנעשי' נר\"נ בבי\"ע ע\"ד זה שע\"ס דבריאה ששרשם מפנימי' הכלים דז\"א והוא בחי' חב\"ד דמל' נמשך מזה שרש להתהוות נשמו' ומלאכי' דבריאה והיינו אימא מקננא בכורסייא כו' וע\"ס דיצי' שרשם מאמצעית הכלים דזףא והוא חג\"ת דמל' מזה שרש לנשמות ומלאכים דיצי' וחיצוניות הכלים דז\"א בע\"ס דעשי' שרש לנשמו' ומלאכי' דעשי' ונק' נר\"ן בכלל נשמה בחי' מוחין בבריאה ורוח מדות ביצי' כו' ובפרט יש נר\"נ בכל עולם עד נשמות ומלאכים דעשי' שהן בחי' נפש דעשי' כידוע והנה ידוע דג' עולמות בי\"ע הן בחי' מח' דבור ומעשה וכאשר אנו אומרים שבצי' יש ג' מדרגות דבי\"ע היינו בחי' מחדו\"מ שבאצי' עצמו שהן מחדו\"מ שבזו\"נ עצמו קודם שירדו למטה כו' ובחי' מח' דחב\"ד דז\"א ונוק' נק' בריאה שבאצילות ובחי' דבור דזו\"נ שבאצי' עצמו נק' יצי' דאצי' ובחי' מעשה דזו\"נ דאצילות נק' עשי' שבאצילות ובאין למטה בג' עולמות בי\"ע"],[1700400145,"והן ע\"ס דבי\"ע להתהוות מציאו' העולמו' כנ\"ל וכאש' אנו אומרי' דכל עולם כלול מבי\"ע היינו שבמח' כלול בג' אלה בי\"ע שהן מחדו\"מ וכן בדבור דיצי' כלול ממחדו\"מ וכן בעשי' כלול ממחדו\"מ עד עשי' דעשי' סוף הכל ויש עשי' דעשי' בכל עולם בפרט כמו עשי' דעשי' שבמח' ועשי' דעשי' דדבור ועשי' דעשי' דמעשה שנק' נה\"י שבנה\"י שאין בו מבחי' חב\"ד וחג\"ת שהן בריאה ויצירה דעשיה כלל רק עשי' דעשי' לבד כנ\"ל והרי מובן ממילא דעשי' דעשי' דאצילות היותר אחרון באצילות הוא בחי' מל' דמל' כלול מכל אשר יצא לגלוי בג' עולמות בי\"ע שהוא בחי' נר\"נ שלהם כנ\"ל והיינו ג\"כ פי' בשכמל\"ו שהוא שרש בנין המל' כנ\"ל וד\"ל והנה להבין כ\"ז דרך פרט הנה תחלה יש להבין בבחי' ומדריגה האחרונה יותר שהוא בחי' עשי' דעשיה שנק' נה\"י שבנה\"י כו' שבסוף עולם העשי' וישנו בכל עולם בפרט כנ\"ל דהנה בחי' עשי' עצמ' הוא כח התנוע' חיצוניו' הבאה בגלוי מכח הפועל או מצייר בידו ועושה דבר מה שכח זה אינו נבדל ונפסק כלל מעצם רוחניות הכח להניע שביד ולהיותו בא בפעולה ומעשה נק' בחי' עשי' שבכח זה משא\"כ בהיותו נגלה בלי התפשטו' בדבר הנפעל רק כמו גלוי תנועת היד בלא מלאכה כלל רק בכפיפה או בקמיצה וכה\"ג בהאברי' כולם כשפועלים פעולתם או כשהן בעצם כחם בגלוי כמו תנוע' הרגל טרם שתתפש' במעש' ההילוך וכה\"ג אך מה שנמצא בכח היד ורגל לפעול במעשה נק' ו\"כ בחי' עשי' שבו והוא בחי' מקור לגלוי התפשטותו בפ\"מ כידוע ועכ\"פ לא נבדל התפשטו' כח הבא בפ\"מ מכח עשי' הרוחני שביד כו' (ועד\"ז יובן גם בעשי' שבשכל ומדו' שהוא הסכם השכל למעשה דוקא יש בו ב' מדריגות הללו והוא מה שהוסכם בשכלו לעשות מעשה ואם לא יתכן המעשה בפ\"מ מעצם השכל רק ע\"י התלבשות במדות ומחשבה כו' מ\"מ אנו מוצאים שמתלבש בגלוי פועל תנועת היד כפי הסכם השכל שבמוחו והוא במעשה הרמז שמרמז בידו לעשות כהוראת השכל דוקא וכמו ציור אופן האותיות הנפעל בידו כהורא' השכל במעשה רוקם וכה\"ג בכל מלאכת חכמ' שנק' שכל שבעשי' ששרשו מעשי' שבשכל כידוע בענין הרמז שאינו אלא ביד דוקא ובסוף היד שהן פרקי האצבעות לפי שביד ג' פרקי חב\"ד חג\"ת כו' בחי' נה\"י שהי' העשי' בגשם הפעולה של היד ואמנם בפרק זה האחרון יש בו בחי' חב\"ד דעשי' שמגיע בחב\"ד שבמוח בלי שום הפסק ביניה' ויותר בקירוב ממוחי' שבראש למדות שבלב וכה\"ג שהרי מיד שיסכים השכל ירמז כך במהירות עצומה בלי הפסק ביניהם כמו פועל היד מכח הפועל וכן יספק ביד אל יד בשמחה ששמח במוח דוקא או להיפך יספוק כפיו ביגון בבשורה רעה ששומע במוח כו' וכמ\"ש במ\"א) וזהו ההפרש בכלל בין עשי' לעשי' דעשי' דבחי' עשי' עצמה אינה נבדלת מכח הפועל אבל עשי' דעשי' הוא כח הנבדל ונפסק מכח התנועה שביד לגמרי כמו ע\"ד דוגמא הזורק אבן בכח שבידו שהאבן הולך מחמת כח הזריקה למרחו' ואינו נופל לארץ רק בכלות כח הזריק' לגמרי כידוע והאבן הדומם הזה שטבעו ליפול ודאי הילוכו הוא מכח היד הרוחני שנושאו ומוליכו (וכחץ הנזרק שלא מכח אדם (ואמנם לא שהאבן נעשה עצם מהותו מכח זה רק שנישא ע\"י משא\"כ בכח העוש' דבר ולזה לא יקרא רק בשם התלבשות ולא בשם התפשטות כהתפשטו' הפעולה דהיינו שכח רוחני הנבדל מן הזורק מלביש לאבן מכל צד (בבחי' מקיף בהעלם כמ\"ש במ\"א ונישאו עד כלות כח זה יפול ממילא וזהו דוגמא לענין בחי' עשי' דעשי' שגם שנשיא' האבן לא נק' בשם עשי' בפעול מ\"מ פעול' זריק' זו שמצד כח היד באה נק' עשי' דעשי' כי נבדל ונפס' מכח התנועה הנגלי' שבאה ביד שנק' עשי' כניצוץ"],[1700400146,"הנבדל והולך מן השלהבת שאינו דומה למדליק נר מנר עצמו אחר שכבר נבדל ואינו מקבל כלל ממקור חוצבו (וכבריכת מים שנפסקה מן הנה' כמשי\"ת] ואין כאן שינוי המהות בכח זה שבהתלבשו' לנשאות האבן באויר יותר מעצם כח היד כלל רק שנבדל ונפסק כניצוץ הנבדל כנ\"ל משא\"כ בפועל היד עצמו במלאכת דבר שיש בו שינוי המהות מצד עצם העשי' שעושה גשם דבר נפרד ומתפשט בו ממש כמשי\"ת בסמוך:\n[כח] <b>והנה</b> הדוגמא ממשל זריקת אבן וכה\"ג שנק' עשי' דעשי' יובן למעלה בסוף כל עולם העשי' היותר אחרון שמזה יובן בכל עולם עד בחי' עשי' דעשי' דאצילות כנ\"ל דהנה מבואר למעלה (באות כה) בענין סיבוב הגלגלי' שזהו השתחואה שלהם ברוחניות כו' ואמנם מה שלא יסבו בלכתן בלי נטיה כלל כו' אין זה מכח עצמה ולא מצד בחירתם עפ\"י הרוחניו' דנפש שלהם כאדם ההולך כו' אלא מוכרחים בסיבובם מצד כח האחקי המלובש בהם בבחי' מקיף כמשל כח הזריקה שמלביש לאבן הנזרק שהולך האבן מכח זה רק כפי אופן המוליך בלי נטי' כלל לימין ושמאל כו' ולכך נק' כוכבי לכת כידוע [וראי' ממה שמסדר הכוכבי' במשמרותיהם כרצונו דוקא כמאמר נטל מזל כימה כו' וכן ממה שא' לר\"א ב\"פ בעית דאיהפכת לעלמא כו' שהוא עונם המזלות כו' כמ\"ש למעל'] וזהו הנק' בחי' עשי' דעשי' שנמשך מכח האלקי דהיינו הנק' בחי' מל' שבמל' דעשי' כנ\"ל והוא בא בבחי' ריחוק והפסק מעצם כח האלקי שבבחי' עשי' הנק' מל' דעשי' (אך מ\"מ אין המשל דומה עם הנמשל שבאבן אין גופו נעשה מכח המוליכו כנ\"ל אבל הגלגלי' וכה\"ג גופן נעשה ונתהווה יש מאין מכח האלקי הזה הנק' מל' דמל' דעשי' בכלל ובאמת הרי נא' לשון עשי' בפ\"מ בשמי' וארץ כמו אף ידי יסדה ארץ וימיני כו' ונק' מעשה ידיו ממש כמו מעשה ידיו של אדם למטב שחס על איבודן מצד שבאו מיגיע כפיו שנמשך כחו בהם כך הקב\"ה חס על מעשה ידיו כמ\"ש ורחמיו על כל מעשיו ולכך זנם ומפרנס' לכל הברואי' מקרני כו' וכמ\"ש גבי ננוה שהוא חס על אדם ובהמה כו' וכן גבי קרי\"ס שא' מעשה ידי טובעי' כו'] והענין הוא דבחי' עשי' הנזכ' למעלה הוא בחי' אותיות שנק' דומה כמ\"ש בס\"י ה' אבנים בונות ק\"כ בתים כו' וכמו שבאותיות הדבור יש בחי' עשי' דעשי' שבו שהוא הבל הקול הנפרד מהפה ויוצא מופרד באויר וסליק למעלה כאבן הנישא באויר כמשי\"ת כך באותיות דעשי' יש אותיות שנבדלים מכח הפועל ולא כאותיות החותם שנחקקו מכח הפועל כבר ועומדין לעצמן שאין בהן רק רשימו בעלמא מכח הפועל וחוקק אלא כמו כח כוחו של אדם שנעשה ממש מכמו רק שנק' כח כוחו כו' כמו המניע דבר ע\"י אמצעי כלקיחה ע\"י דבר אחר כסכין וכף שפועל הסכין והכף לעשות דבר הנבדל ואמנם לא שהסכין וכף בידו אלא מכחו הנבדל עושין דרך הפסקה שנק' כח כוחו כידוע דמלאכים דסוף העשי' נק' שלוחי השפע להביא לידי הגשמה ממש ולא שהן כגרזן ביד החוצב ממש כי הן מקבלים בריחוק והפסק כדמיון הבל קול הנבדל מן הפה כו' ונמצא שזהו כזריקת אבן שמעשה הליכו בא מכח כחו של אדם הזורק אעפ\"י שאין גופו נעשה מזה כתנועת הסכין הבא מכח כוחו וכה\"ג וד\"ל) וזהו הנק' בשם עשי' דעשי' למעלה והוא מ\"ש בזהר אתוון אתגניפו כו' ולא שנגלפו בקירוב מכח העצם אלא בבחי' ריחוק והפסק כאבן הנזרק וכמ\"ש בס\"י נטל צרור מתחת כו' וזרקו (שזהו בחי' דומם דאותיות דעשי' כשנבדלו ונגלפו בבחי' כח כוחו הנ\"ל) אלא כמראה הקשת שמקבל ג' גוונין דשמש מרחוק ונק' הארה דהארה כו' כידוע כך אתגליפו אותיו' שנבראו בהן הגלגלים וכה\"ג בריחוק מכח האותיות דמל' דעשי' שנק'"],[1700400147,"אבנים בחי' דומם שבע\"ס דעשי' ולכך נק' עשי' דעשי' ולא כגליפ' אותיות החותם בדבר נבדל כשעוה שנחקק בקירוב ומ\"מ נק' חקיקה דחקיק' כמו שמצטייר ציור מציור לוח שא\"א לומר בזה גם לשון עשי' דעשי' אם אינו בא מכח אדם כלל שהרי אותיות החות' עצמו לא יש בו רק רשימו בעלמא מכח אדם אם לא שאדם בכחו חותם בשעוה ע\"י החותם הזה כחותם המלך ע\"ג הכתב כענין אשר נחתם בטבעת המלך אין להשיב ולמעל' נק' גושפנק' דמלכ' ובל' הגמ' חותמו של הקב\"ה אמת כו' וידוע שהחות' הזה הוא בבחי' מל' דוק' והוא בבחי' מל' שבמל' כמ\"ש במ\"א בענין פועל אמת שפעולתו אמת שאותיו' החותם עצמו נק' פועל אמת ומה שבפועל בחקיקתו בדב' שחוץ ממנו נק' פעולתו אמת וזהו ג\"כ ענין אין צור כאלקינו צר צורה בתוך צורה כו' שזהו ג\"כ ענין אתוון אתגליפו הנ\"ל באופן אחר דהיינו שנגלפי' אותיות העצמיי' שנק 'צורה הראשונ' בדבר נבדל ומבואר במ\"א שזהו הנק' צלם ודמות וזהו גם כן הנק' הארה דהארה אבל לא כהארה הבוקעת ע\"י המסך שבא בשינוי המהות שהרי חקיקה זו בקירוב מאותיות העצמיי' משא\"כ הדמות מצורה העצמי' בא בשינוי המהות וכן באו גווני השמש בקשת בשינוי המהות אבל לא דרך מסך גמור רק שבקשת מתגלה הגוון ובולט יותר ולכך אמר כמראה הקשת כן מראה הנגה הוא מראה דמות כו' וכמ\"כ למעלה באורך נראה אור שזהו גם כן ענין אתוון אתגליפו שבמל' להיות מקור לנבראים כידוע וד\"ל ואמנם הנה ענין הציור בלוח מכח תנועת היד אע\"פ שאינו נבדל ובכל עת יש קישור וחיבור היד בדבר הנפעל ונק' עשיה עצמה כנ\"ל (משא\"כ כח המעשה בחותם שזהו כמו ע\"י אמצעי שנק' כח כחו כנ\"ל מ\"מ יש בו שינוי המהות דכח הנשאר בלוח רושם בעלמא הוא ואין לו יחוס וערך לעצם הכח שביד שציור אופן התמונה נמשך על ידו בכל פרט הגם שבא בלוח גם כן בכל אופן פרטי שבכח התנועה הרוחניות כמו שכותב ציור תמונת אות א' יוד שע\"ג מיוחד לו כח תנועה ולקו האמצעי שבו תנועה רוחניות ביד מיוחד בפ\"ע וכמ\"ש במ\"א שהמחשבה תצייר התמונה במוח ועפי\"ז יהי' אופן תנועת היד כך למעלה פועל אמת חקיקת אותיות כפי הרצון שבמח' לעשות אותן ועכ\"ז אותיות גשמיי' הנחקקי' בלוח רק רושם רוחני יש בהם מכח היד ובזריק' אבן הגם שנק' כח נבדל מ\"מ הוא אותו כח הרוחני ממש שביד רק שיצא לחוץ מן העצם להתלבש באבן (וכך הן אותיות שנק' אבנים שיוצאים מהבל הדבור לחוץ ואתגליפו למרחוק כנ\"ל) ובזה יתרון מעלתו על ציור עצמי שבלוח רק במה שנבדל וידו מסולקת ויוכל להפריד א\"ע לגמרי (כמו דברי אשר יצא מפי לא ישוב כו' כי אם עשה את אשר כו' הרי האותיות הללו נבדלים בריחוק מן העצם וכמ\"ש במ\"א בענין י' מאמרות בכלל שאותיות יהי אור כאשר יצאו פ\"א לגילוי עומדים מוי\"ב להיות התהוות האור כו' ומ\"ש אני אענה את השמים כו' שמסדר את הכוכבים כו' משום שאין זה כאבן הנזרק או כדבור שיצא שא\"א לשנותו כו' וכמ\"ש במ\"א באריכו' בענין חידוש מע\"ב בכל יום אעפ\"י שדבר אלקינו יקום כו' ואין כל חדש משום שאין זה דבר שחוץ ממנו כדבור האדם שאין דבורו כדבורינו כו' וראי' מניסי' ונפלאות בשינויי הצירופים כמו מי שא' לשמן וידליק וכה\"ג) ע\"כ מטעם זה נק' עשי' דעשי' משא\"כ ציור הפועל שאינו נבדל וכמ\"כ באותיות עצם החותם בשעוה אינו נבדל אעפ\"י שציור השני ובשינוי המהות כי גם ציור הא' בא בשינוי המהות מכח התנועה הרוחניות בציור ולוח כנ\"ל ועכ\"ז נק' עשי' עצמה מטעם הקירוב שמהות התנועה רוחניות עצמה מתלבש בציור זה בשעה שמצייר כך אותיות החותם בשעה שחותם בו בשעוה שנק' אתוון אתגליפו גם כן כנ\"ל אבל הארה דהארה שבאה עך ידי מסך מבדיל וגם הארה דהארה מרחוק בדבר נבדל כמראה הקשת"]]});
